/// Stable runtime state for Flutter.  It contains no protocol URLs, cookies,
/// raw HTML, ticket values, or error backtraces.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CampusRuntimeStatusDto {
    pub state: String,
    pub username: Option<String>,
    pub second_factor_methods: Vec<String>,
    pub masked_phone: Option<String>,
    pub overview_available: bool,
    pub trusted_device_status: Option<String>,
    /// Indicates only that this account has an explicitly saved private-vault
    /// credential available for one bounded recovery attempt. It never
    /// contains the credential, Cookie, ticket, or private vault record.
    pub automatic_recovery_enabled: bool,
    pub error: Option<String>,
}

/// Process-local authority for disconnecting the portal connection that this
/// runtime just established and verified. It is deliberately separate from
/// `SessionCoordinator`: a TUNet login does not create an Auth account or a
/// resumable service session.
struct TunetConnectionTarget {
    client: TunetClient,
    username: String,
    local_ipv4: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum ServiceSecondFactorTarget {
    Portal,
    CampusCard,
    Electricity,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PendingServiceSecondFactor {
    target: ServiceSecondFactorTarget,
    challenge: crate::protocol::SecondFactorChallenge,
}

fn service_second_factor_retry_target(
    pending: ServiceSecondFactorTarget,
) -> ServiceSecondFactorTarget {
    pending
}

fn portal_second_factor_requires_batch_pause(
    portal_result: &Result<(), String>,
    pending: Option<&PendingServiceSecondFactor>,
) -> bool {
    portal_result.is_err()
        && pending.is_some_and(|pending| pending.target == ServiceSecondFactorTarget::Portal)
}

