#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BackendSecondFactorPlan {
    SubmitWechat(String),
    Unused,
    MissingCode,
    Unsupported,
}

pub fn backend_validation_second_factor_plan(
    methods: &[String],
    code: Option<String>,
) -> BackendSecondFactorPlan {
    let code = code.filter(|code| !code.is_empty() && code.len() <= 64);
    if methods.iter().any(|method| method == "wechat") {
        code.map(BackendSecondFactorPlan::SubmitWechat)
            .unwrap_or(BackendSecondFactorPlan::MissingCode)
    } else if methods.is_empty() {
        BackendSecondFactorPlan::Unused
    } else {
        BackendSecondFactorPlan::Unsupported
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BackendWechatSecondFactorAction {
    Submit(String),
    SendOnceThenPrompt,
    MissingCode,
    Unused,
    Unsupported,
}

pub fn backend_validation_wechat_action(
    methods: &[String],
    code: Option<String>,
    explicit_send_enabled: bool,
) -> BackendWechatSecondFactorAction {
    if !methods.iter().any(|method| method == "wechat") {
        return if methods.is_empty() {
            BackendWechatSecondFactorAction::Unused
        } else {
            BackendWechatSecondFactorAction::Unsupported
        };
    }
    match code.filter(|code| !code.is_empty() && code.len() <= 64) {
        Some(code) => BackendWechatSecondFactorAction::Submit(code),
        None if explicit_send_enabled => BackendWechatSecondFactorAction::SendOnceThenPrompt,
        None => BackendWechatSecondFactorAction::MissingCode,
    }
}

#[cfg(test)]
mod standalone_validation_tests {
    use super::*;

    #[test]
    fn backend_repair_wechat_code_is_submitted_only_when_challenge_requires_it() {
        let methods = vec![String::from("wechat")];
        assert_eq!(
            backend_validation_second_factor_plan(&methods, Some("123456".to_owned())),
            BackendSecondFactorPlan::SubmitWechat(String::from("123456"))
        );
        assert_eq!(
            backend_validation_second_factor_plan(&[], Some("123456".to_owned())),
            BackendSecondFactorPlan::Unused
        );
        assert_eq!(
            backend_validation_second_factor_plan(&methods, None),
            BackendSecondFactorPlan::MissingCode
        );
        assert_eq!(
            backend_validation_second_factor_plan(
                &[String::from("sms")],
                Some("123456".to_owned())
            ),
            BackendSecondFactorPlan::Unsupported
        );
    }

    #[test]
    fn backend_repair_explicit_wechat_send_happens_only_after_challenge_without_code() {
        let methods = vec![String::from("wechat")];
        assert_eq!(
            backend_validation_wechat_action(&methods, Some("123456".to_owned()), true),
            BackendWechatSecondFactorAction::Submit(String::from("123456"))
        );
        assert_eq!(
            backend_validation_wechat_action(&methods, None, true),
            BackendWechatSecondFactorAction::SendOnceThenPrompt
        );
        assert_eq!(
            backend_validation_wechat_action(&methods, None, false),
            BackendWechatSecondFactorAction::MissingCode
        );
        assert_eq!(
            backend_validation_wechat_action(&[], Some("123456".to_owned()), true),
            BackendWechatSecondFactorAction::Unused
        );
        assert_eq!(
            backend_validation_wechat_action(&[String::from("sms")], None, true),
            BackendWechatSecondFactorAction::Unsupported
        );
    }

    #[test]
    fn backend_repair_standalone_runtime_never_loads_clears_or_saves_app_session() {
        let directory =
            PathBuf::from(std::env::var("THYOU_SESSION_DIR").expect("isolated fixture"));
        let session_file = directory.join("campus-session-v1.json");
        let diagnostic = directory.join("backend-session-resume.json");
        fs::write(&session_file, "fixture-existing-session-not-readable").unwrap();
        fs::write(&diagnostic, "fixture-existing-diagnostic").unwrap();
        let cache = directory.join("cache.json").to_string_lossy().into_owned();
        let mut runtime = create_backend_validation_runtime("auto".into(), false, cache).unwrap();
        assert_eq!(runtime.status().state, "signed_out");
        assert!(!runtime.service_session_is_proven(ServiceId::Identity));
        assert!(!runtime.portal_bootstrapped);
        runtime
            .persist_resume_state(&UserIdentity {
                username: "fixture-user".into(),
                display_name: None,
            })
            .unwrap();
        runtime.logout().unwrap();
        assert_eq!(
            fs::read_to_string(session_file).unwrap(),
            "fixture-existing-session-not-readable"
        );
        assert_eq!(
            fs::read_to_string(diagnostic).unwrap(),
            "fixture-existing-diagnostic"
        );
    }

    #[tokio::test]
    async fn backend_repair_standalone_validation_rejects_missing_login_without_dispatch() {
        let directory = PathBuf::from(std::env::var("THYOU_SESSION_DIR").unwrap());
        let mut runtime = create_backend_validation_runtime(
            "auto".into(),
            false,
            directory.join("cache.json").to_string_lossy().into_owned(),
        )
        .unwrap();
        let error = run_backend_validation_batch(
            &mut runtime,
            "portal_bootstrap".into(),
            directory
                .join("results.json")
                .to_string_lossy()
                .into_owned(),
        )
        .await
        .unwrap_err();
        assert_eq!(error, "standalone_validation_requires_fresh_login");
    }
}

fn learn_failure_code(error: &crate::learn_client::LearnClientError) -> &'static str {
    use crate::learn_client::LearnClientError as Error;
    match error {
        Error::UnexpectedOrigin => "learn_response_origin",
        Error::UnexpectedPath => "learn_response_path",
        Error::UnexpectedQuery => "learn_response_query",
        Error::SessionExpired => "learn_auth_required",
        Error::Transport(_) => "learn_transport",
        Error::Csrf(_) => "learn_csrf_invalid",
        _ => "learn_response_format",
    }
}

fn info_failure_code(error: &InfoSessionError) -> &'static str {
    match error {
        InfoSessionError::NewsHttpStatus { .. } => "info_news_http",
        InfoSessionError::NewsNavigationCycle => "info_news_redirect_cycle",
        InfoSessionError::NewsNavigationLimit => "info_news_redirect_limit",
        InfoSessionError::UnexpectedOrigin | InfoSessionError::NewsUnexpectedOrigin => {
            "info_origin_rejected"
        }
        InfoSessionError::HandoffUnexpectedPath | InfoSessionError::NewsUnexpectedPath => {
            "info_mapping_rejected"
        }
        InfoSessionError::LoginRequired => "info_session_expired",
        InfoSessionError::MissingCookieCsrf => "info_csrf_missing",
        InfoSessionError::Profile(crate::info::InfoError::ResultFailureWithTarget) => {
            "info_handoff_result_with_target"
        }
        InfoSessionError::Profile(crate::info::InfoError::ResultFailureWithObject) => {
            "info_handoff_result_with_object"
        }
        InfoSessionError::Profile(crate::info::InfoError::ResultFailureWithObjectNoTarget) => {
            "info_handoff_result_object_no_target"
        }
        InfoSessionError::Profile(crate::info::InfoError::ResultFailureWithMessage) => {
            "info_handoff_result_with_message"
        }
        InfoSessionError::Profile(crate::info::InfoError::ResultFailure) => {
            "info_handoff_result_failure"
        }
        InfoSessionError::Profile(crate::info::InfoError::SuccessFlagFailure) => {
            "info_handoff_success_flag_failure"
        }
        InfoSessionError::Profile(crate::info::InfoError::ErrorFieldFailure) => {
            "info_handoff_error_field_failure"
        }
        InfoSessionError::Profile(crate::info::InfoError::MessageFailure) => {
            "info_handoff_message_failure"
        }
        InfoSessionError::Profile(crate::info::InfoError::BusinessFailure) => {
            "info_handoff_rejected"
        }
        InfoSessionError::Profile(crate::info::InfoError::LoginRequired) => "info_session_expired",
        InfoSessionError::Profile(_) => "info_handoff_envelope",
        InfoSessionError::Client(error) => info_client_failure_code(error),
        InfoSessionError::Transport(_) => "info_transport",
        InfoSessionError::SessionProofMissing => "info_handoff_proof_missing",
        InfoSessionError::HandoffStatus { .. } => "info_handoff_http",
        InfoSessionError::News(crate::info_news::NewsParseError::DetailMalformedPayload {
            field,
            reason,
        }) => match field.as_str() {
            "object" | "object.xxDto" => "info_detail_envelope",
            "bt" | "object.xxDto.bt" => "info_detail_title",
            "nr" | "object.xxDto.nr" => "info_detail_content",
            "object.xxDto.xxid" => "info_detail_id",
            "document" => "info_detail_encoding",
            "legacy.policy" => "info_detail_legacy_policy",
            "legacy.html" => "info_detail_legacy_html",
            "legacy.title" => "info_detail_legacy_title",
            "legacy.fragment" if reason == "HTML tag is not terminated" => {
                "info_detail_legacy_tag_unterminated"
            }
            "legacy.fragment" => "info_detail_legacy_fragment",
            "legacy.validation" => "info_detail_legacy_control",
            "legacy.summary" if reason == "unterminated HTML markup" => {
                "info_detail_legacy_summary_markup"
            }
            "legacy.summary"
                if matches!(
                    reason.as_str(),
                    "invalid hexadecimal HTML entity"
                        | "invalid decimal HTML entity"
                        | "invalid HTML entity code point"
                ) =>
            {
                "info_detail_legacy_entity"
            }
            "legacy.summary" => "info_detail_legacy_summary",
            "legacy.content" if reason == "reference body selector has no match" => {
                "info_detail_legacy_selector_missing"
            }
            "legacy.content" if reason == "reference-selected article body is empty" => {
                "info_detail_legacy_empty"
            }
            "legacy.content" => "info_detail_legacy_content",
            _ => "info_detail_field",
        },
        InfoSessionError::News(crate::info_news::NewsParseError::CatalogMalformedPayload {
            ..
        }) => "info_catalog_format",
        InfoSessionError::News(_) => "info_detail_parse",
        _ => "info_service_unconfirmed",
    }
}

fn info_client_failure_code(error: &crate::info_client::InfoClientError) -> &'static str {
    use crate::info_client::InfoClientError as ClientError;

    match error {
        ClientError::UnexpectedOrigin => "info_origin_rejected",
        ClientError::UnexpectedPath => "info_mapping_rejected",
        ClientError::HttpStatus { .. } => "info_handoff_http",
        ClientError::Transport(_) => "info_transport",
        ClientError::Profile(crate::info::InfoError::ResultFailureWithTarget) => {
            "info_handoff_result_with_target"
        }
        ClientError::Profile(crate::info::InfoError::ResultFailureWithObject) => {
            "info_handoff_result_with_object"
        }
        ClientError::Profile(crate::info::InfoError::ResultFailureWithObjectNoTarget) => {
            "info_handoff_result_object_no_target"
        }
        ClientError::Profile(crate::info::InfoError::ResultFailureWithMessage) => {
            "info_handoff_result_with_message"
        }
        ClientError::Profile(crate::info::InfoError::ResultFailure) => {
            "info_handoff_result_failure"
        }
        ClientError::Profile(crate::info::InfoError::SuccessFlagFailure) => {
            "info_handoff_success_flag_failure"
        }
        ClientError::Profile(crate::info::InfoError::ErrorFieldFailure) => {
            "info_handoff_error_field_failure"
        }
        ClientError::Profile(crate::info::InfoError::MessageFailure) => {
            "info_handoff_message_failure"
        }
        ClientError::Profile(crate::info::InfoError::BusinessFailure) => "info_handoff_rejected",
        ClientError::Profile(crate::info::InfoError::LoginRequired) => "info_session_expired",
        ClientError::Profile(_) => "info_handoff_envelope",
        ClientError::HtmlPage {
            classification: crate::info_client::InfoHtmlClassification::LoginRequired,
            ..
        } => "info_session_expired",
        _ => "info_handoff_client",
    }
}

fn trace_session_reuse(service: &'static str, result: &'static str) {
    tracing::info!(target:"tsinghua_kit::auth",event="session_reuse_decision",service,reuse_result=result);
}
fn portal_probe_requires_login(reason: &str) -> bool {
    matches!(
        reason,
        "portal_resume_csrf_missing"
            | "portal_resume_login_required"
            | "portal_resource_login_required"
            | "portal_resource_http_rejected"
            | "portal_resource_webvpn_login"
            | "portal_resource_identity_login"
            | "portal_resource_document_login"
            | "portal_identity_entry_password_form"
            | "portal_resume_password_required"
    )
}

fn portal_reason_requires_interactive_auth(reason: &str) -> bool {
    matches!(
        reason,
        "portal_resume_password_required"
            | "portal_resume_trusted_password_form"
            | "portal_identity_entry_password_form"
            | "portal_identity_target_password_form"
    )
}

/// A trusted-device/SSO continuation may fail after the first probe has
/// already classified the resource as an authentication boundary.  Only a
/// current response that explicitly presents a password boundary (or rejects
/// the trusted continuation with an authentication status) may keep the
/// private-vault fallback open.  Network, rate-limit, routing, parser, 2FA,
/// and otherwise unconfirmed outcomes must close it again.
fn portal_recovery_error_allows_private_credential(reason: &str) -> bool {
    portal_reason_requires_interactive_auth(reason) || reason == "portal_resume_sso_rejected"
}

fn card_probe_allows_initial_handoff(reason: &str) -> bool {
    // Do not apply this recovery policy to card account/transaction failures,
    // malformed payloads, unknown encrypted failures, network/HTTP outages,
    // or a session resolving to a different user.
    matches!(
        reason,
        "campus_card_cookie_rejected" | "campus_card_probe_outer_failure"
    )
}

fn card_probe_reason(error: &crate::campus_card_adapter::CampusCardAdapterError) -> &'static str {
    use crate::campus_card_adapter::CampusCardAdapterError as Error;
    match error {
        Error::Transport => "campus_card_probe_network",
        Error::HttpStatus { status: 429 } => "campus_card_rate_limited",
        Error::HttpStatus { status: 503 } => "campus_card_probe_unavailable",
        Error::HttpStatus { .. } => "campus_card_probe_http",
        Error::SessionExpired => "campus_card_cookie_rejected",
        Error::AccountMismatch => "campus_card_account_mismatch",
        Error::InvalidSessionResponse => "campus_card_probe_account_missing",
        Error::InvalidEncryptedPayload => "campus_card_encrypted_payload_format",
        Error::EncryptedServiceFailure => "campus_card_service_rejected",
        Error::UnexpectedOrigin | Error::UnexpectedPath | Error::UnexpectedRedirect => {
            "campus_card_probe_route"
        }
        Error::InvalidConfig => "campus_card_probe_config",
        Error::Parse(crate::campus_card_read::CampusCardParseError::MalformedJson) => {
            "campus_card_probe_invalid_json"
        }
        Error::Parse(crate::campus_card_read::CampusCardParseError::MalformedEnvelope) => {
            "campus_card_probe_invalid_envelope"
        }
        Error::Parse(crate::campus_card_read::CampusCardParseError::MissingResultData) => {
            "campus_card_probe_result_missing"
        }
        Error::Parse(crate::campus_card_read::CampusCardParseError::OuterFailure) => {
            "campus_card_probe_outer_failure"
        }
        Error::UnexpectedResponse | Error::Parse(_) => "campus_card_probe_format",
    }
}

fn portal_roam_login_input<'a>(
    username: &'a str,
    wire_password: &'a str,
    fingerprint: &'a str,
) -> LoginFormInput<'a> {
    LoginFormInput::new(username, PasswordInput::precomputed_wire(wire_password))
        .with_fingerprint(fingerprint)
        .with_generated_fingerprint("")
        .with_captcha("")
}

fn portal_target_from_identity_evidence(
    client: &IdentityClient,
    final_url: &Url,
    status: reqwest::StatusCode,
    redirect_location: Option<&Url>,
    body: &str,
) -> Option<Url> {
    let info_origin = Url::parse(INFO_DIRECT_ORIGIN).ok()?;
    if (status.is_success() || status.is_redirection())
        && let Some(location) = redirect_location
        && portal_identity_target_allowed(location, &info_origin)
    {
        return Some(location.clone());
    }
    if !status.is_success() {
        return None;
    }
    let page = client.parse_login_page(body);
    if page.failure.is_some() || page.has_login_form || page.second_factor_marker.is_some() {
        return None;
    }
    client
        .first_static_redirect_url_for_origin(final_url, body, &info_origin)
        .or_else(|| {
            let oauth_origin = WebVpnIdentityConfig::current().oauth_origin().clone();
            client
                .first_static_redirect_url_for_origin(final_url, body, &oauth_origin)
                .filter(|url| portal_server_selected_oauth_target_allowed(url, &info_origin))
        })
}

fn portal_fresh_entry_has_terminal_failure(client: &IdentityClient, body: &str) -> bool {
    let page = client.parse_login_page(body);
    page.failure
        .as_ref()
        .is_some_and(|failure| failure.reason != LoginFailureReason::Generic)
}

fn portal_target_from_submitted_identity_evidence(
    client: &IdentityClient,
    final_url: &Url,
    status: reqwest::StatusCode,
    redirect_location: Option<&Url>,
    body: &str,
) -> Option<Url> {
    if let Some(target) =
        portal_target_from_identity_evidence(client, final_url, status, redirect_location, body)
    {
        return Some(target);
    }
    if !status.is_success() || !client.has_identity_success_marker(body) {
        return None;
    }
    let page = client.parse_login_page(body);
    if page.second_factor_marker.is_some()
        || page
            .failure
            .as_ref()
            .is_some_and(|failure| failure.reason != LoginFailureReason::Generic)
    {
        return None;
    }
    let info_origin = Url::parse(INFO_DIRECT_ORIGIN).ok()?;
    client
        .first_static_redirect_url_for_origin(final_url, body, &info_origin)
        .or_else(|| {
            let oauth_origin = WebVpnIdentityConfig::current().oauth_origin().clone();
            client
                .first_static_redirect_url_for_origin(final_url, body, &oauth_origin)
                .filter(|url| portal_server_selected_oauth_target_allowed(url, &info_origin))
        })
}

fn card_target_from_identity_evidence(
    client: &IdentityClient,
    final_url: &Url,
    status: reqwest::StatusCode,
    redirect_location: Option<&Url>,
    body: &str,
    card_origin: &Url,
) -> Option<Url> {
    if (status.is_success() || status.is_redirection())
        && let Some(location) = redirect_location
        && same_origin(location, card_origin)
        && location.username().is_empty()
        && location.password().is_none()
        && location.fragment().is_none()
    {
        return Some(location.clone());
    }
    if !status.is_success() {
        return None;
    }
    let page = client.parse_login_page(body);
    if page.failure.is_some() || page.has_login_form || page.second_factor_marker.is_some() {
        return None;
    }
    client.first_static_redirect_url_for_origin(final_url, body, card_origin)
}

fn completed_service_second_factor_handoff(
    target: ServiceSecondFactorTarget,
    client: &IdentityClient,
    response: &crate::identity_execution::IdentityHttpResponse,
    card_origin: &Url,
) -> Option<Url> {
    match target {
        ServiceSecondFactorTarget::Portal => portal_target_from_submitted_identity_evidence(
            client,
            &response.final_url,
            response.status,
            response.redirect_location.as_ref(),
            response.body(),
        ),
        ServiceSecondFactorTarget::Electricity => electricity_auth::selected_target(
            client,
            response,
            &electricity_auth::ElectricityFlow::current(),
        ),
        ServiceSecondFactorTarget::CampusCard => card_target_from_identity_evidence(
            client,
            &response.final_url,
            response.status,
            response.redirect_location.as_ref(),
            response.body(),
            card_origin,
        ),
    }
}

fn portal_oauth_redirect_url(target: &Url) -> Result<Url, String> {
    let info_origin =
        Url::parse(INFO_DIRECT_ORIGIN).map_err(|_| String::from("WebVPN 门户目标配置无效"))?;
    if portal_server_selected_oauth_target_allowed(target, &info_origin) {
        return Ok(target.clone());
    }
    if !same_origin(target, &info_origin)
        || !target.username().is_empty()
        || target.password().is_some()
        || target.fragment().is_some()
    {
        return Err(String::from("WebVPN 门户目标跳转被拒绝，请稍后重试"));
    }
    crate::portal_resume::broker_target(&WebVpnIdentityConfig::current(), target.clone())
        .map_err(|_| String::from("WebVPN 门户目标跳转被拒绝，请稍后重试"))
}

fn portal_identity_target_allowed(target: &Url, info_origin: &Url) -> bool {
    (same_origin(target, info_origin)
        && target.username().is_empty()
        && target.password().is_none()
        && target.fragment().is_none())
        || portal_server_selected_oauth_target_allowed(target, info_origin)
}

/// The current public reference client preserves an OAuth broker URL when the
/// identity success page already selected it, instead of wrapping that URL in
/// another `/lb-auth/lbredirect` request. Validate the fixed INFO authority
/// separately from the reference's raw URI tail; inner query parameters must
/// not replace broker authority fields or escape to another target origin.
fn validated_server_selected_portal_oauth(target: &Url, info_origin: &Url) -> bool {
    crate::portal_resume::validated_info_broker(
        target,
        &WebVpnIdentityConfig::current(),
        info_origin,
    )
}

fn portal_webvpn_target_allowed(url: &Url) -> bool {
    let Ok(webvpn) = Url::parse(WEBVPN_BASE_URL) else {
        return false;
    };
    same_origin(&webvpn, url)
        && url.username().is_empty()
        && url.password().is_none()
        && url.fragment().is_none()
        && (matches!(url.path(), "/" | "/login")
            || url.path().starts_with("/https/")
            || url.path().starts_with("/http/")
            || url.path().starts_with("/http-"))
}

fn portal_info_target_allowed(url: &Url) -> bool {
    let Ok(info) = Url::parse(INFO_DIRECT_ORIGIN) else {
        return false;
    };
    same_origin(url, &info)
        && url.username().is_empty()
        && url.password().is_none()
        && url.fragment().is_none()
        && url.path().starts_with("/f/info/gxfw_fg/")
}

fn portal_identity_handoff_target_allowed(url: &Url) -> bool {
    let Ok(identity) = Url::parse(IDENTITY_BASE_URL) else {
        return false;
    };
    let path = url.path().trim_end_matches('/');
    same_origin(url, &identity)
        && (matches!(
            path,
            IDENTITY_CALLBACK_PATH
                | "/do/off/ui/auth/login/check"
                | "/do/off/ui/auth/login/checkSingle"
        ) || path.starts_with("/do/off/ui/auth/login/form/"))
        && url.username().is_empty()
        && url.password().is_none()
        && url.fragment().is_none()
}

fn portal_oauth_bridge_target_allowed(url: &Url) -> bool {
    let oauth = WebVpnIdentityConfig::current().oauth_origin().clone();
    same_origin(url, &oauth)
        && url.username().is_empty()
        && url.password().is_none()
        && url.fragment().is_none()
        && (url.path() == "/lb-auth/lbredirect" || url.path().starts_with("/thu-oauth/"))
}

fn portal_server_selected_oauth_target_allowed(target: &Url, info_origin: &Url) -> bool {
    validated_server_selected_portal_oauth(target, info_origin)
        || (portal_oauth_bridge_target_allowed(target) && target.path().starts_with("/thu-oauth/"))
}

fn portal_handoff_redirect_allowed(from: &Url, to: &Url) -> bool {
    let webvpn = Url::parse(WEBVPN_BASE_URL).ok();
    let oauth = WebVpnIdentityConfig::current().oauth_origin().clone();
    let from_known_origin = webvpn
        .as_ref()
        .is_some_and(|origin| same_origin(from, origin))
        || same_origin(from, &oauth)
        || portal_identity_handoff_target_allowed(from);
    from_known_origin
        && (portal_webvpn_target_allowed(to)
            || portal_oauth_bridge_target_allowed(to)
            || portal_info_target_allowed(to)
            || portal_identity_handoff_target_allowed(to))
}

fn portal_redirect_rejection_category(url: &Url) -> &'static str {
    let Ok(webvpn) = Url::parse(WEBVPN_BASE_URL) else {
        return "unknown_origin";
    };
    let oauth = WebVpnIdentityConfig::current().oauth_origin().clone();
    let Ok(info) = Url::parse(INFO_DIRECT_ORIGIN) else {
        return "unknown_origin";
    };
    if same_origin(url, &info) {
        "info_route"
    } else if same_origin(url, &webvpn) {
        "webvpn_route"
    } else if same_origin(url, &oauth) {
        "oauth_route"
    } else if let Ok(identity) = Url::parse(IDENTITY_BASE_URL)
        && same_origin(url, &identity)
    {
        let path = url.path().trim_end_matches('/');
        match path {
            IDENTITY_CALLBACK_PATH => "identity_callback_route",
            "/do/off/ui/auth/login/check" => "identity_submit_route",
            "/do/off/ui/auth/login/checkSingle" => "identity_check_single_route",
            path if path.starts_with("/do/off/ui/auth/login/form/") => "identity_login_form_route",
            _ => "identity_other_route",
        }
    } else if url.host_str() == Some("info.tsinghua.edu.cn") {
        "info_origin_variant"
    } else if url.host_str() == Some("webvpn.tsinghua.edu.cn") {
        "webvpn_origin_variant"
    } else if url.host_str() == Some("oauth.tsinghua.edu.cn") {
        "oauth_origin_variant"
    } else if url.host_str() == Some("id.tsinghua.edu.cn") {
        "identity_origin"
    } else if url.host_str() == Some("card.tsinghua.edu.cn") {
        "card_origin"
    } else if url
        .host_str()
        .is_some_and(|host| host.ends_with(".tsinghua.edu.cn"))
    {
        "other_campus_origin"
    } else {
        "foreign_origin"
    }
}

fn debug_portal_handoff(
    stage: &str,
    status: Option<reqwest::StatusCode>,
    url: &Url,
    location: Option<&Url>,
) {
    let location_category = location
        .map(portal_redirect_rejection_category)
        .unwrap_or("missing");
    let phase = match stage {
        "selected-target" => "selected_target",
        _ => "other",
    };
    tracing::debug!(target:"tsinghua_kit::auth",event="portal_handoff",phase,http_status=status.map_or(0,|s|s.as_u16()),endpoint=crate::telemetry::endpoint(url),reason=location_category);
}

fn portal_handoff_target_allowed(url: &Url) -> bool {
    (portal_webvpn_target_allowed(url) && url.path().starts_with(INFO_TARGET_PREFIX))
        || portal_info_target_allowed(url)
}

fn portal_resume_handoff_error_message(reason: &'static str) -> &'static str {
    match reason {
        "portal_resume_second_factor_required" => "WebVPN 门户需要二次认证，请在登录页完成验证",
        "portal_resume_sso_network"
        | "portal_resume_trusted_network"
        | "portal_resume_rate_limited" => "WebVPN 门户网络连接失败，请稍后重试",
        "portal_resume_trusted_unconfirmed" => "WebVPN 门户免密码续接未确认，已保留其他会话",
        "portal_resume_trusted_password_form"
        | "portal_resume_password_required"
        | "portal_resume_identity_rejected"
        | "portal_resume_captcha_required"
        | "portal_resume_credential_page_rejected"
        | "portal_resume_identity_failure"
        | "portal_resume_sso_rejected" => "WebVPN 门户需要交互认证，已保留其他会话",
        "portal_resume_sso_route" => "WebVPN 门户目标跳转被拒绝，请稍后重试",
        "portal_resume_config" => "WebVPN 门户配置无效",
        _ => "WebVPN 门户目标页状态未确认，请稍后重试",
    }
}

/// Captcha bytes are returned only to the explicit USEREG login dialog.  The
