impl From<UseregAccountInfo> for UseregAccountDto {
    fn from(info: UseregAccountInfo) -> Self {
        Self {
            username: info.username,
            contact_email: mask_email(&info.contact_email),
            contact_phone: mask_phone(&info.contact_phone),
            contact_landline: mask_phone(&info.contact_landline),
            real_name: info.real_name,
            status: info.status,
            user_group: info.user_group,
            location: info.location,
            allowed_devices: info.allowed_devices.min(u32::MAX as usize) as u32,
        }
    }
}

