fn map_usereg_device(index: usize, device: &UseregDevice) -> UseregDeviceDto {
    UseregDeviceDto {
        index: index.min(u32::MAX as usize) as u32,
        ip4: device.ip4.clone(),
        ip6: device.ip6.clone(),
        logged_at: device.logged_at.clone(),
        auth_permission: device.auth_permission.clone(),
        mac_suffix: device
            .mac
            .rsplit_once(':')
            .map(|(_, suffix)| format!("**:{suffix}"))
            .unwrap_or_else(|| "**".to_owned()),
    }
}

fn mask_email(value: &str) -> String {
    let Some((local, domain)) = value.split_once('@') else {
        return value.to_owned();
    };
    let mut chars = local.chars();
    let Some(first) = chars.next() else {
        return format!("***@{domain}");
    };
    format!("{first}***@{domain}")
}

fn mask_phone(value: &str) -> String {
    let chars: Vec<char> = value.chars().collect();
    if chars.len() <= 4 {
        return value.to_owned();
    }
    let prefix: String = chars.iter().take(3).collect();
    let suffix: String = chars
        .iter()
        .rev()
        .take(2)
        .copied()
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .collect();
    format!("{prefix}****{suffix}")
}

fn tunet_status_dto(record: &TunetStatusRecord) -> TunetNetworkStatusDto {
    let state = match record.online_state() {
        TunetOnlineState::Online => "online",
        TunetOnlineState::Offline => "offline",
        TunetOnlineState::Unknown => "unknown",
    };
    let signal = match record.signal {
        TunetStatusSignal::Positive => "positive",
        TunetStatusSignal::Negative => "negative",
        TunetStatusSignal::Unknown => "unknown",
    };
    TunetNetworkStatusDto {
        state: state.to_owned(),
        online: record.online_state() == TunetOnlineState::Online && record.is_positive(),
        signal: signal.to_owned(),
    }
}

fn classroom_slot_status_name(status: &ClassroomSlotStatus) -> String {
    match status {
        ClassroomSlotStatus::Free => "free".to_owned(),
        ClassroomSlotStatus::Occupied => "occupied".to_owned(),
        ClassroomSlotStatus::Exam => "exam".to_owned(),
        ClassroomSlotStatus::Borrowed => "borrowed".to_owned(),
        ClassroomSlotStatus::Disabled => "disabled".to_owned(),
        ClassroomSlotStatus::Unknown { class_name } => {
            format!("unknown:{class_name}")
        }
    }
}

