fn map_classroom_state(
    result: crate::classroom_read::ClassroomStateResult,
) -> ClassroomStateResultDto {
    ClassroomStateResultDto {
        valid_week_numbers: result.valid_week_numbers,
        current_week_number: result.current_week_number,
        dates_of_current_week: result.dates_of_current_week.into_iter().collect(),
        classroom_states: result
            .classroom_states
            .into_iter()
            .map(|state| ClassroomStateDto {
                name: state.name,
                statuses: state
                    .status
                    .iter()
                    .map(classroom_slot_status_name)
                    .collect(),
            })
            .collect(),
    }
}

