fn map_learn_course(record: &LearnCourseRecord, fallback_semester: &str) -> Option<LearnCourseDto> {
    let course_id = record
        .id()
        .map(str::trim)
        .filter(|value| !value.is_empty() && !value.chars().any(char::is_control))?
        .to_owned();
    let title = record
        .title()
        .map(str::trim)
        .filter(|value| !value.is_empty())?
        .to_owned();
    let optional = |value: Option<&str>| {
        value
            .map(str::trim)
            .filter(|value| !value.is_empty() && !value.chars().any(char::is_control))
            .map(str::to_owned)
    };

    Some(LearnCourseDto {
        course_id,
        course_code: optional(record.code()),
        title,
        instructor: optional(record.instructor.as_deref()),
        semester: optional(record.semester.as_deref()).or_else(|| {
            (!fallback_semester.trim().is_empty()).then(|| fallback_semester.to_owned())
        }),
    })
}

fn map_exam_record(record: RegistrarExamRecord) -> CampusExamDto {
    let weekday = match record.schedule.weekday {
        RegistrarExamWeekday::Monday => "monday",
        RegistrarExamWeekday::Tuesday => "tuesday",
        RegistrarExamWeekday::Wednesday => "wednesday",
        RegistrarExamWeekday::Thursday => "thursday",
        RegistrarExamWeekday::Friday => "friday",
        RegistrarExamWeekday::Saturday => "saturday",
        RegistrarExamWeekday::Sunday => "sunday",
    };
    let session = match record.schedule.session {
        RegistrarExamSession::Morning => "morning",
        RegistrarExamSession::Afternoon => "afternoon",
        RegistrarExamSession::Evening => "evening",
    };

    CampusExamDto {
        course_code: record.course_code,
        course_sequence: record.course_sequence,
        course_name: record.course_name,
        exam_month: record.schedule.month,
        exam_day: record.schedule.day,
        exam_weekday: weekday.to_owned(),
        exam_session: session.to_owned(),
        schedule_raw: record.schedule.raw,
        location: record.location,
        department: record.department,
        category: record.category,
        instructor: record.instructor,
        headcount: record.headcount,
    }
}

fn map_exam_report(records: Vec<RegistrarExamRecord>) -> CampusExamReportDto {
    let exam_count = records.len().try_into().unwrap_or(u32::MAX);
    CampusExamReportDto {
        stage: "undergraduate".to_owned(),
        exam_count,
        exams: records.into_iter().map(map_exam_record).collect(),
        generated_at: Some(Utc::now().to_rfc3339()),
        source: Some("live".to_owned()),
        status: Some("ready".to_owned()),
        error: None,
    }
}

fn map_exam_report_with_provenance(
    records: Vec<RegistrarExamRecord>,
    generated_at: String,
    source: &'static str,
    status: &'static str,
    error: Option<String>,
) -> CampusExamReportDto {
    let mut report = map_exam_report(records);
    report.generated_at = Some(generated_at);
    report.source = Some(source.to_owned());
    report.status = Some(status.to_owned());
    report.error = error;
    report
}

