    /// Read one stage's steps using only a task selector from the complete,
    /// recent THOS phases list in this account-bound Runtime.
    pub async fn load_thos_phase_steps(
        &mut self,
        task_id: String,
        force_refresh: bool,
    ) -> Result<super::thos::ThosPhaseStepsDto, String> {
        crate::telemetry::observe(
            "info",
            "load_thos_phase_steps",
            thos_runtime::read_phase_steps(self, task_id, force_refresh),
        )
        .await
    }

    pub async fn load_overview(&mut self, date: String) -> Result<CampusOverviewFacadeDto, String> {
        self.load_overview_with_refresh(date, false).await
    }

    /// Explicit user refresh bypasses a fresh cache, but never bypasses the
    /// transport gate, account binding, service proofs or bounded recovery.
    pub async fn refresh_overview(
        &mut self,
        date: String,
    ) -> Result<CampusOverviewFacadeDto, String> {
        self.load_overview_with_refresh(date, true).await
    }

    async fn load_overview_with_refresh(
        &mut self,
        date: String,
        force_refresh: bool,
    ) -> Result<CampusOverviewFacadeDto, String> {
        crate::telemetry::observe("overview", "load_overview", async {
            self.allow_live_operation()?;
            let date = NaiveDate::parse_from_str(&date, "%Y-%m-%d")
                .map_err(|_| String::from("日期格式无效"))?;
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            self.apply_reference_academic_stage(&user);

            // Hydrated overview data follows the same rule as the Reference
            // client's persisted Redux state: a validated value for the
            // requested day is usable before any downstream handoff.  The
            // path is account+stage scoped and does not require the live
            // semester to be rediscovered after a process restart.
            let overview_cache = JsonFileCache::<CampusOverviewCachePayload>::new(
                overview_cache_path_for_account_stage(&self.cache_path, &user.username, self.stage),
                CAMPUS_OVERVIEW_CACHE_SCHEMA_VERSION,
                CAMPUS_OVERVIEW_CACHE_SERVICE,
            );
            let configured_overview_semester = if self.semester != AUTO_SEMESTER {
                self.semester.clone()
            } else {
                self.semester_config.trim().to_owned()
            };
            let cached = read_account_bound_overview_cache(
                &overview_cache,
                &user.username,
                self.stage,
                date,
                &configured_overview_semester,
                SystemTime::now(),
            );
            let stale_cache = (cached.status == "stale"
                || (force_refresh && cached.status == "ready"))
                .then(|| {
                    let mut fallback = cached.clone();
                    fallback.status = "stale".to_owned();
                    fallback
                });
            if cached.status == "ready" && !force_refresh {
                self.last_error = None;
                return Ok(cached);
            }

            let mut learn = self.service_session_is_proven(ServiceId::Learn);
            let mut registrar = self.service_session_is_proven(ServiceId::Registrar);

            // A stale hydrated value is immediately useful when the primary
            // Identity proof is absent.  Once Identity is already proven,
            // however, a stale overview should get the same one-shot lazy
            // Learn/Registrar refresh opportunity as a cache miss; a failed
            // handoff or read still falls back to this explicitly stale DTO.
            if stale_cache.is_some()
                && !learn
                && !registrar
                && !self.service_session_is_proven(ServiceId::Identity)
            {
                let _ = self.try_restore_identity_for_cache_refresh().await;
                if !self.service_session_is_proven(ServiceId::Identity) {
                    self.last_error = None;
                    return Ok(stale_cache.expect("stale cache checked above"));
                }
            }

            // A cache miss, or a stale cache for which an already-proven live
            // academic service is available, is the first point at which the
            // current Identity proof is required.  The account context above
            // may be recovered from an expired snapshot/metadata, but it is
            // never sufficient to authorize a live handoff.
            if !self.service_session_is_proven(ServiceId::Identity) {
                user = self.ensure_identity_user_for_live_read().await?;
                self.apply_reference_academic_stage(&user);
            }

            // Cache miss (or a stale cache with an already proven service) is
            // the only point at which the Rust runtime may establish the
            // academic services.  Flutter never performs this handoff before
            // asking for the overview.  Learn is established first because
            // the current Registrar WebVPN proof is obtained from its shared
            // INFO/academic route; an existing independent Registrar proof
            // remains usable if Learn is unavailable.
            if !learn && !registrar {
                if self
                    .establish_service_session(String::from("learn"))
                    .await
                    .is_err()
                {
                    if let Some(stale) = stale_cache.as_ref().cloned() {
                        self.last_error = None;
                        return Ok(stale);
                    }
                }
                learn = self.service_session_is_proven(ServiceId::Learn);
                registrar = self.service_session_is_proven(ServiceId::Registrar);
            }
            if !registrar && self.service_session_is_proven(ServiceId::Learn) {
                // Keep the already proven Learn source available if the
                // independent Registrar handoff fails.  The live resolver
                // can still return a partial overview; a stale cache is only
                // selected after that live partial attempt fails.
                let _ = self
                    .establish_service_session(String::from("registrar"))
                    .await;
                registrar = self.service_session_is_proven(ServiceId::Registrar);
            }

            if !learn && !registrar {
                if let Some(stale) = stale_cache.as_ref().cloned() {
                    self.last_error = None;
                    return Ok(stale);
                }
                return Err(self
                    .last_error
                    .clone()
                    .unwrap_or_else(|| String::from("校园概览服务会话未建立，请重试")));
            }
            let (mut result, mut live_payload, recovery) =
                self.load_overview_live_once(date, learn, registrar).await?;

            // The live adapter retains typed SessionExpired evidence for the
            // Learn and Registrar sections.  Only that evidence opens the
            // existing one-shot academic refresh gates.  A transport,
            // parser, or business error leaves the result alone and therefore
            // cannot trigger a surprise login chain.
            if !recovery.is_empty() {
                if recovery.learn_session_expired {
                    self.invalidate_learn_session();
                    let _ = self
                        .refresh_academic_service_after_expiry(ServiceId::Learn)
                        .await;
                }
                if recovery.registrar_session_expired {
                    self.invalidate_registrar_session();
                    let _ = self
                        .refresh_academic_service_after_expiry(ServiceId::Registrar)
                        .await;
                }

                // Re-read only with proofs that actually survived the bounded
                // refresh.  This preserves a usable partial overview when one
                // academic service recovered but the other did not, and avoids
                // querying a service whose refresh gate already failed.
                learn = self.service_session_is_proven(ServiceId::Learn);
                registrar = self.service_session_is_proven(ServiceId::Registrar);
                if learn || registrar {
                    if let Ok((retried, retried_payload, _)) =
                        self.load_overview_live_once(date, learn, registrar).await
                    {
                        result = retried;
                        live_payload = retried_payload;
                    }
                }
            }
            let live_payload_present = live_payload.is_some();
            if let Some(overview) = live_payload {
                let payload = CampusOverviewCachePayload {
                    account_scope: cache_account_scope(&user.username),
                    stage: self.stage,
                    date,
                    generated_at: overview.generated_at,
                    overview,
                };
                if campus_overview_cache_payload_is_valid(
                    &payload,
                    &user.username,
                    self.stage,
                    date,
                    &configured_overview_semester,
                ) {
                    if let Err(error) = overview_cache.write(&payload) {
                        tracing::warn!(
                            target: "tsinghua_kit::storage",
                            event = "overview_cache_write_failed",
                            reason = "storage_io",
                            error = %error
                        );
                    }
                }
            }
            if result.status == "error" {
                if let Some(stale) = stale_cache.as_ref().cloned() {
                    self.last_error = None;
                    return Ok(stale);
                }
                result.error = Some(String::from("校园数据服务暂时不可用，请稍后重试"));
            }
            if live_payload_present && result.status != "error" {
                self.last_error = None;
                self.persist_resume_state_after_live_read(&user, "overview");
            }
            Ok(result)
        })
        .await
    }

    async fn load_overview_live_once(
        &self,
        date: NaiveDate,
        learn: bool,
        registrar: bool,
    ) -> Result<
        (
            CampusOverviewFacadeDto,
            Option<CampusOverview>,
            CampusOverviewRecoveryHints,
        ),
        String,
    > {
        let (source, scoped_learn, scoped_registrar) = if learn && self.learn_source.is_some() {
            (
                self.learn_source
                    .as_ref()
                    .expect("learn source checked above"),
                true,
                registrar && self.grades_source.is_some(),
            )
        } else if registrar && self.grades_source.is_some() {
            (
                self.grades_source
                    .as_ref()
                    .expect("registrar source checked above"),
                false,
                true,
            )
        } else {
            return Err(String::from("校园概览服务会话未建立，请重试"));
        };
        let scoped: Arc<dyn crate::services::CampusDataSource> =
            Arc::new(source.scoped_to_services(scoped_learn, scoped_registrar));
        Ok(CampusOverviewFacade::live(scoped)
            .load_with_payload_and_recovery(date)
            .await)
    }

    /// Loads the complete current semester calendar in one logical read.
    ///
    /// `CampusLiveDataSource::list_schedule` delegates the inclusive local
    /// date range to `RegistrarClient::fetch_calendar_range`, which serializes
    /// the existing 28-day windows through the shared transport gate. The
    /// result is cached by account, semester, and academic stage so changing
    /// weeks in Flutter never issues another day-sized request.
    pub async fn load_semester_schedule(&mut self) -> Result<CampusSemesterScheduleDto, String> {
        crate::telemetry::observe("registrar", "load_semester_schedule", async {
            self.allow_live_operation()?;
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            self.apply_reference_academic_stage(&user);

            let configured_semester = self.semester_config.trim().to_owned();
            let cache_allowed = self.stage_context_available_for_cache();
            let mut stale_cache = None;
            if cache_allowed {
                // Resolve an exact semester from the Rust-owned index (or the
                // already validated Learn semester cache) before touching a
                // semester-specific calendar file. If no index exists, the
                // bounded scanner below can still recover a valid calendar
                // from an earlier installation without guessing from today.
                let resolved_semester = self.resolve_schedule_cache_semester(&user);
                let mut candidate = self
                    .semester_schedule_snapshot
                    .clone()
                    .filter(|snapshot| {
                        schedule_cache_matches_context(
                            &snapshot.payload,
                            &user.username,
                            &configured_semester,
                            self.stage,
                        )
                    })
                    .map(|snapshot| SemesterScheduleCacheCandidate {
                        payload: snapshot.payload,
                        path: None,
                    });

                if candidate.is_none() {
                    if let Some(semester) = resolved_semester.as_deref() {
                        let path = academic_schedule_cache_path(
                            &self.cache_path,
                            &user.username,
                            semester,
                            self.stage,
                        );
                        let cache = JsonFileCache::<SemesterScheduleCachePayload>::new(
                            &path,
                            SEMESTER_SCHEDULE_CACHE_SCHEMA_VERSION,
                            SEMESTER_SCHEDULE_CACHE_SERVICE,
                        );
                        match cache.read() {
                            Ok(Some(envelope))
                                if schedule_cache_matches_context(
                                    &envelope.payload,
                                    &user.username,
                                    &configured_semester,
                                    self.stage,
                                ) =>
                            {
                                candidate = Some(SemesterScheduleCacheCandidate {
                                    payload: envelope.payload,
                                    path: Some(path),
                                });
                            }
                            Ok(Some(_)) | Ok(None) => {}
                            Err(error) => {
                                tracing::warn!(
                                    target: "tsinghua_kit::storage",
                                    event = "semester_schedule_cache_read_failed",
                                    reason = "cache_unavailable",
                                    error = %error
                                );
                            }
                        }
                    }
                }

                if candidate.is_none() {
                    candidate = find_semester_schedule_cache(
                        &self.cache_path,
                        &user.username,
                        self.stage,
                        if configured_semester == AUTO_SEMESTER {
                            None
                        } else {
                            Some(configured_semester.as_str())
                        },
                    );
                }

                if let Some(candidate) = candidate {
                    self.adopt_schedule_cache_context(&candidate.payload);
                    let expected_path = academic_schedule_cache_path(
                        &self.cache_path,
                        &user.username,
                        &candidate.payload.semester,
                        self.stage,
                    );
                    if candidate.path.as_deref() != Some(expected_path.as_path()) {
                        // A valid legacy cache is migrated only after all
                        // account/stage/semester/event checks above pass.
                        // Failure to migrate never turns a usable read into a
                        // false backend error.
                        let migration = JsonFileCache::<SemesterScheduleCachePayload>::new(
                            &expected_path,
                            SEMESTER_SCHEDULE_CACHE_SCHEMA_VERSION,
                            SEMESTER_SCHEDULE_CACHE_SERVICE,
                        );
                        if let Err(error) = migration.write(&candidate.payload) {
                            tracing::warn!(
                                target: "tsinghua_kit::storage",
                                event = "semester_schedule_cache_migration_failed",
                                reason = "storage_io",
                                error = %error
                            );
                        }
                    }
                    if schedule_cache_is_fresh(&candidate.payload.generated_at) {
                        let ready = SemesterScheduleSnapshot {
                            payload: candidate.payload,
                            source: "cache",
                            status: "ready",
                            error: None,
                        };
                        self.semester_schedule_snapshot = Some(ready.clone());
                        self.last_error = None;
                        return Ok(self.map_semester_schedule_snapshot(&ready));
                    }
                    if schedule_cache_is_usable(&candidate.payload.generated_at) {
                        stale_cache = Some(Self::cache_snapshot(candidate.payload));
                    }
                }
            }

            // A stale, fully validated calendar is useful when the current
            // Identity proof is absent.  If this installation has an explicit
            // private-credential opt-in (or a restored Cookie candidate), let
            // the Rust runtime spend its one bounded identity-resume attempt
            // before falling back to the same explicitly stale snapshot. A
            // cache read without that opt-in remains strictly offline.
            if !self.service_session_is_proven(ServiceId::Registrar) {
                if !self.service_session_is_proven(ServiceId::Identity) {
                    let _ = self.try_restore_identity_for_cache_refresh().await;
                    if !self.service_session_is_proven(ServiceId::Identity) {
                        if let Some(snapshot) = stale_cache.take() {
                            return Ok(self.return_stale_schedule(snapshot));
                        }
                    }
                }
                // There is no cache to serve, or Identity is already proven
                // and a stale cache deserves one live refresh opportunity. The
                // Rust read boundary owns this one lazy identity check;
                // Flutter must not preflight the service handoff.
                user = self.ensure_identity_user_for_live_read().await?;
                self.apply_reference_academic_stage(&user);
                if let Err(error) = self
                    .ensure_academic_reader_session(ServiceId::Registrar)
                    .await
                {
                    if let Some(snapshot) = stale_cache.take() {
                        return Ok(self.return_stale_schedule(snapshot));
                    }
                    return Err(error);
                }
                if !self.service_session_is_proven(ServiceId::Registrar) {
                    if let Some(snapshot) = stale_cache.take() {
                        return Ok(self.return_stale_schedule(snapshot));
                    }
                    return self.fail("教务服务会话建立状态未确认，请稍后重试");
                }
            }

            let first_day = self
                .semester_first_day
                .or_else(|| {
                    self.semester_schedule_snapshot
                        .as_ref()
                        .map(|s| s.payload.first_day)
                })
                .ok_or_else(|| String::from("当前学期开始日期未确认，无法读取完整课表"))?;
            let last_day = self
                .semester_last_day
                .or_else(|| {
                    self.semester_schedule_snapshot
                        .as_ref()
                        .map(|s| s.payload.last_day)
                })
                .ok_or_else(|| String::from("当前学期结束日期未确认，无法读取完整课表"))?;
            if first_day > last_day {
                return self.fail("当前学期日期范围无效，无法读取完整课表");
            }

            let source = self
                .grades_source
                .clone()
                .ok_or_else(|| String::from("教务课表读取能力未建立，请重新建立教务会话"))?;
            let range = campus_date_range_between(first_day, last_day)?;
            let events = match source.list_schedule(range.clone()).await {
                Ok(events) => events,
                Err(error) if error.is_session_expired(ServiceId::Registrar) => {
                    self.invalidate_registrar_session();
                    let retry = if self
                        .refresh_academic_service_after_expiry(ServiceId::Registrar)
                        .await
                        .is_ok()
                    {
                        if let Some(refreshed) = self.grades_source.clone() {
                            refreshed
                                .list_schedule(range)
                                .await
                                .map_err(|error| error.to_string())
                        } else {
                            Err(String::from("教务服务自动续接后会话未建立"))
                        }
                    } else {
                        Err(String::from("教务服务自动续接未完成"))
                    };
                    match retry {
                        Ok(events) => events,
                        Err(_) => {
                            if let Some(snapshot) = stale_cache.take() {
                                return Ok(self.return_stale_schedule(snapshot));
                            }
                            return self.fail("教务服务已过期，且没有可用的课表缓存");
                        }
                    }
                }
                Err(error) => {
                    if let Some(mut snapshot) = stale_cache.take() {
                        snapshot.status = "stale";
                        snapshot.error =
                            Some(String::from("实时课表暂时不可用，当前显示已验证缓存"));
                        self.semester_schedule_snapshot = Some(snapshot.clone());
                        self.last_error = None;
                        return Ok(self.map_semester_schedule_snapshot(&snapshot));
                    }
                    return Err(self.record_error(format!("学期课表读取: {error}")));
                }
            };

            let payload = SemesterScheduleCachePayload {
                account_scope: cache_account_scope(&user.username),
                semester: self.semester.clone(),
                stage: self.stage,
                first_day,
                last_day,
                generated_at: Utc::now(),
                events,
            };
            if !schedule_cache_matches(
                &payload,
                &user.username,
                &self.semester,
                self.stage,
                first_day,
                last_day,
            ) {
                return self.fail("学期课表响应未通过一致性校验");
            }
            // Cache persistence is best effort. It cannot turn a validated
            // live response into an error, but a failed write is observable in
            // logs and the in-memory runtime still prevents repeat requests.
            // The calendar path includes the exact semester; only after that
            // write succeeds do we advance the `auto` recovery index.
            let cache_path = academic_schedule_cache_path(
                &self.cache_path,
                &user.username,
                &payload.semester,
                self.stage,
            );
            let cache = JsonFileCache::<SemesterScheduleCachePayload>::new(
                &cache_path,
                SEMESTER_SCHEDULE_CACHE_SCHEMA_VERSION,
                SEMESTER_SCHEDULE_CACHE_SERVICE,
            );
            let cache_written = if let Err(error) = cache.write(&payload) {
                tracing::warn!(
                    target: "tsinghua_kit::storage",
                    event = "semester_schedule_cache_write_failed",
                    reason = "storage_io",
                    error = %error
                );
                false
            } else {
                true
            };
            if cache_written {
                let index = JsonFileCache::<SemesterScheduleCacheIndexPayload>::new(
                    academic_schedule_cache_index_path_for_account_stage(
                        &self.cache_path,
                        &user.username,
                        self.stage,
                    ),
                    SEMESTER_SCHEDULE_CACHE_INDEX_SCHEMA_VERSION,
                    SEMESTER_SCHEDULE_CACHE_INDEX_SERVICE,
                );
                let index_payload = SemesterScheduleCacheIndexPayload {
                    account_scope: cache_account_scope(&user.username),
                    semester: payload.semester.clone(),
                    stage: self.stage,
                    first_day,
                    last_day,
                    generated_at: payload.generated_at,
                };
                if let Err(error) = index.write(&index_payload) {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "semester_schedule_cache_index_write_failed",
                        reason = "storage_io",
                        error = %error
                    );
                }
            }
            let snapshot = SemesterScheduleSnapshot {
                payload,
                source: "live",
                status: "ready",
                error: None,
            };
            self.semester_schedule_snapshot = Some(snapshot.clone());
            self.last_error = None;
            self.persist_resume_state_after_live_read(&user, "registrar");
            Ok(self.map_semester_schedule_snapshot(&snapshot))
        })
        .await
    }

    fn map_semester_schedule_snapshot(
        &self,
        snapshot: &SemesterScheduleSnapshot,
    ) -> CampusSemesterScheduleDto {
        let first_day = snapshot.payload.first_day;
        let last_day = snapshot.payload.last_day;
        let week_count = semester_week_count(first_day, last_day);
        CampusSemesterScheduleDto {
            semester: snapshot.payload.semester.clone(),
            stage: academic_stage_name(snapshot.payload.stage).to_owned(),
            first_day: first_day.to_string(),
            last_day: last_day.to_string(),
            week_count,
            current_week: current_semester_week(first_day, week_count),
            generated_at: snapshot.payload.generated_at.to_rfc3339(),
            source: snapshot.source.to_owned(),
            status: snapshot.status.to_owned(),
            error: snapshot.error.clone(),
            events: snapshot
                .payload
                .events
                .iter()
                .cloned()
                .map(CampusScheduleDto::from)
                .collect(),
        }
    }

    fn cache_snapshot(payload: SemesterScheduleCachePayload) -> SemesterScheduleSnapshot {
        SemesterScheduleSnapshot {
            payload,
            source: "cache",
            status: "stale",
            error: None,
        }
    }

    fn adopt_schedule_cache_context(&mut self, payload: &SemesterScheduleCachePayload) {
        // `auto` may adopt the exact semester and date evidence that was
        // persisted with the previously verified calendar.  An explicit
        // semester remains constrained by schedule_cache_matches_context.
        self.semester = payload.semester.clone();
        self.semester_first_day = Some(payload.first_day);
        self.semester_last_day = Some(payload.last_day);
    }

    fn return_stale_schedule(
        &mut self,
        mut snapshot: SemesterScheduleSnapshot,
    ) -> CampusSemesterScheduleDto {
        snapshot.source = "cache";
        snapshot.status = "stale";
        snapshot.error = Some(String::from("实时课表暂时不可用，当前显示已验证缓存"));
        self.adopt_schedule_cache_context(&snapshot.payload);
        self.semester_schedule_snapshot = Some(snapshot.clone());
        self.last_error = None;
        self.map_semester_schedule_snapshot(&snapshot)
    }

    /// Resolves the exact semester needed for a schedule cache read without
    /// starting an online handoff. The schedule index is the preferred source
    /// because it records the last verified full calendar; the Learn semester
    /// cache is only a compatibility/context fallback for installations that
    /// have not written the new index yet.
    fn resolve_schedule_cache_semester(&mut self, user: &UserIdentity) -> Option<String> {
        if self.semester != AUTO_SEMESTER {
            return Some(self.semester.clone());
        }
        let configured = self.semester_config.trim();
        if configured != AUTO_SEMESTER {
            return Some(configured.to_owned());
        }
        if !self.stage_context_available_for_cache() {
            return None;
        }

        let index = JsonFileCache::<SemesterScheduleCacheIndexPayload>::new(
            academic_schedule_cache_index_path_for_account_stage(
                &self.cache_path,
                &user.username,
                self.stage,
            ),
            SEMESTER_SCHEDULE_CACHE_INDEX_SCHEMA_VERSION,
            SEMESTER_SCHEDULE_CACHE_INDEX_SERVICE,
        );
        if let Ok(Some(envelope)) = index.read() {
            if schedule_cache_index_payload_is_valid(&envelope.payload, &user.username, self.stage)
                && schedule_cache_is_usable(&envelope.payload.generated_at)
            {
                self.semester = envelope.payload.semester.clone();
                self.semester_first_day = Some(envelope.payload.first_day);
                self.semester_last_day = Some(envelope.payload.last_day);
                return Some(envelope.payload.semester);
            }
        }

        self.cache_semester_for_read(user)
    }

    /// Resolves the semester-specific cache key without forcing a live Learn
    /// or Registrar discovery request. The default `auto` mode has no semester
    /// in its filename, so prefer the Registrar-owned account/stage pointer,
    /// then a bounded scan of validated Registrar cache envelopes, and only
    /// then the Learn semester context. None of these local hints proves a
    /// live service session; the caller still performs its normal proof gate.
    fn cache_semester_for_read(&mut self, user: &UserIdentity) -> Option<String> {
        if self.semester != AUTO_SEMESTER {
            return Some(self.semester.clone());
        }
        let configured = self.semester_config.trim();
        if configured != AUTO_SEMESTER {
            return Some(configured.to_owned());
        }
        if !self.stage_context_available_for_cache() {
            return None;
        }

        if let Some(semester) =
            read_registrar_current_semester_cache(&self.cache_path, &user.username, self.stage)
        {
            self.semester = semester.clone();
            return Some(semester);
        }

        if let Some(semester) =
            find_registrar_cache_semester(&self.cache_path, &user.username, self.stage)
        {
            self.semester = semester.clone();
            return Some(semester);
        }

        self.cache_semester_from_learn_cache(user)
    }

    fn cache_semester_from_learn_cache(&mut self, user: &UserIdentity) -> Option<String> {
        let cache = JsonFileCache::<LearnSemesterCachePayload>::new(
            learn_semester_cache_path_for_account_stage(
                &self.cache_path,
                &user.username,
                self.stage,
            ),
            LEARN_CACHE_SCHEMA_VERSION,
            LEARN_SEMESTER_CACHE_SERVICE,
        );
        if let Some(payload) = cache.read().ok().flatten().map(|envelope| envelope.payload) {
            if learn_semester_cache_payload_is_valid(&payload, &user.username, self.stage) {
                self.semester = payload.semester.clone();
                self.semester_first_day = Some(payload.first_day);
                self.semester_last_day = Some(payload.last_day);
                return Some(payload.semester);
            }
        }
        let semester =
            find_learn_course_cache_semester(&self.cache_path, &user.username, self.stage);
        if let Some(semester) = semester.as_ref() {
            self.semester = semester.clone();
        }
        semester
    }

    /// Loads the configured user's read-only Registrar grade report through
    /// the authenticated Rust session and maps it to a safe bridge DTO.
    pub async fn load_grades(&mut self) -> Result<CampusGradeReportDto, String> {
        crate::telemetry::observe("registrar", "load_grades", async {
            self.allow_live_operation()?;
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            self.apply_reference_academic_stage(&user);
            let mut profile = match self.stage {
                AcademicStage::Undergraduate => {
                    RegistrarGradesProfile::undergraduate(UndergraduateReportKind::FirstDegree)
                }
                AcademicStage::Graduate => RegistrarGradesProfile::graduate(),
            };

            let mut report_kind = match self.stage {
                AcademicStage::Undergraduate => Some("first_degree"),
                AcademicStage::Graduate => None,
            };
            let mut configured_semester = self.cache_semester_for_read(&user);
            let mut cache = configured_semester.as_ref().map(|semester| {
                JsonFileCache::<RegistrarGradesCachePayload>::new(
                    registrar_grades_cache_path(
                        &self.cache_path,
                        &user.username,
                        semester,
                        self.stage,
                        report_kind,
                    ),
                    REGISTRAR_GRADES_CACHE_SCHEMA_VERSION,
                    REGISTRAR_GRADES_CACHE_SERVICE,
                )
            });
            let cached = cache.as_ref().and_then(|cache| match cache.read() {
                Ok(Some(envelope))
                    if configured_semester.as_deref().is_some_and(|semester| {
                        registrar_grades_cache_payload_is_valid(
                            &envelope.payload,
                            &user.username,
                            semester,
                            self.stage,
                            report_kind,
                        )
                    }) =>
                {
                    Some(envelope.payload)
                }
                Ok(Some(_)) | Ok(None) => None,
                Err(error) => {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "registrar_grades_cache_read_failed",
                        reason = "cache_unavailable",
                        error = %error
                    );
                    None
                }
            });
            let cached =
                cached.filter(|payload| registrar_grades_cache_is_usable(&payload.generated_at));

            // Grades are a slow-changing report and the cache has already
            // passed the account, stage, semester, report-kind, and payload
            // checks above.  A fresh verified result must be usable without a
            // new Registrar handoff; otherwise every page opening still
            // performs a live request and the cache only helps after an
            // outage.  The source/status envelope keeps this explicit to the
            // bridge and UI.
            if let Some(payload) = cached.as_ref().filter(|payload| {
                cache_is_fresh(&payload.generated_at, REGISTRAR_GRADES_CACHE_MAX_AGE)
            }) {
                self.last_error = None;
                let cache_note = payload
                    .courses
                    .is_empty()
                    .then(|| String::from("当前显示已验证的空成绩缓存，未发起实时请求"));
                return Ok(map_grade_cache_payload(
                    payload, "cache", "ready", cache_note,
                ));
            }

            let fallback = |payload: &RegistrarGradesCachePayload| {
                map_grade_cache_payload(
                    payload,
                    "cache",
                    if cache_is_fresh(&payload.generated_at, REGISTRAR_GRADES_CACHE_MAX_AGE) {
                        "ready"
                    } else {
                        "stale"
                    },
                    Some(String::from("实时成绩暂时不可用，当前显示已验证缓存")),
                )
            };

            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = cached.as_ref() {
                        self.last_error = None;
                        return Ok(fallback(payload));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = cached.as_ref() {
                        self.last_error = None;
                        return Ok(fallback(payload));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
                self.apply_reference_academic_stage(&user);
            }

            // A stale cache gets one bounded live-refresh opportunity while
            // Identity is proven. If the service cannot be rebuilt, retain
            // the explicitly stale report instead of losing offline access.
            if !self.service_session_is_proven(ServiceId::Registrar) {
                if let Err(error) = self
                    .ensure_academic_reader_session(ServiceId::Registrar)
                    .await
                {
                    if let Some(payload) = cached.as_ref() {
                        self.last_error = None;
                        return Ok(fallback(payload));
                    }
                    return Err(error);
                }
            }

            // Registrar establishment is also where an `auto` semester and an
            // ambiguous academic stage become live, verified runtime context.
            // Rebuild the cache path after that proof; otherwise the first live
            // report after an app restart has nowhere safe to be persisted and
            // every subsequent read repeats the network request.
            if self.service_session_is_proven(ServiceId::Registrar) {
                self.apply_reference_academic_stage(&user);
                profile = match self.stage {
                    AcademicStage::Undergraduate => {
                        RegistrarGradesProfile::undergraduate(UndergraduateReportKind::FirstDegree)
                    }
                    AcademicStage::Graduate => RegistrarGradesProfile::graduate(),
                };
                report_kind = match self.stage {
                    AcademicStage::Undergraduate => Some("first_degree"),
                    AcademicStage::Graduate => None,
                };
                configured_semester = self.cache_semester_for_read(&user);
                cache = configured_semester.as_ref().map(|semester| {
                    JsonFileCache::<RegistrarGradesCachePayload>::new(
                        registrar_grades_cache_path(
                            &self.cache_path,
                            &user.username,
                            semester,
                            self.stage,
                            report_kind,
                        ),
                        REGISTRAR_GRADES_CACHE_SCHEMA_VERSION,
                        REGISTRAR_GRADES_CACHE_SERVICE,
                    )
                });
            }

            let Some(source) = self.grades_source.clone() else {
                if let Some(payload) = cached.as_ref() {
                    self.last_error = None;
                    return Ok(fallback(payload));
                }
                if self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Registrar)
                    .state
                    != ServiceSessionState::Anonymous
                {
                    self.invalidate_registrar_session();
                }
                return self.fail("请先完成登录");
            };
            if !self.service_session_is_proven(ServiceId::Registrar) {
                if let Some(payload) = cached.as_ref() {
                    self.last_error = None;
                    return Ok(fallback(payload));
                }
                self.invalidate_registrar_session();
                return self.fail("教务服务会话未建立，请重新建立");
            }
            let report = match self
                .read_registrar_grade_report(source.registrar(), profile)
                .await
            {
                Ok(report) => report,
                Err(error) => {
                    if error.is_session_expired(ServiceId::Registrar) {
                        self.invalidate_registrar_session();
                        if self
                            .refresh_academic_service_after_expiry(ServiceId::Registrar)
                            .await
                            .is_ok()
                        {
                            if let Some(refreshed) = self.grades_source.clone() {
                                match self
                                    .read_registrar_grade_report(refreshed.registrar(), profile)
                                    .await
                                {
                                    Ok(report) => report,
                                    Err(retry_error) => {
                                        if retry_error.is_session_expired(ServiceId::Registrar) {
                                            self.invalidate_service_session(ServiceId::Registrar);
                                        }
                                        if let Some(payload) = cached.as_ref() {
                                            self.last_error = None;
                                            return Ok(fallback(payload));
                                        }
                                        return self.fail(
                                            "教务服务自动续接后仍未通过验证，请稍后手动重试",
                                        );
                                    }
                                }
                            } else {
                                if let Some(payload) = cached.as_ref() {
                                    self.last_error = None;
                                    return Ok(fallback(payload));
                                }
                                return self.fail("教务服务自动续接后会话未建立");
                            }
                        } else {
                            if let Some(payload) = cached.as_ref() {
                                self.last_error = None;
                                return Ok(fallback(payload));
                            }
                            return self.fail("教务服务已过期，自动续接未完成");
                        }
                    } else {
                        if let Some(payload) = cached.as_ref() {
                            self.last_error = None;
                            return Ok(fallback(payload));
                        }
                        return Err(self.record_error(error));
                    }
                }
            };
            let mut mapped = CampusGradeReportDto::from(report);
            let generated_at = Utc::now();
            if let Some(semester) = configured_semester.as_deref() {
                if cache_semester_is_safe(semester) {
                    let payload = RegistrarGradesCachePayload {
                        account_scope: cache_account_scope(&user.username),
                        semester: semester.to_owned(),
                        stage: self.stage,
                        report_kind: mapped.report_kind.clone(),
                        generated_at,
                        courses: mapped.courses.clone(),
                    };
                    if registrar_grades_cache_payload_is_valid(
                        &payload,
                        &user.username,
                        semester,
                        self.stage,
                        report_kind,
                    ) {
                        if let Some(cache) = cache.as_ref() {
                            match cache.write(&payload) {
                                Ok(()) => persist_registrar_current_semester_cache(
                                    &self.cache_path,
                                    &user.username,
                                    self.stage,
                                    semester,
                                    generated_at,
                                ),
                                Err(error) => {
                                    tracing::warn!(
                                        target: "tsinghua_kit::storage",
                                        event = "registrar_grades_cache_write_failed",
                                        reason = "storage_io",
                                        error = %error
                                    );
                                }
                            }
                        }
                    }
                }
            }
            mapped.generated_at = Some(generated_at.to_rfc3339());
            mapped.source = Some("live".to_owned());
            mapped.status = Some("ready".to_owned());
            mapped.error = None;
            self.last_error = None;
            self.persist_resume_state_after_live_read(&user, "registrar");
            Ok(mapped)
        })
        .await
    }

    /// Loads the active and expired announcements for one real Learn course.
    /// The course identifier is validated by the Learn announcement adapter;
    /// no INFO news fallback or empty-success conversion is allowed.
    pub async fn load_learn_courses(&mut self) -> Result<LearnCourseListDto, String> {
        self.read_learn_courses(true).await
    }

    async fn read_learn_courses(
        &mut self,
        allow_cached_display: bool,
    ) -> Result<LearnCourseListDto, String> {
        crate::telemetry::observe("learn", "load_learn_courses", async {
            self.allow_live_operation()?;
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            self.apply_reference_academic_stage(&user);

            // A stage must be proven before a disk cache can be reused.  For
            // the normal numeric student-id path this is resolved before the
            // first academic handoff; an ambiguous username or an explicit
            // selection still requires the stage-specific Registrar proof.
            let mut stale_cache: Option<LearnCourseListCachePayload> = None;
            if allow_cached_display && self.stage_context_available_for_cache() {
                let configured_semester = self.semester_config.trim();

                // `auto` does not yet know the semester-derived course-cache
                // path after a process restart.  The current-semester cache
                // is the account+stage index that safely supplies it.
                if self.semester == AUTO_SEMESTER {
                    let semester_cache = JsonFileCache::<LearnSemesterCachePayload>::new(
                        learn_semester_cache_path_for_account_stage(
                            &self.cache_path,
                            &user.username,
                            self.stage,
                        ),
                        LEARN_CACHE_SCHEMA_VERSION,
                        LEARN_SEMESTER_CACHE_SERVICE,
                    );
                    if let Ok(Some(envelope)) = semester_cache.read() {
                        let payload_matches = learn_semester_cache_payload_is_valid(
                            &envelope.payload,
                            &user.username,
                            self.stage,
                        );
                        let configured_semester_is_available = configured_semester == AUTO_SEMESTER
                            || envelope
                                .payload
                                .available_semesters
                                .iter()
                                .any(|semester| semester == configured_semester);
                        if payload_matches && configured_semester_is_available {
                            self.semester = if configured_semester == AUTO_SEMESTER {
                                envelope.payload.semester.clone()
                            } else {
                                configured_semester.to_owned()
                            };
                            if self.semester == envelope.payload.semester {
                                self.semester_first_day = Some(envelope.payload.first_day);
                                self.semester_last_day = Some(envelope.payload.last_day);
                            }
                        }
                    }
                    if self.semester == AUTO_SEMESTER {
                        if let Some(semester) = find_learn_course_cache_semester(
                            &self.cache_path,
                            &user.username,
                            self.stage,
                        ) {
                            self.semester = semester;
                        }
                    }
                }

                if self.semester != AUTO_SEMESTER
                    && crate::learn::validate_semester_id(&self.semester).is_ok()
                {
                    let course_cache = JsonFileCache::<LearnCourseListCachePayload>::new(
                        learn_course_list_cache_path(
                            &self.cache_path,
                            &user.username,
                            &self.semester,
                            self.stage,
                        ),
                        LEARN_CACHE_SCHEMA_VERSION,
                        LEARN_COURSE_LIST_CACHE_SERVICE,
                    );
                    match course_cache.read() {
                        Ok(Some(envelope))
                            if learn_course_list_cache_payload_is_valid(
                                &envelope.payload,
                                &user.username,
                                &self.semester,
                                self.stage,
                            ) =>
                        {
                            let payload = envelope.payload;
                            if learn_cache_is_fresh(&payload.generated_at) {
                                self.last_error = None;
                                return Ok(self.map_learn_course_list_cache(
                                    &payload, "cache", "ready", None,
                                ));
                            }
                            if learn_course_cache_is_usable(&payload.generated_at) {
                                stale_cache = Some(payload);
                            }
                        }
                        Ok(Some(_)) | Ok(None) => {}
                        Err(error) => {
                            tracing::warn!(
                                target: "tsinghua_kit::storage",
                                event = "learn_course_cache_read_failed",
                                reason = "cache_unavailable",
                                error = %error
                            );
                        }
                    }
                }
            }

            // Do not turn an expired Identity into an unsolicited live Learn
            // handoff when a validated stale course list can already be
            // rendered.  An explicit private-vault opt-in gets one bounded
            // Rust-owned identity recovery first; a cache miss still crosses
            // the live Identity boundary below.
            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(self.map_learn_course_list_cache(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时课程列表暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(self.map_learn_course_list_cache(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时课程列表暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
                self.apply_reference_academic_stage(&user);
            }

            // A stale cache is useful during an outage, but a live course
            // list remains preferable whenever the Learn proof can be built.
            // Establishment is performed by Rust here so the Flutter caller
            // does not have to decide whether a handoff is necessary.
            if !self.service_session_is_proven(ServiceId::Learn) {
                if let Err(error) = self.ensure_academic_reader_session(ServiceId::Learn).await {
                    if let Some(payload) = stale_cache.take().filter(|payload| {
                        payload.semester == self.semester && payload.stage == self.stage
                    }) {
                        return Ok(self.map_learn_course_list_cache(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时课程列表暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(error);
                }
            }

            let Some(source) = self.learn_source.clone() else {
                if let Some(payload) = stale_cache.take().filter(|payload| {
                    payload.semester == self.semester && payload.stage == self.stage
                }) {
                    return Ok(self.map_learn_course_list_cache(
                        &payload,
                        "cache",
                        "stale",
                        Some("实时课程列表暂时不可用，当前显示已验证缓存".to_owned()),
                    ));
                }
                return self.fail("学习平台服务会话未建立，请重新建立");
            };

            let records = match self.fetch_live_learn_course_records(&source).await {
                Ok(records) => records,
                Err(error) => {
                    if error.is_session_expired(ServiceId::Learn) {
                        self.invalidate_learn_session();
                        if self
                            .refresh_academic_service_after_expiry(ServiceId::Learn)
                            .await
                            .is_ok()
                        {
                            if let Some(refreshed) = self.learn_source.clone() {
                                match self.fetch_live_learn_course_records(&refreshed).await {
                                    Ok(records) => records,
                                    Err(retry_error) => {
                                        if retry_error.is_session_expired(ServiceId::Learn) {
                                            self.invalidate_service_session(ServiceId::Learn);
                                        }
                                        if let Some(payload) =
                                            stale_cache.take().filter(|payload| {
                                                payload.semester == self.semester
                                                    && payload.stage == self.stage
                                            })
                                        {
                                            return Ok(self.map_learn_course_list_cache(
                                                &payload,
                                                "cache",
                                                "stale",
                                                Some(
                                                    "实时课程列表暂时不可用，当前显示已验证缓存"
                                                        .to_owned(),
                                                ),
                                            ));
                                        }
                                        return self.fail(
                                            "学习平台自动续接后仍未通过验证，请稍后手动重试",
                                        );
                                    }
                                }
                            } else {
                                return self.fail("学习平台自动续接后会话未建立");
                            }
                        } else if let Some(payload) = stale_cache.take().filter(|payload| {
                            payload.semester == self.semester && payload.stage == self.stage
                        }) {
                            return Ok(self.map_learn_course_list_cache(
                                &payload,
                                "cache",
                                "stale",
                                Some("实时课程列表暂时不可用，当前显示已验证缓存".to_owned()),
                            ));
                        } else {
                            return self.fail("学习平台已过期，自动续接未完成");
                        }
                    } else if let Some(payload) = stale_cache.take().filter(|payload| {
                        payload.semester == self.semester && payload.stage == self.stage
                    }) {
                        return Ok(self.map_learn_course_list_cache(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时课程列表暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    } else {
                        return Err(self.record_error(format!("learn course list: {error}")));
                    }
                }
            };
            let mut seen = HashSet::new();
            let courses = records
                .iter()
                .filter_map(|record| map_learn_course(record, &self.semester))
                .filter(|course| seen.insert(course.course_id.clone()))
                .collect::<Vec<_>>();

            if !records.is_empty() && courses.is_empty() {
                return self.fail("网络学堂课程响应未提供可用的真实课程 ID");
            }

            self.learn_course_ids = courses
                .iter()
                .map(|course| course.course_id.clone())
                .collect();
            self.learn_homework.clear();
            self.learn_course_records = Some(records);
            let payload = LearnCourseListCachePayload {
                account_scope: cache_account_scope(&user.username),
                semester: self.semester.clone(),
                stage: self.stage,
                generated_at: Utc::now(),
                courses,
            };
            if self.stage_context_available_for_cache()
                && learn_course_list_cache_payload_is_valid(
                    &payload,
                    &user.username,
                    &self.semester,
                    self.stage,
                )
            {
                let cache = JsonFileCache::<LearnCourseListCachePayload>::new(
                    learn_course_list_cache_path(
                        &self.cache_path,
                        &user.username,
                        &self.semester,
                        self.stage,
                    ),
                    LEARN_CACHE_SCHEMA_VERSION,
                    LEARN_COURSE_LIST_CACHE_SERVICE,
                );
                if let Err(error) = cache.write(&payload) {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "learn_course_cache_write_failed",
                        reason = "storage_io",
                        error = %error
                    );
                }
            }
            self.last_error = None;
            self.persist_resume_state_after_live_read(&user, "learn");
            Ok(self.map_learn_course_list_cache(&payload, "live", "ready", None))
        })
        .await
    }

    fn map_learn_course_list_cache(
        &mut self,
        payload: &LearnCourseListCachePayload,
        source: &str,
        status: &str,
        error: Option<String>,
    ) -> LearnCourseListDto {
        if source == "cache" {
            self.adopt_learn_course_cache_payload(payload);
        }
        LearnCourseListDto {
            semester: payload.semester.clone(),
            stage: academic_stage_name(payload.stage).to_owned(),
            generated_at: payload.generated_at.to_rfc3339(),
            source: source.to_owned(),
            status: status.to_owned(),
            error,
            courses: payload.courses.clone(),
        }
    }

    fn adopt_learn_course_cache_payload(&mut self, payload: &LearnCourseListCachePayload) {
        // The payload has already passed the account/stage/semester cache
        // validation at the caller.  Keep the in-memory context in lockstep
        // with the envelope so a following announcement read can use the
        // cached course ids without recursively trying to rebuild Learn.
        self.semester = payload.semester.clone();
        self.stage = payload.stage;
        self.stage_detected = true;
        self.learn_course_ids = payload
            .courses
            .iter()
            .map(|course| course.course_id.clone())
            .collect();
        self.learn_homework.clear();
        self.learn_course_records = None;
    }

