    /// Loads the active and expired announcements for one real Learn course
    /// with a source-aware durable cache. Fresh metadata is served before any
    /// Learn handoff; a bounded stale list is returned only when the live
    /// service cannot be established or its read is unavailable. The durable
    /// list intentionally omits announcement bodies, which remain live-only.
    pub async fn load_learn_announcement_list(
        &mut self,
        course_id: String,
    ) -> Result<LearnAnnouncementListDto, String> {
        crate::telemetry::observe("learn", "load_learn_announcements", async {
            self.allow_live_operation()?;
            let course_id = course_id.trim().to_owned();
            if course_id.is_empty() || course_id.chars().any(char::is_control) {
                return self.fail("网络学堂课程 ID 无效");
            }

            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            self.apply_reference_academic_stage(&user);

            let mut stale_cache = None;
            if self.stage_context_available_for_cache() {
                // Explicit semesters use their deterministic account-scoped
                // path.  In `auto` mode there may be no Learn semester index
                // left after a process restart, so scan only normalized cache
                // envelopes and derive the semester from a matching
                // account/stage/course announcement payload.  The helper
                // rejects other accounts, stages, malformed envelopes, and
                // caches outside the bounded stale window.
                let configured_semester = (self.semester != AUTO_SEMESTER
                    && crate::learn::validate_semester_id(&self.semester).is_ok())
                .then(|| self.semester.clone());
                let cached_payload = if let Some(semester) = configured_semester.as_deref() {
                    let cache = JsonFileCache::<LearnAnnouncementCachePayload>::new(
                        learn_announcement_cache_path(
                            &self.cache_path,
                            &user.username,
                            semester,
                            self.stage,
                            &course_id,
                        ),
                        LEARN_ANNOUNCEMENT_CACHE_SCHEMA_VERSION,
                        LEARN_ANNOUNCEMENT_CACHE_SERVICE,
                    );
                    match cache.read() {
                        Ok(Some(envelope))
                            if learn_announcement_cache_payload_is_valid(
                                &envelope.payload,
                                &user.username,
                                semester,
                                self.stage,
                                &course_id,
                            ) && learn_announcement_cache_is_usable(
                                &envelope.payload.generated_at,
                            ) =>
                        {
                            Some(envelope.payload)
                        }
                        Ok(Some(_)) | Ok(None) => None,
                        Err(error) => {
                            tracing::warn!(
                                target: "tsinghua_kit::storage",
                                event = "learn_announcement_cache_read_failed",
                                reason = "cache_unavailable",
                                error = %error
                            );
                            None
                        }
                    }
                } else {
                    find_learn_announcement_cache(
                        &self.cache_path,
                        &user.username,
                        self.stage,
                        None,
                        Some(&course_id),
                    )
                };

                if let Some(payload) = cached_payload {
                    if self.semester == AUTO_SEMESTER {
                        // The payload was written only after a real Learn
                        // course id and semester had been validated.  Adopt
                        // that exact context; never infer a semester from the
                        // current date or from the caller's course id.
                        self.semester = payload.semester.clone();
                    }
                    if learn_announcement_cache_is_fresh(&payload.generated_at) {
                        self.last_error = None;
                        return Ok(map_learn_announcement_cache(
                            &payload, "cache", "ready", None,
                        ));
                    }
                    stale_cache = Some(payload);
                }
            }

            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_learn_announcement_cache(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告暂时不可用，当前显示已验证过期缓存".to_owned()),
                        ));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_learn_announcement_cache(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告暂时不可用，当前显示已验证过期缓存".to_owned()),
                        ));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
                self.apply_reference_academic_stage(&user);
            }

            // A cache envelope written by this reader already contains the
            // account, stage, semester, and real course ID that were proved
            // when it was created.  Let that envelope serve a fresh/stale
            // metadata read after restart; requiring the live course list
            // first would turn a catalog-advertised cache capability back
            // into an unsolicited Learn handoff.  A cache miss still crosses
            // the live course-list boundary below before any announcement
            // request is sent.
            if !self
                .learn_course_ids
                .iter()
                .any(|known_id| known_id == &course_id)
            {
                match self.load_learn_courses().await {
                    Ok(course_list) => {
                        if !course_list
                            .courses
                            .iter()
                            .any(|course| course.course_id == course_id)
                        {
                            return self.fail("网络学堂课程不在当前真实课程列表中");
                        }
                    }
                    Err(error) => {
                        // A stale announcement envelope is already bound to
                        // this account, stage, semester, and real course id.
                        // If the live course-list handoff is unavailable, it
                        // remains a safe offline result; the error must still
                        // be visible in the source-aware DTO.
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_learn_announcement_cache(
                                &payload,
                                "cache",
                                "stale",
                                Some("实时公告暂时不可用，当前显示已验证过期缓存".to_owned()),
                            ));
                        }
                        return Err(error);
                    }
                }
            }

            if !self.service_session_is_proven(ServiceId::Learn) {
                if let Err(error) = self.ensure_academic_reader_session(ServiceId::Learn).await {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_learn_announcement_cache(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告暂时不可用，当前显示已验证过期缓存".to_owned()),
                        ));
                    }
                    return Err(error);
                }
            }
            let Some(source) = self.learn_source.clone() else {
                if let Some(payload) = stale_cache.take() {
                    self.last_error = None;
                    return Ok(map_learn_announcement_cache(
                        &payload,
                        "cache",
                        "stale",
                        Some("实时公告暂时不可用，当前显示已验证过期缓存".to_owned()),
                    ));
                }
                return self.fail("学习平台服务会话未建立，请重新建立");
            };
            if !self.service_session_is_proven(ServiceId::Learn) {
                self.invalidate_learn_session();
                return self.fail("学习平台服务会话未建立，请重新建立");
            }
            let announcements = match source.list_learn_announcements(&course_id).await {
                Ok(announcements) => announcements,
                Err(error) => {
                    if error.is_session_expired(ServiceId::Learn) {
                        self.invalidate_learn_session();
                        if self
                            .refresh_academic_service_after_expiry(ServiceId::Learn)
                            .await
                            .is_ok()
                        {
                            let courses = self.load_learn_courses().await;
                            if let Ok(courses) = courses {
                                if !courses
                                    .courses
                                    .iter()
                                    .any(|course| course.course_id == course_id)
                                {
                                    return self.fail("网络学堂课程不在自动续接后的真实课程列表中");
                                }
                            } else if let Some(payload) = stale_cache.take() {
                                self.last_error = None;
                                return Ok(map_learn_announcement_cache(
                                    &payload,
                                    "cache",
                                    "stale",
                                    Some("实时公告暂时不可用，当前显示已验证过期缓存".to_owned()),
                                ));
                            }
                            if let Some(refreshed) = self.learn_source.clone() {
                                match refreshed.list_learn_announcements(&course_id).await {
                                    Ok(announcements) => announcements,
                                    Err(retry_error) => {
                                        if retry_error.is_session_expired(ServiceId::Learn) {
                                            self.invalidate_service_session(ServiceId::Learn);
                                        }
                                        if let Some(payload) = stale_cache.take() {
                                            self.last_error = None;
                                            return Ok(map_learn_announcement_cache(
                                                &payload,
                                                "cache",
                                                "stale",
                                                Some(
                                                    "实时公告暂时不可用，当前显示已验证过期缓存"
                                                        .to_owned(),
                                                ),
                                            ));
                                        }
                                        return self.fail(
                                            "网络学堂自动续接后仍未通过验证，请稍后手动重试",
                                        );
                                    }
                                }
                            } else if let Some(payload) = stale_cache.take() {
                                self.last_error = None;
                                return Ok(map_learn_announcement_cache(
                                    &payload,
                                    "cache",
                                    "stale",
                                    Some("实时公告暂时不可用，当前显示已验证过期缓存".to_owned()),
                                ));
                            } else {
                                return self.fail("学习平台自动续接后会话未建立");
                            }
                        } else {
                            if let Some(payload) = stale_cache.take() {
                                self.last_error = None;
                                return Ok(map_learn_announcement_cache(
                                    &payload,
                                    "cache",
                                    "stale",
                                    Some("实时公告暂时不可用，当前显示已验证过期缓存".to_owned()),
                                ));
                            }
                            return self.fail("学习平台已过期，自动续接未完成");
                        }
                    } else {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_learn_announcement_cache(
                                &payload,
                                "cache",
                                "stale",
                                Some("实时公告暂时不可用，当前显示已验证过期缓存".to_owned()),
                            ));
                        }
                        return Err(self.record_error(format!("网络学堂公告: {error}")));
                    }
                }
            };
            let announcements = announcements
                .into_iter()
                .map(map_learn_announcement)
                .collect::<Vec<_>>();
            let generated_at = Utc::now();
            let payload = LearnAnnouncementCachePayload {
                account_scope: cache_account_scope(&user.username),
                semester: self.semester.clone(),
                stage: self.stage,
                course_id: course_id.clone(),
                generated_at,
                announcements: announcements
                    .iter()
                    .map(|announcement| LearnAnnouncementCacheRecord {
                        course_id: announcement.course_id.clone(),
                        announcement_id: announcement.announcement_id.clone(),
                        title: announcement.title.clone(),
                        publisher: announcement.publisher.clone(),
                        published_at: announcement.published_at.clone(),
                        expires_at: announcement.expires_at.clone(),
                        read: announcement.read,
                        important: announcement.important,
                        favorited: announcement.favorited,
                        expired: announcement.expired,
                    })
                    .collect(),
            };
            if learn_announcement_cache_payload_is_valid(
                &payload,
                &user.username,
                &self.semester,
                self.stage,
                &course_id,
            ) {
                let cache = JsonFileCache::<LearnAnnouncementCachePayload>::new(
                    learn_announcement_cache_path(
                        &self.cache_path,
                        &user.username,
                        &self.semester,
                        self.stage,
                        &course_id,
                    ),
                    LEARN_ANNOUNCEMENT_CACHE_SCHEMA_VERSION,
                    LEARN_ANNOUNCEMENT_CACHE_SERVICE,
                );
                if let Err(error) = cache.write(&payload) {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "learn_announcement_cache_write_failed",
                        reason = "storage_io",
                        error = %error
                    );
                }
            }
            self.last_error = None;
            self.persist_resume_state_after_live_read(&user, "learn");
            Ok(LearnAnnouncementListDto {
                course_id,
                generated_at: generated_at.to_rfc3339(),
                source: "live".to_owned(),
                status: "ready".to_owned(),
                error: None,
                announcements,
            })
        })
        .await
    }

    /// Compatibility method for older bridge consumers. Production Flutter
    /// uses `load_learn_announcement_list` so cache provenance is preserved.
    pub async fn load_learn_announcements(
        &mut self,
        course_id: String,
    ) -> Result<Vec<LearnAnnouncementDto>, String> {
        Ok(self
            .load_learn_announcement_list(course_id)
            .await?
            .announcements)
    }

    /// Loads examinations through the authenticated, stage-bound Registrar
    /// session: the undergraduate exam page or graduate teaching calendar.
    ///
    /// The confirmed page is a complete HTML table request and has no proven
    /// `start_date`/`end_date` query or filtering semantics. The two arguments
    /// remain in the bridge for compatibility with the earlier API shape, but
    /// any non-empty value is rejected before a request is sent. Rust chooses
    /// the undergraduate page or the complete, verified graduate term window;
    /// a caller cannot replace this with an arbitrary day or guessed endpoint.
    pub async fn load_exams(
        &mut self,
        start_date: String,
        end_date: String,
    ) -> Result<CampusExamReportDto, String> {
        crate::telemetry::observe("registrar", "load_exams", async {
            self.allow_live_operation()?;
            if !start_date.trim().is_empty() || !end_date.trim().is_empty() {
                return self.fail("考试页面没有已确认的日期筛选语义，请使用空日期读取完整页面");
            }

            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            self.apply_reference_academic_stage(&user);
            let stage = self.stage;
            let mut configured_semester = self.cache_semester_for_read(&user);
            let mut cache = configured_semester.as_ref().map(|semester| {
                JsonFileCache::<RegistrarExamsCachePayload>::new(
                    registrar_exams_cache_path(&self.cache_path, &user.username, semester, stage),
                    REGISTRAR_EXAMS_CACHE_SCHEMA_VERSION,
                    graduate_exams::cache_service(stage),
                )
            });
            let cached = cache.as_ref().and_then(|cache| match cache.read() {
                Ok(Some(envelope))
                    if configured_semester.as_deref().is_some_and(|semester| {
                        registrar_exams_cache_payload_is_valid(
                            &envelope.payload,
                            &user.username,
                            semester,
                            stage,
                        )
                    }) =>
                {
                    Some(envelope.payload)
                }
                Ok(Some(_)) | Ok(None) => None,
                Err(error) => {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "registrar_exams_cache_read_failed",
                        reason = "cache_unavailable",
                        error = %error
                    );
                    None
                }
            });
            let cached =
                cached.filter(|payload| registrar_exams_cache_is_usable(&payload.generated_at));
            if let Some(payload) = cached.as_ref().filter(|payload| {
                cache_is_fresh(&payload.generated_at, REGISTRAR_EXAMS_CACHE_MAX_AGE)
            }) {
                self.last_error = None;
                return Ok(map_exam_cache_payload(payload, "cache", "ready", None));
            }
            let fallback = |payload: &RegistrarExamsCachePayload| {
                map_exam_cache_payload(
                    payload,
                    "cache",
                    if cache_is_fresh(&payload.generated_at, REGISTRAR_EXAMS_CACHE_MAX_AGE) {
                        "ready"
                    } else {
                        "stale"
                    },
                    Some(String::from("实时考试安排暂时不可用，当前显示已验证缓存")),
                )
            };

            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = cached.as_ref() {
                        self.last_error = None;
                        return Ok(fallback(payload));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = cached.as_ref() {
                        self.last_error = None;
                        return Ok(fallback(payload));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
                self.apply_reference_academic_stage(&user);
            }

            // Give a stale report one bounded Registrar refresh opportunity;
            // preserve it if that live attempt cannot be completed.
            if !self.service_session_is_proven(ServiceId::Registrar) {
                if let Err(error) = self
                    .ensure_academic_reader_session(ServiceId::Registrar)
                    .await
                {
                    if let Some(payload) = cached.as_ref() {
                        self.last_error = None;
                        return Ok(fallback(payload));
                    }
                    return Err(error);
                }
            }

            // The live Registrar handoff can resolve both the actual semester
            // and the academic stage. Re-read that verified context before
            // constructing the write path for the first live exam report.
            if self.service_session_is_proven(ServiceId::Registrar) {
                self.apply_reference_academic_stage(&user);
                if self.stage != stage {
                    return self.fail("考试查询的学业阶段已变化，请重新读取");
                }
                configured_semester = self.cache_semester_for_read(&user);
                cache = configured_semester.as_ref().map(|semester| {
                    JsonFileCache::<RegistrarExamsCachePayload>::new(
                        registrar_exams_cache_path(
                            &self.cache_path,
                            &user.username,
                            semester,
                            stage,
                        ),
                        REGISTRAR_EXAMS_CACHE_SCHEMA_VERSION,
                        graduate_exams::cache_service(stage),
                    )
                });
            }

            let Some(source) = self.grades_source.clone() else {
                if let Some(payload) = cached.as_ref() {
                    self.last_error = None;
                    return Ok(fallback(payload));
                }
                if self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Registrar)
                    .state
                    != ServiceSessionState::Anonymous
                {
                    self.invalidate_registrar_session();
                }
                return self.fail("请先完成登录");
            };
            if !self.service_session_is_proven(ServiceId::Registrar) {
                if let Some(payload) = cached.as_ref() {
                    self.last_error = None;
                    return Ok(fallback(payload));
                }
                self.invalidate_registrar_session();
                return self.fail("教务服务会话未建立，请重新建立");
            }

            let calendar_window = if stage == AcademicStage::Graduate {
                Some(
                    self.semester_first_day
                        .zip(self.semester_last_day)
                        .filter(|(first, last)| first <= last && (*last - *first).num_days() <= 370)
                        .ok_or_else(|| String::from("研究生考试查询的完整学期日期范围未确认"))?,
                )
            } else {
                None
            };
            let exam_semester = self.semester.clone();
            let mapped =
                match graduate_exams::read_report(&source, stage, calendar_window, &exam_semester)
                    .await
                {
                    Ok(records) => records,
                    Err(error) => {
                        if error.is_session_expired(ServiceId::Registrar) {
                            self.invalidate_registrar_session();
                            if self
                                .refresh_academic_service_after_expiry(ServiceId::Registrar)
                                .await
                                .is_ok()
                            {
                                if let Some(refreshed) = self.grades_source.clone() {
                                    match graduate_exams::read_report(
                                        &refreshed,
                                        stage,
                                        calendar_window,
                                        &exam_semester,
                                    )
                                    .await
                                    {
                                        Ok(records) => records,
                                        Err(retry_error) => {
                                            if retry_error.is_session_expired(ServiceId::Registrar)
                                            {
                                                self.invalidate_service_session(
                                                    ServiceId::Registrar,
                                                );
                                            }
                                            if let Some(payload) = cached.as_ref() {
                                                self.last_error = None;
                                                return Ok(fallback(payload));
                                            }
                                            return self.fail(
                                                "教务服务自动续接后仍未通过验证，请稍后手动重试",
                                            );
                                        }
                                    }
                                } else {
                                    if let Some(payload) = cached.as_ref() {
                                        self.last_error = None;
                                        return Ok(fallback(payload));
                                    }
                                    return self.fail("教务服务自动续接后会话未建立");
                                }
                            } else {
                                if let Some(payload) = cached.as_ref() {
                                    self.last_error = None;
                                    return Ok(fallback(payload));
                                }
                                return self.fail("教务服务已过期，自动续接未完成");
                            }
                        } else {
                            if let Some(payload) = cached.as_ref() {
                                self.last_error = None;
                                return Ok(fallback(payload));
                            }
                            return Err(self.record_error(format!("registrar exams: {error}")));
                        }
                    }
                };
            let generated_at = Utc::now();
            if let Some(semester) = configured_semester.as_deref() {
                if cache_semester_is_safe(semester) {
                    let payload = RegistrarExamsCachePayload {
                        account_scope: cache_account_scope(&user.username),
                        semester: semester.to_owned(),
                        stage,
                        generated_at,
                        calendar_window,
                        exams: mapped.exams.clone(),
                    };
                    if registrar_exams_cache_payload_is_valid(
                        &payload,
                        &user.username,
                        semester,
                        stage,
                    ) {
                        if let Some(cache) = cache.as_ref() {
                            match cache.write(&payload) {
                                Ok(()) => persist_registrar_current_semester_cache(
                                    &self.cache_path,
                                    &user.username,
                                    stage,
                                    semester,
                                    generated_at,
                                ),
                                Err(error) => {
                                    tracing::warn!(
                                        target: "tsinghua_kit::storage",
                                        event = "registrar_exams_cache_write_failed",
                                        reason = "storage_io",
                                        error = %error
                                    );
                                }
                            }
                        }
                    }
                }
            }
            let mut mapped = mapped;
            mapped.generated_at = Some(generated_at.to_rfc3339());
            mapped.source = Some("live".to_owned());
            mapped.status = Some("ready".to_owned());
            mapped.error = None;
            self.last_error = None;
            self.persist_resume_state_after_live_read(&user, "registrar");
            Ok(mapped)
        })
        .await
    }

    /// Loads one real INFO portal news page through the authenticated INFO
    /// WebVPN session.  This is intentionally a Rust-owned request: Flutter
    /// supplies paging/filter inputs and receives only normalized records.
    async fn fetch_info_news_list_once(
        adapter: &InfoSessionAdapter,
        coordinator: &SessionCoordinator,
        page: u32,
        page_size: u32,
        source_id: Option<&str>,
        channel_id: Option<&str>,
    ) -> Result<NewsPage, InfoSessionError> {
        adapter
            .fetch_news_list(coordinator, page, page_size, source_id, channel_id)
            .await
    }

    async fn search_info_news_once(
        adapter: &InfoSessionAdapter,
        coordinator: &SessionCoordinator,
        input: &NewsSearchInput,
    ) -> Result<NewsPage, InfoSessionError> {
        adapter.search_news(coordinator, input).await
    }

    async fn fetch_info_news_detail_once(
        adapter: &InfoSessionAdapter,
        coordinator: &SessionCoordinator,
        article_id_or_link: &str,
    ) -> Result<NewsDetail, InfoSessionError> {
        adapter
            .fetch_news_detail(coordinator, article_id_or_link)
            .await
    }

    async fn fetch_info_news_catalog_once(
        adapter: &InfoSessionAdapter,
        coordinator: &SessionCoordinator,
    ) -> Result<
        (
            Vec<NewsSourceOption>,
            Result<Vec<NewsChannelOption>, InfoSessionError>,
        ),
        InfoSessionError,
    > {
        // Both requests share the same proven INFO session and cookie jar.
        // Keep the CSRF bootstrap serial so one request cannot race a cookie
        // refresh performed by the other.
        let sources = adapter.fetch_news_sources(coordinator).await?;
        let channels = adapter.fetch_news_channels(coordinator).await;
        Ok((sources, channels))
    }

    pub async fn load_info_news_catalog(&mut self) -> Result<InfoNewsCatalogDto, String> {
        crate::telemetry::observe("info", "load_info_news_catalog", async {
            self.allow_live_operation()?;
            let user = self.ensure_identity_user_for_live_read().await?;
            self.ensure_info_reader_session(&user).await?;
            let Some(adapter) = self.info_adapter.as_ref() else {
                return self.fail("INFO 服务会话未建立");
            };
            if !self.service_session_is_proven(ServiceId::Identity)
                || !self.service_session_is_proven(ServiceId::Info)
                || self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Info)
                    .user
                    .as_ref()
                    != Some(&user)
                || !Arc::ptr_eq(
                    adapter.transport().cookie_jar(),
                    self.identity.transport().cookie_jar(),
                )
            {
                return self.fail("INFO 新闻目录账号会话未确认");
            }
            let mut result = Self::fetch_info_news_catalog_once(adapter, &self.coordinator).await;
            if matches!(&result, Err(InfoSessionError::LoginRequired))
                || matches!(&result, Ok((_, Err(InfoSessionError::LoginRequired))))
            {
                self.invalidate_service_session(ServiceId::Info);
                self.refresh_nonacademic_service_after_expiry(ServiceId::Info)
                    .await
                    .map_err(|_| self.record_error("INFO 新闻目录会话续接未完成".to_owned()))?;
                let Some(adapter) = self.info_adapter.as_ref() else {
                    return self.fail("INFO 新闻目录续接后会话未建立");
                };
                result = Self::fetch_info_news_catalog_once(adapter, &self.coordinator).await;
                if matches!(&result, Err(InfoSessionError::LoginRequired))
                    || matches!(&result, Ok((_, Err(InfoSessionError::LoginRequired))))
                {
                    self.invalidate_service_session(ServiceId::Info);
                    return self.fail("INFO 新闻目录会话仍已过期，请重新登录");
                }
            }
            let (sources, channels) = result.map_err(|error| {
                self.record_business_failure("info", "info_news_catalog", info_failure_code(&error))
            })?;
            let (channels, status, channel_error) = match channels {
                Ok(channels) => (channels, "ready", None),
                Err(InfoSessionError::NewsHttpStatus { status })
                    if status == reqwest::StatusCode::NOT_FOUND =>
                {
                    // The pinned reference directory route is gone on the
                    // current server. Only IDs from a freshly verified news
                    // page may become partial filter options; this never
                    // claims to be the complete channel catalog.
                    let observed = self
                        .info_adapter
                        .as_ref()
                        .ok_or("INFO 服务会话未建立")?
                        .fetch_news_list(&self.coordinator, 1, 30, None, None)
                        .await;
                    let (observed, warning) = match observed {
                        Ok(page) => {
                            let channels = crate::info_news::channels_observed_on_news_page(&page);
                            let warning = if channels.is_empty() {
                                "INFO 栏目目录接口不存在；最新新闻中未发现可筛选栏目"
                            } else {
                                "INFO 栏目目录接口不存在；仅显示最新新闻中已发现的栏目"
                            };
                            (channels, warning)
                        }
                        Err(InfoSessionError::LoginRequired) => {
                            self.invalidate_service_session(ServiceId::Info);
                            return self.fail("INFO 新闻栏目候选读取时会话已过期，请重新建立");
                        }
                        Err(error) => {
                            let _ = self.record_business_failure(
                                "info",
                                "info_news_catalog_observed",
                                info_failure_code(&error),
                            );
                            (
                                Vec::new(),
                                "INFO 栏目目录接口不存在，最新新闻栏目候选读取失败；当前仅可按来源筛选",
                            )
                        }
                    };
                    (observed, "partial", Some(warning.to_owned()))
                }
                Err(error) => {
                    return Err(self.record_business_failure(
                        "info",
                        "info_news_catalog",
                        info_failure_code(&error),
                    ));
                }
            };
            self.allow_live_operation()?;
            if !self.service_session_is_proven(ServiceId::Identity)
                || !self.service_session_is_proven(ServiceId::Info)
                || self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Info)
                    .user
                    .as_ref()
                    != Some(&user)
            {
                return self.fail("INFO 新闻目录账号会话未确认");
            }
            self.last_error = None;
            self.persist_resume_state_after_live_read(&user, "info");
            Ok(InfoNewsCatalogDto {
                sources: sources
                    .into_iter()
                    .map(|option| InfoNewsFilterDto {
                        id: option.id,
                        label: option.name,
                    })
                    .collect(),
                channels: channels
                    .into_iter()
                    .map(|option| InfoNewsFilterDto {
                        id: option.id,
                        label: option.title,
                    })
                    .collect(),
                generated_at: Utc::now().to_rfc3339(),
                source: "live".to_owned(),
                status: status.to_owned(),
                channel_error,
            })
        })
        .await
    }

    /// Reads the user's INFO subscription rules without exposing server rule
    /// IDs or performing subscribe/unsubscribe operations.
    pub async fn load_info_news_subscriptions(
        &mut self,
    ) -> Result<InfoNewsSubscriptionsDto, String> {
        crate::telemetry::observe("info", "load_info_news_subscriptions", async {
            self.allow_live_operation()?;
            self.info_subscription_selectors.clear();
            self.info_subscription_owner = None;
            self.info_subscription_at = None;
            let user = self.ensure_identity_user_for_live_read().await?;
            self.ensure_info_reader_session(&user).await?;
            let Some(adapter) = self.info_adapter.as_ref() else {
                return self.fail("INFO 服务会话未建立");
            };
            if !self.service_session_is_proven(ServiceId::Identity)
                || !self.service_session_is_proven(ServiceId::Info)
                || self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Info)
                    .user
                    .as_ref()
                    != Some(&user)
                || !Arc::ptr_eq(
                    adapter.transport().cookie_jar(),
                    self.identity.transport().cookie_jar(),
                )
            {
                return self.fail("INFO 订阅账号会话未确认");
            }
            let mut result = adapter.fetch_news_subscriptions(&self.coordinator).await;
            if matches!(&result, Err(InfoSessionError::LoginRequired)) {
                self.invalidate_service_session(ServiceId::Info);
                self.refresh_nonacademic_service_after_expiry(ServiceId::Info)
                    .await
                    .map_err(|_| self.record_error("INFO 订阅会话续接未完成".to_owned()))?;
                let Some(adapter) = self.info_adapter.as_ref() else {
                    return self.fail("INFO 订阅续接后会话未建立");
                };
                if !self.service_session_is_proven(ServiceId::Info)
                    || self
                        .coordinator
                        .registry()
                        .snapshot_for(ServiceId::Info)
                        .user
                        .as_ref()
                        != Some(&user)
                    || !Arc::ptr_eq(
                        adapter.transport().cookie_jar(),
                        self.identity.transport().cookie_jar(),
                    )
                {
                    return self.fail("INFO 订阅续接后账号会话未确认");
                }
                result = adapter.fetch_news_subscriptions(&self.coordinator).await;
                if matches!(&result, Err(InfoSessionError::LoginRequired)) {
                    self.invalidate_service_session(ServiceId::Info);
                    return self.fail("INFO 订阅会话仍已过期，请重新登录");
                }
            }
            let rules = result.map_err(|error| {
                self.record_business_failure(
                    "info",
                    "info_news_subscriptions",
                    info_failure_code(&error),
                )
            })?;
            self.allow_live_operation()?;
            if !self.service_session_is_proven(ServiceId::Identity)
                || !self.service_session_is_proven(ServiceId::Info)
                || self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Info)
                    .user
                    .as_ref()
                    != Some(&user)
                || self.info_adapter.as_ref().is_none_or(|adapter| {
                    !Arc::ptr_eq(
                        adapter.transport().cookie_jar(),
                        self.identity.transport().cookie_jar(),
                    )
                })
            {
                return self.fail("INFO 订阅账号会话未确认");
            }
            let mut selectors = HashMap::new();
            let rules = rules
                .into_iter()
                .map(|rule| {
                    let selector = Uuid::new_v4().simple().to_string();
                    selectors.insert(selector.clone(), rule.id);
                    InfoNewsSubscriptionDto {
                        selector,
                        title: rule.title,
                        order: rule.order,
                        sources: rule.sources,
                        channels: rule.channels,
                        keyword: rule.keyword,
                    }
                })
                .collect();
            self.info_subscription_selectors = selectors;
            self.info_subscription_owner = Some(user.username.clone());
            self.info_subscription_at = Some(std::time::Instant::now());
            self.last_error = None;
            self.persist_resume_state_after_live_read(&user, "info");
            Ok(InfoNewsSubscriptionsDto {
                rules,
                generated_at: Utc::now().to_rfc3339(),
                source: "live".to_owned(),
                status: "ready".to_owned(),
            })
        })
        .await
    }

    /// Reads one page for a rule selected from this runtime's recent live
    /// subscription list. Unknown, stale, or another account's selectors are
    /// rejected before the INFO request is built.
    pub async fn load_info_news_subscription_page(
        &mut self,
        selector: String,
        page: u32,
    ) -> Result<InfoNewsPageDto, String> {
        crate::telemetry::observe("info", "load_info_news_subscription_page", async {
            self.allow_live_operation()?;
            if !(1..=100).contains(&page) {
                return self.fail("INFO 订阅新闻页码无效");
            }
            let user = self.ensure_identity_user_for_live_read().await?;
            self.ensure_info_reader_session(&user).await?;
            let rule_id = selected_info_subscription_rule(
                self.info_subscription_owner.as_deref(),
                self.info_subscription_at,
                &self.info_subscription_selectors,
                &user.username,
                &selector,
            )
            .map(str::to_owned)
            .ok_or_else(|| self.record_error("INFO 订阅选择已失效，请刷新订阅规则".to_owned()))?;
            let Some(adapter) = self.info_adapter.as_ref() else {
                return self.fail("INFO 服务会话未建立");
            };
            if !self.service_session_is_proven(ServiceId::Identity)
                || !self.service_session_is_proven(ServiceId::Info)
                || self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Info)
                    .user
                    .as_ref()
                    != Some(&user)
                || !Arc::ptr_eq(
                    adapter.transport().cookie_jar(),
                    self.identity.transport().cookie_jar(),
                )
            {
                return self.fail("INFO 订阅新闻账号会话未确认");
            }
            let page_result = adapter
                .fetch_news_by_subscription(&self.coordinator, page, &rule_id)
                .await;
            if matches!(&page_result, Err(InfoSessionError::LoginRequired)) {
                self.invalidate_service_session(ServiceId::Info);
                return self.fail("INFO 订阅新闻会话已过期，请重新读取订阅规则");
            }
            let page_result = page_result.map_err(|error| {
                self.record_business_failure(
                    "info",
                    "info_news_subscription_page",
                    info_failure_code(&error),
                )
            })?;
            self.allow_live_operation()?;
            if !self.service_session_is_proven(ServiceId::Identity)
                || !self.service_session_is_proven(ServiceId::Info)
                || self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Info)
                    .user
                    .as_ref()
                    != Some(&user)
                || self.info_adapter.as_ref().is_none_or(|adapter| {
                    !Arc::ptr_eq(
                        adapter.transport().cookie_jar(),
                        self.identity.transport().cookie_jar(),
                    )
                })
                || self.info_subscription_owner.as_deref() != Some(&user.username)
                || self.info_subscription_selectors.get(&selector) != Some(&rule_id)
            {
                return self.fail("INFO 订阅新闻账号会话未确认");
            }
            self.remember_news_links(&page_result)?;
            self.last_error = None;
            self.persist_resume_state_after_live_read(&user, "info");
            Ok(page_result.into())
        })
        .await
    }

