    pub async fn load_info_news(
        &mut self,
        page: u32,
        page_size: u32,
        source_id: Option<String>,
        channel_id: Option<String>,
    ) -> Result<InfoNewsPageDto, String> {
        self.load_info_news_with_policy(
            page,
            page_size,
            source_id,
            channel_id,
            ReadPolicy::PreferFreshCache,
        )
        .await
    }

    pub(crate) async fn load_info_news_with_policy(
        &mut self,
        page: u32,
        page_size: u32,
        source_id: Option<String>,
        channel_id: Option<String>,
        policy: ReadPolicy,
    ) -> Result<InfoNewsPageDto, String> {
        crate::telemetry::observe("info", "load_info_news", async {
            if policy != ReadPolicy::CacheOnly {
                self.allow_live_operation()?;
            }
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None if policy == ReadPolicy::CacheOnly => {
                    return Err(self.record_business_failure(
                        "info",
                        "info_news_list",
                        "info_news_cache_miss",
                    ));
                }
                None => self.ensure_identity_user_for_live_read().await?,
            };

            let mut cache = JsonFileCache::<InfoNewsPageCachePayload>::new(
                info_news_cache_path(
                    &self.cache_path,
                    &user.username,
                    "list",
                    page,
                    page_size,
                    source_id.as_deref(),
                    channel_id.as_deref(),
                    "",
                    None,
                    false,
                ),
                INFO_NEWS_CACHE_SCHEMA_VERSION,
                INFO_NEWS_CACHE_SERVICE,
            );
            let mut stale_cache = None;
            match cache.read() {
                Ok(Some(envelope))
                    if info_news_cache_payload_is_valid(
                        &envelope.payload,
                        &user.username,
                        "list",
                        page,
                        page_size,
                        source_id.as_deref(),
                        channel_id.as_deref(),
                        "",
                        None,
                        false,
                    ) && info_news_cache_is_usable(&envelope.payload.generated_at) =>
                {
                    let payload = envelope.payload;
                    let fresh = info_news_cache_is_fresh(&payload.generated_at);
                    if policy == ReadPolicy::CacheOnly
                        || (fresh
                            && policy != ReadPolicy::RefreshOrCached
                            && policy != ReadPolicy::Refresh)
                    {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            if fresh { "ready" } else { "stale" },
                            None,
                        ));
                    }
                    if policy != ReadPolicy::Refresh {
                        stale_cache = Some(payload);
                    }
                }
                Ok(Some(_)) | Ok(None) => {}
                Err(error) => {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "info_news_cache_read_failed",
                        reason = "cache_unavailable",
                        error = %error
                    );
                }
            }

            if policy == ReadPolicy::CacheOnly {
                return Err(self.record_business_failure(
                    "info",
                    "info_news_list",
                    "info_news_cache_miss",
                ));
            }

            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
                cache = JsonFileCache::<InfoNewsPageCachePayload>::new(
                    info_news_cache_path(
                        &self.cache_path,
                        &user.username,
                        "list",
                        page,
                        page_size,
                        source_id.as_deref(),
                        channel_id.as_deref(),
                        "",
                        None,
                        false,
                    ),
                    INFO_NEWS_CACHE_SCHEMA_VERSION,
                    INFO_NEWS_CACHE_SERVICE,
                );
            }

            // A stale feed gets one normal live attempt while Identity is
            // proven. The reader owns the lazy portal + INFO handoff so a
            // cache miss after an app restart does not require a separate
            // manual service-page action. Only an explicit stale-session
            // response from an already established INFO adapter enters the
            // bounded automatic-refresh path below.
            if !self.service_session_is_proven(ServiceId::Info) {
                if let Err(error) = self.ensure_info_reader_session(&user).await {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(error);
                }
            }
            let Some(adapter) = self.info_adapter.as_ref() else {
                return self.fail("INFO 服务会话未建立");
            };
            let mut result = Self::fetch_info_news_list_once(
                adapter,
                &self.coordinator,
                page,
                page_size,
                source_id.as_deref(),
                channel_id.as_deref(),
            )
            .await;
            if matches!(&result, Err(InfoSessionError::LoginRequired)) {
                self.invalidate_service_session(ServiceId::Info);
                if let Err(error) = self
                    .refresh_nonacademic_service_after_expiry(ServiceId::Info)
                    .await
                {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("INFO 会话续接失败，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(self.record_error(format!("INFO 新闻列表自动续接失败: {error}")));
                }
                let Some(adapter) = self.info_adapter.as_ref() else {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("INFO 会话续接后仍不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("INFO 新闻列表自动续接后会话未建立");
                };
                result = Self::fetch_info_news_list_once(
                    adapter,
                    &self.coordinator,
                    page,
                    page_size,
                    source_id.as_deref(),
                    channel_id.as_deref(),
                )
                .await;
                if matches!(&result, Err(InfoSessionError::LoginRequired)) {
                    self.invalidate_service_session(ServiceId::Info);
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("INFO 新闻会话仍已过期，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("INFO 新闻列表自动续接后仍已过期，请重新建立");
                }
            }
            match result {
                Ok(news_page) => {
                    self.remember_news_links(&news_page)?;
                    let generated_at = Utc::now();
                    let mut mapped: InfoNewsPageDto = news_page.into();
                    mapped.generated_at = Some(generated_at.to_rfc3339());
                    mapped.source = Some("live".to_owned());
                    mapped.status = Some("ready".to_owned());
                    mapped.error = None;
                    let payload = InfoNewsPageCachePayload {
                        account_scope: cache_account_scope(&user.username),
                        feed: "list".to_owned(),
                        page,
                        page_size,
                        source_id,
                        channel_id,
                        keyword: String::new(),
                        channel_filter_label: None,
                        exact_match: false,
                        generated_at,
                        items: mapped.items.clone(),
                    };
                    if info_news_cache_payload_is_valid(
                        &payload,
                        &user.username,
                        "list",
                        page,
                        page_size,
                        payload.source_id.as_deref(),
                        payload.channel_id.as_deref(),
                        "",
                        None,
                        false,
                    ) {
                        if let Err(error) = cache.write(&payload) {
                            tracing::warn!(
                                target: "tsinghua_kit::storage",
                                event = "info_news_cache_write_failed",
                                reason = "storage_io",
                                error = %error
                            );
                        }
                    }
                    self.last_error = None;
                    self.persist_resume_state_after_live_read(&user, "info");
                    Ok(mapped)
                }
                Err(error) => {
                    self.last_info_failure_code = Some(info_failure_code(&error));
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    if matches!(
                        error,
                        InfoSessionError::IdentityNotAuthenticated
                            | InfoSessionError::IdentityUserMissing
                            | InfoSessionError::IdentityUserMismatch
                    ) {
                        self.invalidate_service_session(ServiceId::Info);
                    }
                    Err(self.record_error(format!("INFO 新闻列表: {error}")))
                }
            }
        })
        .await
    }

    /// Searches the INFO portal's real news endpoint using its observed
    /// `esParamClass` payload.  `channel_filter_label` is the localized label
    /// expected by the server, not a client-side channel guess.
    pub async fn search_info_news(
        &mut self,
        page: u32,
        keyword: String,
        channel_filter_label: Option<String>,
        exact_match: bool,
    ) -> Result<InfoNewsPageDto, String> {
        self.search_info_news_with_policy(
            page,
            keyword,
            channel_filter_label,
            exact_match,
            ReadPolicy::PreferFreshCache,
        )
        .await
    }

    pub(crate) async fn search_info_news_with_policy(
        &mut self,
        page: u32,
        keyword: String,
        channel_filter_label: Option<String>,
        exact_match: bool,
        policy: ReadPolicy,
    ) -> Result<InfoNewsPageDto, String> {
        crate::telemetry::observe("info", "search_info_news", async {
            if policy != ReadPolicy::CacheOnly {
                self.allow_live_operation()?;
            }
            // Search follows the same cache-first boundary as the ordinary
            // INFO list reader.  An expired Identity snapshot or matching
            // resume metadata is enough to identify an account-bound cache;
            // it is deliberately not enough to authorize the live search
            // request below.
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None if policy == ReadPolicy::CacheOnly => {
                    return Err(self.record_business_failure(
                        "info",
                        "info_news_search",
                        "info_news_cache_miss",
                    ));
                }
                None => self.ensure_identity_user_for_live_read().await?,
            };
            let mut cache = JsonFileCache::<InfoNewsPageCachePayload>::new(
                info_news_cache_path(
                    &self.cache_path,
                    &user.username,
                    "search",
                    page,
                    0,
                    None,
                    None,
                    &keyword,
                    channel_filter_label.as_deref(),
                    exact_match,
                ),
                INFO_NEWS_CACHE_SCHEMA_VERSION,
                INFO_NEWS_CACHE_SERVICE,
            );
            let mut stale_cache = None;
            match cache.read() {
                Ok(Some(envelope))
                    if info_news_cache_payload_is_valid(
                        &envelope.payload,
                        &user.username,
                        "search",
                        page,
                        0,
                        None,
                        None,
                        &keyword,
                        channel_filter_label.as_deref(),
                        exact_match,
                    ) && info_news_cache_is_usable(&envelope.payload.generated_at) =>
                {
                    let payload = envelope.payload;
                    let fresh = info_news_cache_is_fresh(&payload.generated_at);
                    if policy == ReadPolicy::CacheOnly
                        || (fresh
                            && policy != ReadPolicy::RefreshOrCached
                            && policy != ReadPolicy::Refresh)
                    {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            if fresh { "ready" } else { "stale" },
                            None,
                        ));
                    }
                    if policy != ReadPolicy::Refresh {
                        stale_cache = Some(payload);
                    }
                }
                Ok(Some(_)) | Ok(None) => {}
                Err(error) => {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "info_news_cache_read_failed",
                        reason = "cache_unavailable",
                        error = %error
                    );
                }
            }

            if policy == ReadPolicy::CacheOnly {
                return Err(self.record_business_failure(
                    "info",
                    "info_news_search",
                    "info_news_cache_miss",
                ));
            }

            // A cache miss is the only point at which this operation may
            // cross the live Identity boundary.  Refreshing can replace an
            // expired account context, so rebuild the write path using the
            // user actually returned by the verified live boundary.
            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告搜索暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告搜索暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
                cache = JsonFileCache::<InfoNewsPageCachePayload>::new(
                    info_news_cache_path(
                        &self.cache_path,
                        &user.username,
                        "search",
                        page,
                        0,
                        None,
                        None,
                        &keyword,
                        channel_filter_label.as_deref(),
                        exact_match,
                    ),
                    INFO_NEWS_CACHE_SCHEMA_VERSION,
                    INFO_NEWS_CACHE_SERVICE,
                );
            }

            if !self.service_session_is_proven(ServiceId::Info) {
                if let Err(error) = self.ensure_info_reader_session(&user).await {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告搜索暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(error);
                }
            }
            let Some(adapter) = self.info_adapter.as_ref() else {
                return self.fail("INFO 服务会话未建立");
            };
            let mut input =
                NewsSearchInput::new(keyword.clone(), page).with_exact_match(exact_match);
            if let Some(label) = channel_filter_label.clone() {
                input = input.with_channel_filter(label);
            }
            let mut result = Self::search_info_news_once(adapter, &self.coordinator, &input).await;
            if matches!(&result, Err(InfoSessionError::LoginRequired)) {
                self.invalidate_service_session(ServiceId::Info);
                if let Err(error) = self
                    .refresh_nonacademic_service_after_expiry(ServiceId::Info)
                    .await
                {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("INFO 会话续接失败，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(self.record_error(format!("INFO 新闻搜索自动续接失败: {error}")));
                }
                let Some(adapter) = self.info_adapter.as_ref() else {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("INFO 会话续接后仍不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("INFO 新闻搜索自动续接后会话未建立");
                };
                result = Self::search_info_news_once(adapter, &self.coordinator, &input).await;
                if matches!(&result, Err(InfoSessionError::LoginRequired)) {
                    self.invalidate_service_session(ServiceId::Info);
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("INFO 新闻会话仍已过期，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("INFO 新闻搜索自动续接后仍已过期，请重新建立");
                }
            }
            match result {
                Ok(news_page) => {
                    self.remember_news_links(&news_page)?;
                    let generated_at = Utc::now();
                    let mut mapped: InfoNewsPageDto = news_page.into();
                    mapped.generated_at = Some(generated_at.to_rfc3339());
                    mapped.source = Some("live".to_owned());
                    mapped.status = Some("ready".to_owned());
                    mapped.error = None;
                    let payload = InfoNewsPageCachePayload {
                        account_scope: cache_account_scope(&user.username),
                        feed: "search".to_owned(),
                        page,
                        page_size: 0,
                        source_id: None,
                        channel_id: None,
                        keyword,
                        channel_filter_label,
                        exact_match,
                        generated_at,
                        items: mapped.items.clone(),
                    };
                    if info_news_cache_payload_is_valid(
                        &payload,
                        &user.username,
                        "search",
                        page,
                        0,
                        None,
                        None,
                        &payload.keyword,
                        payload.channel_filter_label.as_deref(),
                        exact_match,
                    ) {
                        if let Err(error) = cache.write(&payload) {
                            tracing::warn!(
                                target: "tsinghua_kit::storage",
                                event = "info_news_cache_write_failed",
                                reason = "storage_io",
                                error = %error
                            );
                        }
                    }
                    self.last_error = None;
                    self.persist_resume_state_after_live_read(&user, "info");
                    Ok(mapped)
                }
                Err(error) => {
                    self.last_info_failure_code = Some(info_failure_code(&error));
                    if let Some(payload) = stale_cache.take() {
                        self.remember_cached_news_links(&payload, &user.username)?;
                        self.last_error = None;
                        return Ok(map_info_news_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时公告搜索暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    if matches!(
                        error,
                        InfoSessionError::IdentityNotAuthenticated
                            | InfoSessionError::IdentityUserMissing
                            | InfoSessionError::IdentityUserMismatch
                    ) {
                        self.invalidate_service_session(ServiceId::Info);
                    }
                    Err(self.record_error(format!("INFO 新闻搜索: {error}")))
                }
            }
        })
        .await
    }

    /// Keeps the legacy detail shape for deterministic callers that predate
    /// source-aware INFO payloads. Production Flutter uses the result method
    /// below so cache provenance is not discarded at the Rust boundary.
    pub async fn load_info_news_detail(
        &mut self,
        article_id: String,
    ) -> Result<InfoNewsDetailDto, String> {
        self.load_info_news_detail_result(article_id)
            .await
            .map(|result| InfoNewsDetailDto {
                id: result.id,
                title: result.title,
                content_html: result.content_html,
                summary: result.summary,
                attachments: result.attachments,
            })
    }

    /// Loads one INFO article with an account- and link-bound provenance
    /// envelope. A fresh detail cache is returned before any INFO handoff. A
    /// bounded stale cache is used only after a live handoff/read fails; it is
    /// never presented as a live article and it never establishes INFO proof.
    pub async fn load_info_news_detail_result(
        &mut self,
        article_id: String,
    ) -> Result<InfoNewsDetailResultDto, String> {
        self.load_info_news_detail_result_with_policy(article_id, ReadPolicy::PreferFreshCache)
            .await
    }

    pub(crate) async fn load_info_news_detail_result_with_policy(
        &mut self,
        article_id: String,
        policy: ReadPolicy,
    ) -> Result<InfoNewsDetailResultDto, String> {
        crate::telemetry::observe("info", "load_info_news_detail_result", async {
            if policy != ReadPolicy::CacheOnly {
                self.allow_live_operation()?;
            }
            let article_id = article_id.trim().to_owned();
            if article_id.is_empty() {
                return self.fail("INFO 新闻编号无效");
            }

            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None if policy == ReadPolicy::CacheOnly => {
                    return Err(self.record_business_failure(
                        "info",
                        "info_news_detail",
                        "info_news_cache_miss",
                    ));
                }
                None => self.ensure_identity_user_for_live_read().await?,
            };

            // A detail cache is eligible only when this exact article id is
            // bound to a server-returned link for the current account. The
            // mapping normally lives in memory after a list read; after an app
            // restart, the Rust-owned bounded scanner below recovers the same
            // link from a payload that proves all three values. Directly
            // supplied ids remain live-readable for compatibility, but cannot
            // create a durable cache without a proven link.
            let mut bound_link = (self.info_news_link_owner.as_deref()
                == Some(user.username.as_str()))
            .then(|| self.info_news_links.get(&article_id).cloned())
            .flatten();
            let mut stale_cache = None;
            if let Some(bound_link_value) = bound_link.as_deref() {
                let cache = JsonFileCache::<InfoNewsDetailCachePayload>::new(
                    info_news_detail_cache_path(
                        &self.cache_path,
                        &user.username,
                        &article_id,
                        bound_link_value,
                    ),
                    INFO_NEWS_DETAIL_CACHE_SCHEMA_VERSION,
                    INFO_NEWS_DETAIL_CACHE_SERVICE,
                );
                match cache.read() {
                    Ok(Some(envelope))
                        if info_news_detail_cache_payload_is_valid(
                            &envelope.payload,
                            &user.username,
                            &article_id,
                            bound_link_value,
                        ) && info_news_detail_cache_is_usable(
                            &envelope.payload.generated_at,
                        ) =>
                    {
                        let payload = envelope.payload;
                        let fresh = info_news_detail_cache_is_fresh(&payload.generated_at);
                        if fresh
                            && policy != ReadPolicy::RefreshOrCached
                            && policy != ReadPolicy::Refresh
                        {
                            self.last_error = None;
                            return Ok(map_info_news_detail_cache_payload(
                                &payload, "cache", "ready", None,
                            ));
                        }
                        if policy != ReadPolicy::Refresh {
                            stale_cache = Some(payload);
                        }
                    }
                    Ok(Some(_)) | Ok(None) => {}
                    Err(error) => {
                        tracing::warn!(
                            target: "tsinghua_kit::storage",
                            event = "info_news_detail_cache_read_failed",
                            reason = "cache_unavailable",
                            error = %error
                        );
                    }
                }
            }

            // The first process may have written a detail without the second
            // process having loaded the list. Recover only a matching typed
            // envelope; never turn an arbitrary article id into a path or URL.
            if stale_cache.is_none() {
                if let Some((payload, _path)) =
                    find_info_news_detail_cache(&self.cache_path, &user.username, &article_id)
                {
                    bound_link = Some(payload.bound_link.clone());
                    let fresh = info_news_detail_cache_is_fresh(&payload.generated_at);
                    if policy == ReadPolicy::CacheOnly
                        || (fresh
                            && policy != ReadPolicy::RefreshOrCached
                            && policy != ReadPolicy::Refresh)
                    {
                        self.last_error = None;
                        return Ok(map_info_news_detail_cache_payload(
                            &payload,
                            "cache",
                            if fresh { "ready" } else { "stale" },
                            None,
                        ));
                    }
                    if policy != ReadPolicy::Refresh {
                        stale_cache = Some(payload);
                    }
                }
            }
            let detail_cache = bound_link.as_deref().map(|link| {
                JsonFileCache::<InfoNewsDetailCachePayload>::new(
                    info_news_detail_cache_path(
                        &self.cache_path,
                        &user.username,
                        &article_id,
                        link,
                    ),
                    INFO_NEWS_DETAIL_CACHE_SCHEMA_VERSION,
                    INFO_NEWS_DETAIL_CACHE_SERVICE,
                )
            });

            if policy == ReadPolicy::CacheOnly {
                if let Some(payload) = stale_cache.take() {
                    self.last_error = None;
                    return Ok(map_info_news_detail_cache_payload(
                        &payload, "cache", "stale", None,
                    ));
                }
                return Err(self.record_business_failure(
                    "info",
                    "info_news_detail",
                    "info_news_cache_miss",
                ));
            }

            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_info_news_detail_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时新闻详情暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_info_news_detail_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时新闻详情暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
            }

            // A stale detail should still make one normal live attempt when
            // identity is proven. This also lets an app restart rebuild INFO
            // lazily; if the handoff is unavailable, the bounded cache below
            // remains useful without pretending that INFO is authenticated.
            if !self.service_session_is_proven(ServiceId::Info) {
                if let Err(error) = self.ensure_info_reader_session(&user).await {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_info_news_detail_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时新闻详情暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(error);
                }
            }
            let Some(adapter) = self.info_adapter.as_ref() else {
                if let Some(payload) = stale_cache.take() {
                    self.last_error = None;
                    return Ok(map_info_news_detail_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some("INFO 服务会话未建立，当前显示已验证缓存".to_owned()),
                    ));
                }
                return self.fail("INFO 服务会话未建立");
            };
            if let Some(expected_link) = bound_link.as_deref() {
                if self.info_news_link_owner.as_deref() != Some(user.username.as_str())
                    || self.info_news_links.get(&article_id).map(String::as_str)
                        != Some(expected_link)
                {
                    self.invalidate_info_news_links();
                    return Err(self.record_business_failure(
                        "info",
                        "info_detail",
                        "info_news_account_changed",
                    ));
                }
            }
            let link = bound_link.clone().unwrap_or_else(|| article_id.clone());
            let replay_fence = self.identity.transport().replay_fence();
            let mut result =
                Self::fetch_info_news_detail_once(adapter, &self.coordinator, &link).await;
            if matches!(&result, Err(InfoSessionError::LoginRequired)) {
                self.invalidate_service_session(ServiceId::Info);
                // A typed login response can authorize session reconciliation,
                // but never reusing a ticketed article navigation that has
                // already crossed the consuming-dispatch boundary.
                if !replay_fence.permits_probe_retry(self.identity.transport()) {
                    if let Some(payload) = stale_cache.take() {
                        return Ok(map_info_news_detail_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("新闻链接需要重新验证，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(self.record_business_failure(
                        "info",
                        "info_detail",
                        "info_news_reauth_needs_user",
                    ));
                }
                if let Err(error) = self
                    .refresh_nonacademic_service_after_expiry(ServiceId::Info)
                    .await
                {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_info_news_detail_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("INFO 新闻详情自动续接失败，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(self.record_error(format!("INFO 新闻详情自动续接失败: {error}")));
                }
                let Some(adapter) = self.info_adapter.as_ref() else {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_info_news_detail_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some(
                                "INFO 新闻详情自动续接后会话未建立，当前显示已验证缓存".to_owned(),
                            ),
                        ));
                    }
                    return self.fail("INFO 新闻详情自动续接后会话未建立");
                };
                result = Self::fetch_info_news_detail_once(adapter, &self.coordinator, &link).await;
                if matches!(&result, Err(InfoSessionError::LoginRequired)) {
                    self.invalidate_service_session(ServiceId::Info);
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_info_news_detail_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("INFO 新闻详情自动续接后仍已过期，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("INFO 新闻详情自动续接后仍已过期，请重新建立");
                }
            }
            match result {
                Ok(mut detail) => {
                    if detail.id.is_empty() {
                        detail.id = article_id.clone();
                    }
                    let generated_at = Utc::now();
                    let mapped = InfoNewsDetailResultDto {
                        // The adapter validates the concrete upstream xxid /
                        // publication id. The facade identity is the requested
                        // list item (or exact link), matching its cache key and
                        // Flutter's requestedArticleId contract.
                        id: article_id.clone(),
                        title: detail.title.clone(),
                        content_html: detail.content_html.clone(),
                        summary: detail.summary.clone(),
                        attachments: detail
                            .attachments
                            .iter()
                            .map(|attachment| InfoNewsAttachmentDto {
                                id: attachment.id.clone(),
                                name: attachment.name.clone(),
                            })
                            .collect(),
                        generated_at: generated_at.to_rfc3339(),
                        source: "live".to_owned(),
                        status: "ready".to_owned(),
                        error: None,
                    };
                    if let (Some(cache), Some(bound_link)) =
                        (detail_cache.as_ref(), bound_link.as_deref())
                    {
                        let payload = InfoNewsDetailCachePayload {
                            account_scope: cache_account_scope(&user.username),
                            article_id: article_id.clone(),
                            bound_link: bound_link.to_owned(),
                            generated_at,
                            title: detail.title,
                            content_html: detail.content_html,
                            summary: detail.summary,
                            attachments: mapped.attachments.clone(),
                        };
                        if info_news_detail_cache_payload_is_valid(
                            &payload,
                            &user.username,
                            &article_id,
                            bound_link,
                        ) {
                            if let Err(error) = cache.write(&payload) {
                                tracing::warn!(
                                    target: "tsinghua_kit::storage",
                                    event = "info_news_detail_cache_write_failed",
                                    reason = "storage_io",
                                    error = %error
                                );
                            }
                        }
                    }
                    self.last_error = None;
                    self.persist_resume_state_after_live_read(&user, "info");
                    Ok(mapped)
                }
                Err(error) => {
                    self.last_info_failure_code = Some(info_failure_code(&error));
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_info_news_detail_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时新闻详情暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    if matches!(
                        error,
                        InfoSessionError::IdentityNotAuthenticated
                            | InfoSessionError::IdentityUserMissing
                            | InfoSessionError::IdentityUserMismatch
                    ) {
                        self.invalidate_service_session(ServiceId::Info);
                    }
                    Err(self.record_business_failure(
                        "info",
                        "info_detail",
                        info_failure_code(&error),
                    ))
                }
            }
        })
        .await
    }

    /// Legacy area-tree shape retained for small deterministic gateways.
    pub async fn load_library_area_tree(
        &mut self,
    ) -> Result<crate::library_read::LibraryAreaTreeDto, String> {
        self.load_library_area_tree_result().await.map(|result| {
            crate::library_read::LibraryAreaTreeDto {
                areas: result.areas,
            }
        })
    }

    /// Reads the library area directory with an account-bound cache. The
    /// cache contains only the directory; seat inventory and socket state
    /// continue to require a live request.
    pub async fn load_library_area_tree_result(
        &mut self,
    ) -> Result<LibraryAreaTreeResultDto, String> {
        crate::telemetry::observe("library", "load_library_area_tree_result", async {
            self.allow_live_operation()?;
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            let cache = JsonFileCache::<LibraryAreaTreeCachePayload>::new(
                library_area_cache_path(&self.cache_path, &user.username),
                LIBRARY_AREA_CACHE_SCHEMA_VERSION,
                LIBRARY_AREA_CACHE_SERVICE,
            );
            let mut stale_cache = None;
            match cache.read() {
                Ok(Some(envelope))
                    if library_area_tree_cache_payload_is_valid(
                        &envelope.payload,
                        &user.username,
                    ) && library_area_cache_is_usable(&envelope.payload.generated_at) =>
                {
                    let payload = envelope.payload;
                    if library_area_cache_is_fresh(&payload.generated_at) {
                        self.remember_library_section_ids(&payload.areas);
                        self.last_error = None;
                        return Ok(map_library_area_cache_payload(
                            &payload, "cache", "ready", None,
                        ));
                    }
                    stale_cache = Some(payload);
                }
                Ok(Some(_)) | Ok(None) => {}
                Err(error) => {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "library_area_cache_read_failed",
                        reason = "cache_unavailable",
                        error = %error
                    );
                }
            }

            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_library_section_ids(&payload.areas);
                        self.last_error = None;
                        return Ok(map_library_area_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时图书馆区域暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_library_section_ids(&payload.areas);
                        self.last_error = None;
                        return Ok(map_library_area_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时图书馆区域暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
            }

            if !self.service_session_is_proven(ServiceId::Library) {
                if let Err(error) = self.ensure_info_and_library(&user).await {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_library_section_ids(&payload.areas);
                        self.last_error = None;
                        return Ok(map_library_area_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时图书馆区域暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(error);
                }
            }
            let Some(adapter) = self.library_adapter.as_ref() else {
                if let Some(payload) = stale_cache.take() {
                    self.remember_library_section_ids(&payload.areas);
                    self.last_error = None;
                    return Ok(map_library_area_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some("图书馆服务会话未建立，当前显示已验证缓存".to_owned()),
                    ));
                }
                return self.fail("图书馆服务会话未建立");
            };
            let mut result = if let Some(tree) = self.library_area_tree_prefetch.take() {
                Ok(tree)
            } else {
                adapter.read_area_tree().await
            };
            if matches!(&result, Err(error) if error.is_session_expired()) {
                self.invalidate_service_session(ServiceId::Library);
                if let Err(error) = self
                    .refresh_nonacademic_service_after_expiry(ServiceId::Library)
                    .await
                {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_library_section_ids(&payload.areas);
                        self.last_error = None;
                        return Ok(map_library_area_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("图书馆区域自动续接失败，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(self.record_error(format!("图书馆区域自动续接失败: {error}")));
                }
                result = if let Some(tree) = self.library_area_tree_prefetch.take() {
                    Ok(tree)
                } else {
                    let Some(adapter) = self.library_adapter.as_ref() else {
                        if let Some(payload) = stale_cache.take() {
                            self.remember_library_section_ids(&payload.areas);
                            self.last_error = None;
                            return Ok(map_library_area_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some(
                                    "图书馆区域自动续接后会话未建立，当前显示已验证缓存".to_owned(),
                                ),
                            ));
                        }
                        return self.fail("图书馆区域自动续接后会话未建立");
                    };
                    adapter.read_area_tree().await
                };
                if matches!(&result, Err(error) if error.is_session_expired()) {
                    self.invalidate_service_session(ServiceId::Library);
                    if let Some(payload) = stale_cache.take() {
                        self.remember_library_section_ids(&payload.areas);
                        self.last_error = None;
                        return Ok(map_library_area_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("图书馆区域自动续接后仍已过期，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("图书馆区域自动续接后仍已过期，请重新建立");
                }
            }
            match result {
                Ok(tree) => {
                    self.remember_library_section_ids(&tree.areas);
                    let generated_at = Utc::now();
                    let payload = LibraryAreaTreeCachePayload {
                        account_scope: cache_account_scope(&user.username),
                        generated_at,
                        areas: tree.areas.clone(),
                    };
                    if library_area_tree_cache_payload_is_valid(&payload, &user.username) {
                        if let Err(error) = cache.write(&payload) {
                            tracing::warn!(
                                target: "tsinghua_kit::storage",
                                event = "library_area_cache_write_failed",
                                reason = "storage_io",
                                error = %error
                            );
                        }
                    }
                    self.last_error = None;
                    self.persist_resume_state_after_live_read(&user, "library");
                    Ok(map_library_area_cache_payload(
                        &payload, "live", "ready", None,
                    ))
                }
                Err(error) => {
                    if let Some(payload) = stale_cache.take() {
                        self.remember_library_section_ids(&payload.areas);
                        self.last_error = None;
                        return Ok(map_library_area_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时图书馆区域暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    Err(self.record_business_failure(
                        "library",
                        "library_read",
                        error.diagnostic_code(),
                    ))
                }
            }
        })
        .await
    }

    /// Reads floors only for a library id confirmed by this Runtime's root
    /// directory. A root id is never passed to the day-segment endpoint.
    pub async fn load_library_floors(
        &mut self,
        library_id: u64,
    ) -> Result<crate::library_read::LibraryAreaTreeDto, String> {
        crate::telemetry::observe("library", "load_library_floors", async {
            self.allow_live_operation()?;
            if library_id == 0 || !self.library_root_ids.contains(&library_id) {
                return self.fail("图书馆编号未在已验证目录中");
            }
            self.library_seat_hierarchy_active = true;
            let user = self.ensure_identity_user_for_live_read().await?;
            if !self.service_session_is_proven(ServiceId::Library) {
                self.ensure_info_and_library(&user).await?;
            }
            // Recheck after a handoff: a cache-backed directory must not
            // authorize an id that the current server directory removed.
            if !self.library_root_ids.contains(&library_id) {
                return self.fail("图书馆编号不在当前服务目录中");
            }
            let adapter = self
                .library_adapter
                .as_ref()
                .ok_or("图书馆服务会话未建立")?;
            let result = adapter.read_area_children(library_id).await;
            let floors = self.accept_library_discovery(result)?;
            self.library_floor_ids = floors
                .areas
                .iter()
                .filter(|area| area.id > 0 && area.is_valid != Some(false))
                .map(|area| area.id)
                .collect();
            self.library_seat_section_ids.clear();
            self.library_confirmed_seat_windows.clear();
            self.extend_library_section_ids(&floors.areas);
            self.library_area_tree_prefetch = None;
            self.last_error = None;
            self.persist_identity_resume_state_after_live_read("library");
            Ok(floors)
        })
        .await
    }

    /// Reads selectable seat sections beneath a confirmed floor. The date
    /// choice is bounded to today or tomorrow, matching the reference flow.
    pub async fn load_library_sections_for_day(
        &mut self,
        floor_id: u64,
        day_offset: u8,
    ) -> Result<crate::library_read::LibraryAreaTreeDto, String> {
        if day_offset > 1 {
            return self.fail("图书馆日期选择无效");
        }
        let day = campus_date_at(Utc::now())
            .checked_add_days(chrono::Days::new(u64::from(day_offset)))
            .ok_or("图书馆日期选择无效")?
            .format("%Y-%m-%d")
            .to_string();
        self.load_library_sections_for_campus_date(floor_id, day)
            .await
    }

    /// Reads sections for one exact, currently supported campus date. Keeping
    /// the validated date fixed across authentication handoff avoids turning a
    /// `Today` selection into a different request if midnight passes in flight.
    pub(crate) async fn load_library_sections_for_campus_date(
        &mut self,
        floor_id: u64,
        requested_day: String,
    ) -> Result<crate::library_read::LibraryAreaTreeDto, String> {
        crate::telemetry::observe("library", "load_library_sections_for_day", async {
            self.allow_live_operation()?;
            let parsed_day = NaiveDate::parse_from_str(&requested_day, "%Y-%m-%d")
                .map_err(|_| String::from("图书馆日期选择无效"))?;
            if parsed_day.format("%Y-%m-%d").to_string() != requested_day {
                return self.fail("图书馆日期选择无效");
            }
            if !library_campus_date_is_current_or_tomorrow(parsed_day, Utc::now()) {
                return self.fail("图书馆日期选择已过期，请重新选择");
            }
            if floor_id == 0 || !self.library_floor_ids.contains(&floor_id) {
                return self.fail("图书馆楼层编号未在已验证目录中");
            }
            self.ensure_library_reader_session().await?;
            if !library_campus_date_is_current_or_tomorrow(parsed_day, Utc::now()) {
                return self.fail("图书馆日期选择已过期，请重新选择");
            }
            if !self.library_floor_ids.contains(&floor_id) {
                return self.fail("图书馆楼层目录已更新，请重新选择");
            }
            let day = requested_day;
            let adapter = self
                .library_adapter
                .as_ref()
                .ok_or("图书馆服务会话未建立")?;
            let result = adapter.read_area_for_day(floor_id, &day).await;
            if !library_campus_date_is_current_or_tomorrow(parsed_day, Utc::now()) {
                return self.fail("图书馆日期选择已过期，请重新选择");
            }
            let sections = self.accept_library_discovery(result)?;
            self.library_seat_section_ids = valid_library_area_ids(&sections.areas);
            self.library_confirmed_seat_windows.clear();
            self.extend_library_section_ids(&sections.areas);
            self.library_area_tree_prefetch = None;
            self.last_error = None;
            self.persist_identity_resume_state_after_live_read("library");
            Ok(sections)
        })
        .await
    }

    /// Legacy opening-window shape retained for small deterministic gateways.
    pub async fn load_library_day_segments(
        &mut self,
        section_id: u64,
    ) -> Result<crate::library_read::LibraryDaySegmentsDto, String> {
        self.load_library_day_segments_result(section_id)
            .await
            .map(|result| crate::library_read::LibraryDaySegmentsDto {
                segments: result.segments,
            })
    }

    /// Reads one section's opening windows with a section-bound cache. Seat
    /// availability is intentionally outside this cache path.
    pub async fn load_library_day_segments_result(
        &mut self,
        section_id: u64,
    ) -> Result<LibraryDaySegmentsResultDto, String> {
        self.load_library_day_segments_result_for_date(section_id, None)
            .await
    }

    /// Only returns windows for the requested local date. The full verified
    /// response stays in the account/section cache, while a cache from before
    /// midnight that never covered this date cannot turn into false empty.
    pub async fn load_library_day_segments_for_day_result(
        &mut self,
        section_id: u64,
        day_offset: u8,
    ) -> Result<LibraryDaySegmentsResultDto, String> {
        if day_offset > 1 {
            return self.fail("图书馆日期选择无效");
        }
        let day = campus_date_at(Utc::now())
            .checked_add_days(chrono::Days::new(u64::from(day_offset)))
            .ok_or("图书馆日期选择无效")?
            .format("%Y-%m-%d")
            .to_string();
        self.load_library_day_segments_for_campus_date_result(section_id, day)
            .await
    }

    /// Reads the opening windows for an exact currently supported campus
    /// date, preserving that selector if an authentication handoff crosses
    /// midnight.
    pub(crate) async fn load_library_day_segments_for_campus_date_result(
        &mut self,
        section_id: u64,
        requested_day: String,
    ) -> Result<LibraryDaySegmentsResultDto, String> {
        if section_id == 0 {
            return self.fail("图书馆区域编号无效");
        }
        let parsed_day = NaiveDate::parse_from_str(&requested_day, "%Y-%m-%d")
            .map_err(|_| String::from("图书馆日期选择无效"))?;
        if parsed_day.format("%Y-%m-%d").to_string() != requested_day {
            return self.fail("图书馆日期选择无效");
        }
        if !library_campus_date_is_current_or_tomorrow(parsed_day, Utc::now()) {
            return self.fail("图书馆日期选择已过期，请重新选择");
        }
        let mut result = self
            .load_library_day_segments_result_for_date(section_id, Some(&requested_day))
            .await?;
        if !library_campus_date_is_current_or_tomorrow(parsed_day, Utc::now()) {
            return self.fail("图书馆日期选择已过期，请重新选择");
        }
        result
            .segments
            .retain(|segment| segment.day == requested_day);
        if self.library_seat_hierarchy_active && self.library_seat_section_ids.contains(&section_id)
        {
            self.library_confirmed_seat_windows
                .insert(section_id, result.segments.clone());
        }
        Ok(result)
    }

    async fn load_library_day_segments_result_for_date(
        &mut self,
        section_id: u64,
        required_day: Option<&str>,
    ) -> Result<LibraryDaySegmentsResultDto, String> {
        crate::telemetry::observe("library", "load_library_day_segments_result", async {
            self.allow_live_operation()?;
            if section_id == 0 {
                return self.fail("图书馆区域编号无效");
            }
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            let cache = JsonFileCache::<LibraryDaySegmentsCachePayload>::new(
                library_segment_cache_path(&self.cache_path, &user.username, section_id),
                LIBRARY_SEGMENT_CACHE_SCHEMA_VERSION,
                LIBRARY_SEGMENT_CACHE_SERVICE,
            );
            let mut stale_cache = None;
            // The cache file is already account- and section-bound, so it is
            // safe to inspect it before the in-memory area directory has been
            // hydrated. `library_section_ids` belongs to one Runtime only;
            // using it as a cache-read gate made a fresh process discard a
            // valid persisted segment and unnecessarily redo the library
            // handoff. The live path below still requires the section to be
            // present in a verified directory before dispatching a request.
            match cache.read() {
                Ok(Some(envelope))
                    if library_day_segments_cache_payload_is_valid(
                        &envelope.payload,
                        &user.username,
                        section_id,
                    ) && library_segment_cache_is_usable(&envelope.payload.generated_at) =>
                {
                    let payload = envelope.payload;
                    let covers_day = required_day.is_none_or(|day| {
                        payload.segments.iter().any(|segment| segment.day == day)
                            || campus_date_at(payload.generated_at) == campus_date_at(Utc::now())
                    });
                    if covers_day {
                        if library_segment_cache_is_fresh(&payload.generated_at) {
                            self.last_error = None;
                            return Ok(map_library_segment_cache_payload(
                                &payload, "cache", "ready", None,
                            ));
                        }
                        stale_cache = Some(payload);
                    }
                }
                Ok(Some(_)) | Ok(None) => {}
                Err(error) => {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "library_segment_cache_read_failed",
                        reason = "cache_unavailable",
                        error = %error
                    );
                }
            }

            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_library_segment_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时图书馆时段暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_library_segment_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时图书馆时段暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
            }

            if !self.service_session_is_proven(ServiceId::Library) {
                if let Err(error) = self.ensure_info_and_library(&user).await {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_library_segment_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时图书馆时段暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(error);
                }
            }
            let Some(adapter) = self.library_adapter.as_ref() else {
                if let Some(payload) = stale_cache.take() {
                    self.last_error = None;
                    return Ok(map_library_segment_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some("图书馆服务会话未建立，当前显示已验证缓存".to_owned()),
                    ));
                }
                return self.fail("图书馆服务会话未建立");
            };
            if !self.library_section_ids.contains(&section_id)
                || (self.library_seat_hierarchy_active
                    && !self.library_seat_section_ids.contains(&section_id))
            {
                if let Some(payload) = stale_cache.take() {
                    self.last_error = None;
                    return Ok(map_library_segment_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some("实时图书馆时段暂时不可用，当前显示已验证缓存".to_owned()),
                    ));
                }
                return Err(self.record_business_failure(
                    "library",
                    "library_read",
                    "library_section_unconfirmed",
                ));
            }
            self.library_area_tree_prefetch = None;
            let mut result = adapter.read_day_segments(section_id).await;
            if matches!(&result, Err(error) if error.is_session_expired()) {
                self.invalidate_service_session(ServiceId::Library);
                if let Err(error) = self
                    .refresh_nonacademic_service_after_expiry(ServiceId::Library)
                    .await
                {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_library_segment_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("图书馆时段自动续接失败，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(self.record_error(format!("图书馆时段自动续接失败: {error}")));
                }
                let Some(adapter) = self.library_adapter.as_ref() else {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_library_segment_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("图书馆时段自动续接后会话未建立，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("图书馆时段自动续接后会话未建立");
                };
                if self.library_seat_hierarchy_active
                    && !self.library_seat_section_ids.contains(&section_id)
                {
                    return self.fail("图书馆分区目录已更新，请重新选择");
                }
                result = adapter.read_day_segments(section_id).await;
                if matches!(&result, Err(error) if error.is_session_expired()) {
                    self.invalidate_service_session(ServiceId::Library);
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_library_segment_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("图书馆时段自动续接后仍已过期，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("图书馆时段自动续接后仍已过期，请重新建立");
                }
            }
            match result {
                Ok(segments) => {
                    let generated_at = Utc::now();
                    let payload = LibraryDaySegmentsCachePayload {
                        account_scope: cache_account_scope(&user.username),
                        section_id,
                        generated_at,
                        segments: segments.segments.clone(),
                    };
                    if library_day_segments_cache_payload_is_valid(
                        &payload,
                        &user.username,
                        section_id,
                    ) {
                        if let Err(error) = cache.write(&payload) {
                            tracing::warn!(
                                target: "tsinghua_kit::storage",
                                event = "library_segment_cache_write_failed",
                                reason = "storage_io",
                                error = %error
                            );
                        }
                    }
                    self.last_error = None;
                    self.persist_resume_state_after_live_read(&user, "library");
                    Ok(map_library_segment_cache_payload(
                        &payload, "live", "ready", None,
                    ))
                }
                Err(error) => {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_library_segment_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时图书馆时段暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    Err(self.record_business_failure(
                        "library",
                        "library_read",
                        error.diagnostic_code(),
                    ))
                }
            }
        })
        .await
    }

    /// Reads seat availability using bounded, validated selectors.
    pub async fn load_library_seats(
        &mut self,
        area_id: u64,
        segment_id: u64,
        day: String,
        start_time: String,
        end_time: String,
    ) -> Result<crate::library_read::LibrarySeatAvailabilityDto, String> {
        crate::telemetry::observe("library", "load_library_seats", async {
            self.allow_live_operation()?;
            self.ensure_library_reader_session().await?;
            if self.library_seat_hierarchy_active
                && !self.library_seat_section_ids.contains(&area_id)
            {
                return Err(self.record_business_failure(
                    "library",
                    "library_read",
                    "library_section_unconfirmed",
                ));
            }
            if self.library_seat_hierarchy_active
                && !self
                    .library_confirmed_seat_windows
                    .get(&area_id)
                    .is_some_and(|windows| {
                        windows.iter().any(|window| {
                            window.id == segment_id
                                && window.day == day
                                && window.start_time == start_time
                                && window.end_time == end_time
                        })
                    })
            {
                return Err(self.record_business_failure(
                    "library",
                    "library_read",
                    "library_segment_unconfirmed",
                ));
            }
            // THU Info advances today's request start to the current campus
            // time. Keeping the original segment start can ask the service
            // for already elapsed seats; the selected window remains bound
            // above to the exact server-proven segment.
            let request_start =
                match library_seat_request_start_at(&day, &start_time, &end_time, Utc::now()) {
                    Ok(start) => start,
                    Err(reason) => return self.fail(reason),
                };
            let Some(adapter) = self.library_adapter.as_ref() else {
                return self.fail("图书馆服务会话未建立");
            };
            self.library_area_tree_prefetch = None;
            let mut result = adapter
                .read_seat_availability(area_id, segment_id, &day, &request_start, &end_time)
                .await;
            if matches!(&result, Err(error) if error.is_session_expired()) {
                self.invalidate_service_session(ServiceId::Library);
                if let Err(error) = self
                    .refresh_nonacademic_service_after_expiry(ServiceId::Library)
                    .await
                {
                    return Err(self.record_error(format!("图书馆座位自动续接失败: {error}")));
                }
                let Some(adapter) = self.library_adapter.as_ref() else {
                    return self.fail("图书馆座位自动续接后会话未建立");
                };
                if self.library_seat_hierarchy_active {
                    return self.fail("图书馆座位目录已更新，请重新选择");
                }
                result = adapter
                    .read_seat_availability(area_id, segment_id, &day, &request_start, &end_time)
                    .await;
                if matches!(&result, Err(error) if error.is_session_expired()) {
                    self.invalidate_service_session(ServiceId::Library);
                    return self.fail("图书馆座位自动续接后仍已过期，请重新建立");
                }
            }
            match result {
                Ok(seats) => {
                    self.last_error = None;
                    self.persist_identity_resume_state_after_live_read("library");
                    Ok(seats)
                }
                Err(error) => Err(self.record_business_failure(
                    "library",
                    "library_read",
                    error.diagnostic_code(),
                )),
            }
        })
        .await
    }

    /// Reads the independent socket-status endpoint for one section while
    /// retaining the library handoff's Cookie-aware transport. The socket
    /// service is a separate response contract from seat inventory, so the
    /// returned records are kept as their own DTO and are never merged by
    /// this method.
    pub async fn load_library_socket_status(
        &mut self,
        section_id: u64,
    ) -> Result<crate::library_read::LibrarySocketStatusesDto, String> {
        crate::telemetry::observe("library", "load_library_socket_status", async {
            self.allow_live_operation()?;
            self.ensure_library_reader_session().await?;
            let Some(adapter) = self.library_adapter.as_ref() else {
                return self.fail("图书馆服务会话未建立");
            };
            self.library_area_tree_prefetch = None;
            let socket = adapter
                .app_socket_status_adapter()
                .map_err(|error| self.record_error(format!("library socket adapter: {error}")))?;
            let mut result = socket.read_section_status(section_id).await;
            if matches!(&result, Err(error) if error.is_session_expired()) {
                self.invalidate_service_session(ServiceId::Library);
                if let Err(error) = self
                    .refresh_nonacademic_service_after_expiry(ServiceId::Library)
                    .await
                {
                    return Err(self.record_error(format!("图书馆插座状态自动续接失败: {error}")));
                }
                let Some(adapter) = self.library_adapter.as_ref() else {
                    return self.fail("图书馆插座状态自动续接后会话未建立");
                };
                let socket = adapter.app_socket_status_adapter().map_err(|error| {
                    self.record_error(format!("library socket adapter: {error}"))
                })?;
                result = socket.read_section_status(section_id).await;
                if matches!(&result, Err(error) if error.is_session_expired()) {
                    self.invalidate_service_session(ServiceId::Library);
                    return self.fail("图书馆插座状态自动续接后仍已过期，请重新建立");
                }
            }
            match result {
                Ok(statuses) => {
                    self.last_error = None;
                    self.persist_identity_resume_state_after_live_read("library");
                    Ok(statuses)
                }
                Err(error) => Err(self.record_business_failure(
                    "library",
                    "library_read",
                    error.diagnostic_code(),
                )),
            }
        })
        .await
    }

    /// Legacy classroom directory shape retained for deterministic gateways.
    pub async fn load_classroom_buildings(&mut self) -> Result<Vec<ClassroomBuildingDto>, String> {
        self.load_classroom_buildings_result()
            .await
            .map(|result| result.buildings)
    }

    /// Reads the slowly changing classroom directory with an account-bound
    /// cache. A cached directory does not prove the current weekly matrix or
    /// the classroom service session; the state method still performs a live
    /// directory read before sending its server-side selector.
    pub async fn load_classroom_buildings_result(
        &mut self,
    ) -> Result<ClassroomBuildingsResultDto, String> {
        crate::telemetry::observe("classroom", "load_classroom_buildings_result", async {
            self.allow_live_operation()?;
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            let cache = JsonFileCache::<ClassroomBuildingCachePayload>::new(
                classroom_building_cache_path(&self.cache_path, &user.username),
                CLASSROOM_BUILDING_CACHE_SCHEMA_VERSION,
                CLASSROOM_BUILDING_CACHE_SERVICE,
            );
            let mut stale_cache = None;
            match cache.read() {
                Ok(Some(envelope))
                    if classroom_building_cache_payload_is_valid(
                        &envelope.payload,
                        &user.username,
                    ) && classroom_building_cache_is_usable(&envelope.payload.generated_at) =>
                {
                    let payload = envelope.payload;
                    if classroom_building_cache_is_fresh(&payload.generated_at) {
                        self.classroom_cached_directory = Some(payload.buildings.clone());
                        self.last_error = None;
                        return Ok(map_classroom_building_cache_payload(
                            &payload, "cache", "ready", None,
                        ));
                    }
                    stale_cache = Some(payload);
                }
                Ok(Some(_)) | Ok(None) => {}
                Err(error) => {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "classroom_building_cache_read_failed",
                        reason = "cache_unavailable",
                        error = %error
                    );
                }
            }

            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = stale_cache.take() {
                        self.classroom_cached_directory = Some(payload.buildings.clone());
                        self.last_error = None;
                        return Ok(map_classroom_building_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时教室楼栋暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = stale_cache.take() {
                        self.classroom_cached_directory = Some(payload.buildings.clone());
                        self.last_error = None;
                        return Ok(map_classroom_building_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时教室楼栋暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
            }

            if let Err(error) = self.ensure_classroom_reader_session(&user).await {
                if let Some(payload) = stale_cache.take() {
                    self.classroom_cached_directory = Some(payload.buildings.clone());
                    self.last_error = None;
                    return Ok(map_classroom_building_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some("实时教室楼栋暂时不可用，当前显示已验证缓存".to_owned()),
                    ));
                }
                return Err(error);
            }
            let Some(list) = self.classroom_buildings.as_ref() else {
                if let Some(payload) = stale_cache.take() {
                    self.classroom_cached_directory = Some(payload.buildings.clone());
                    self.last_error = None;
                    return Ok(map_classroom_building_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some("教室服务目录未确认，当前显示已验证缓存".to_owned()),
                    ));
                }
                return self.fail("教室服务会话建立状态未确认");
            };
            let generated_at = Utc::now();
            let payload = ClassroomBuildingCachePayload {
                account_scope: cache_account_scope(&user.username),
                generated_at,
                buildings: map_classroom_buildings(list)
                    .into_iter()
                    .map(|building| ClassroomBuildingCacheRecord {
                        name: building.name,
                        week_number: building.week_number,
                    })
                    .collect(),
            };
            if classroom_building_cache_payload_is_valid(&payload, &user.username) {
                self.classroom_cached_directory = Some(payload.buildings.clone());
                if let Err(error) = cache.write(&payload) {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "classroom_building_cache_write_failed",
                        reason = "storage_io",
                        error = %error
                    );
                }
            }
            self.last_error = None;
            self.persist_resume_state_after_live_read(&user, "classroom");
            Ok(map_classroom_building_cache_payload(
                &payload, "live", "ready", None,
            ))
        })
        .await
    }

    /// Reads one weekly classroom matrix by the index returned from
    /// `load_classroom_buildings`.  Building selectors and the session proof
    /// stay inside the Rust runtime.
    pub async fn load_classroom_state(
        &mut self,
        building_index: u32,
        week_number: u32,
    ) -> Result<ClassroomStateResultDto, String> {
        crate::telemetry::observe("classroom", "load_classroom_state", async {
            self.allow_live_operation()?;
            let mut user = self.ensure_identity_user_for_live_read().await?;
            self.ensure_classroom_reader_session(&user).await?;
            self.ensure_classroom_directory_matches_cached()?;

            let index = building_index as usize;
            let mut result = {
                let Some(list) = self.classroom_buildings.as_ref() else {
                    return self.fail("教室服务会话未建立");
                };
                if index >= list.buildings.len() {
                    return self.fail("教室楼栋编号无效，请先刷新楼栋列表");
                }
                let Some(adapter) = self.classroom_adapter.as_ref() else {
                    return self.fail("教室服务会话未建立");
                };
                adapter.read_state_from_list(list, index, week_number).await
            };
            if matches!(&result, Err(error) if error.is_session_expired()) {
                self.invalidate_classroom_session();
                if let Err(error) = self
                    .refresh_nonacademic_service_after_expiry(ServiceId::Info)
                    .await
                {
                    return Err(self.record_error(format!("教室矩阵自动续接失败: {error}")));
                }
                user = self.ensure_identity_user_for_live_read().await?;
                self.ensure_classroom_session(&user).await?;
                self.ensure_classroom_directory_matches_cached()?;
                result = {
                    let Some(list) = self.classroom_buildings.as_ref() else {
                        return self.fail("教室矩阵自动续接后会话未建立");
                    };
                    if index >= list.buildings.len() {
                        return self.fail("教室楼栋编号无效，请先刷新楼栋列表");
                    }
                    let Some(adapter) = self.classroom_adapter.as_ref() else {
                        return self.fail("教室矩阵自动续接后会话未建立");
                    };
                    adapter.read_state_from_list(list, index, week_number).await
                };
                if matches!(&result, Err(error) if error.is_session_expired()) {
                    self.invalidate_classroom_session();
                    return self.fail("教室矩阵自动续接后仍已过期，请重新建立");
                }
            }
            match result {
                Ok(result) => {
                    self.last_error = None;
                    self.persist_resume_state_after_live_read(&user, "classroom");
                    Ok(map_classroom_state(result))
                }
                Err(error) => Err(self.record_business_failure(
                    "classroom",
                    "classroom_read",
                    error.diagnostic_code(),
                )),
            }
        })
        .await
    }

    /// Legacy electricity-remainder shape retained for deterministic callers.
    /// Production Flutter uses the result envelope below so a stale fallback
    /// cannot be rendered as a current balance.
    pub async fn load_electricity_remainder(&mut self) -> Result<ElectricityRemainderDto, String> {
        self.load_electricity_remainder_result()
            .await
            .map(|result| ElectricityRemainderDto {
                remainder: result.remainder,
                update_time: result.update_time,
            })
    }

    /// Reads the electricity remainder with a Rust-owned, account-bound cache.
    /// A fresh cache is usable without Identity or INFO proof.  A bounded
    /// stale value is returned only when live recovery/read cannot be
    /// confirmed, and its `source/status/error` fields make that degradation
    /// explicit to the bridge.
    pub async fn load_electricity_remainder_result(
        &mut self,
    ) -> Result<ElectricityRemainderResultDto, String> {
        crate::telemetry::observe("electricity", "load_electricity_remainder_result", async {
            self.allow_live_operation()?;
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            let cache = JsonFileCache::<ElectricityRemainderCachePayload>::new(
                electricity_remainder_cache_path(&self.cache_path, &user.username),
                ELECTRICITY_REMAINDER_CACHE_SCHEMA_VERSION,
                ELECTRICITY_REMAINDER_CACHE_SERVICE,
            );
            let mut stale_cache = None;
            match cache.read() {
                Ok(Some(envelope))
                    if electricity_remainder_cache_payload_is_valid(
                        &envelope.payload,
                        &user.username,
                    ) && electricity_remainder_cache_is_usable(
                        &envelope.payload.generated_at,
                    ) =>
                {
                    let payload = envelope.payload;
                    if electricity_remainder_cache_is_fresh(&payload.generated_at) {
                        self.last_error = None;
                        return Ok(map_electricity_remainder_cache_payload(
                            &payload, "cache", "ready", None,
                        ));
                    }
                    stale_cache = Some(payload);
                }
                Ok(Some(_)) | Ok(None) => {}
                Err(error) => {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "electricity_remainder_cache_read_failed",
                        reason = "cache_unavailable",
                        error = %error
                    );
                }
            }

            let return_stale = |runtime: &mut Self,
                                stale: &mut Option<ElectricityRemainderCachePayload>,
                                message: &'static str|
             -> Option<ElectricityRemainderResultDto> {
                stale.take().map(|payload| {
                    runtime.last_error = None;
                    map_electricity_remainder_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some(message.to_owned()),
                    )
                })
            };

            // Metadata/expired Identity may select this account's cache,
            // but it cannot authorize the live electricity request. Give
            // the shared Rust recovery gate one chance before deciding
            // that the stale snapshot is the only usable result.
            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(result) = return_stale(
                        self,
                        &mut stale_cache,
                        "实时电费余额暂时不可用，当前显示已验证缓存",
                    ) {
                        return Ok(result);
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(result) = return_stale(
                        self,
                        &mut stale_cache,
                        "实时电费余额暂时不可用，当前显示已验证缓存",
                    ) {
                        return Ok(result);
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
            }

            if let Err(error) = self.ensure_electricity_reader_session(&user).await {
                if let Some(result) = return_stale(
                    self,
                    &mut stale_cache,
                    "电费服务暂时不可用，当前显示已验证缓存",
                ) {
                    return Ok(result);
                }
                return Err(error);
            }

            let result = if let Some(value) = self.electricity_remainder_prefetch.take() {
                Ok((value, None))
            } else {
                let Some(adapter) = self.electricity_adapter.as_ref() else {
                    if let Some(result) = return_stale(
                        self,
                        &mut stale_cache,
                        "电费服务会话未建立，当前显示已验证缓存",
                    ) {
                        return Ok(result);
                    }
                    return self.fail("电费服务会话未建立");
                };
                adapter
                    .read_remainder_with_proof()
                    .await
                    .map(|read| (read.value, Some(read.proof)))
                    .map_err(|error| error)
            };
            // The prefetched value is already the proof-bearing read used
            // to establish the electricity adapter.  Normalize both paths
            // into one value/proof pair before handling expiry.
            let mut value = match result {
                Ok(value) => value,
                Err(error) if error.is_session_expired() => {
                    self.invalidate_electricity_session();
                    if let Err(refresh_error) = self
                        .refresh_nonacademic_service_after_expiry(ServiceId::Info)
                        .await
                    {
                        if let Some(result) = return_stale(
                            self,
                            &mut stale_cache,
                            "电费余额自动续接失败，当前显示已验证缓存",
                        ) {
                            return Ok(result);
                        }
                        return Err(
                            self.record_error(format!("电费余额自动续接失败: {refresh_error}"))
                        );
                    }
                    user = self.ensure_identity_user_for_live_read().await?;
                    if let Err(error) = self.ensure_electricity_session(&user).await {
                        if let Some(result) = return_stale(
                            self,
                            &mut stale_cache,
                            "电费余额自动续接后不可用，当前显示已验证缓存",
                        ) {
                            return Ok(result);
                        }
                        return Err(error);
                    }
                    if let Some(prefetched) = self.electricity_remainder_prefetch.take() {
                        (prefetched, None)
                    } else {
                        let Some(adapter) = self.electricity_adapter.as_ref() else {
                            if let Some(result) = return_stale(
                                self,
                                &mut stale_cache,
                                "电费余额自动续接后会话未建立，当前显示已验证缓存",
                            ) {
                                return Ok(result);
                            }
                            return self.fail("电费余额自动续接后会话未建立");
                        };
                        match adapter.read_remainder_with_proof().await {
                            Ok(read) => (read.value, Some(read.proof)),
                            Err(error) if error.is_session_expired() => {
                                self.invalidate_electricity_session();
                                if let Some(result) = return_stale(
                                    self,
                                    &mut stale_cache,
                                    "电费余额自动续接后仍已过期，当前显示已验证缓存",
                                ) {
                                    return Ok(result);
                                }
                                return self.fail("电费余额自动续接后仍已过期，请重新建立");
                            }
                            Err(error) => {
                                if let Some(result) = return_stale(
                                    self,
                                    &mut stale_cache,
                                    "实时电费余额读取失败，当前显示已验证缓存",
                                ) {
                                    return Ok(result);
                                }
                                return Err(self.record_business_failure(
                                    "electricity",
                                    "electricity_read",
                                    error.diagnostic_code(),
                                ));
                            }
                        }
                    }
                }
                Err(error) => {
                    if let Some(result) = return_stale(
                        self,
                        &mut stale_cache,
                        "实时电费余额读取失败，当前显示已验证缓存",
                    ) {
                        return Ok(result);
                    }
                    return Err(self.record_business_failure(
                        "electricity",
                        "electricity_read",
                        error.diagnostic_code(),
                    ));
                }
            };

            // A prefetched balance already installed its adapter-bound proof.
            // `None` means no replacement proof, not permission to erase it.
            if let Some(proof) = value.1.take() {
                self.electricity_proof = Some(proof);
            }
            if !self.electricity_service_is_proven() {
                return self.fail("电费服务会话证明未确认，请重新建立服务会话");
            }
            let generated_at = Utc::now();
            let payload = ElectricityRemainderCachePayload {
                account_scope: cache_account_scope(&user.username),
                generated_at,
                remainder: value.0.remainder,
                update_time: value.0.update_time.clone(),
            };
            if electricity_remainder_cache_payload_is_valid(&payload, &user.username) {
                if let Err(error) = cache.write(&payload) {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "electricity_remainder_cache_write_failed",
                        reason = "storage_io",
                        error = %error
                    );
                }
            }
            self.last_error = None;
            self.persist_resume_state_after_live_read(&user, "electricity");
            Ok(map_electricity_remainder_cache_payload(
                &payload, "live", "ready", None,
            ))
        })
        .await
    }

    /// Legacy electricity-history shape retained for deterministic gateways.
    pub async fn load_electricity_payment_history(
        &mut self,
    ) -> Result<ElectricityPaymentHistoryDto, String> {
        self.load_electricity_payment_history_result()
            .await
            .map(|result| ElectricityPaymentHistoryDto {
                records: result.records,
                empty: result.empty,
            })
    }

    /// Reads the validated electricity payment history with a bounded,
    /// account-bound cache. A structurally valid empty table is cached as a
    /// real empty history; a missing/replaced table remains an error and can
    /// only fall back to an already validated stale snapshot.
    pub async fn load_electricity_payment_history_result(
        &mut self,
    ) -> Result<ElectricityPaymentHistoryResultDto, String> {
        crate::telemetry::observe(
            "electricity",
            "load_electricity_payment_history_result",
            async {
                self.allow_live_operation()?;
                let mut user = match self.cache_user_for_read()? {
                    Some(user) => user,
                    None => self.ensure_identity_user_for_live_read().await?,
                };
                let cache = JsonFileCache::<ElectricityPaymentHistoryCachePayload>::new(
                    electricity_history_cache_path(&self.cache_path, &user.username),
                    ELECTRICITY_HISTORY_CACHE_SCHEMA_VERSION,
                    ELECTRICITY_HISTORY_CACHE_SERVICE,
                );
                let mut stale_cache = None;
                match cache.read() {
                    Ok(Some(envelope))
                        if electricity_history_cache_payload_is_valid(
                            &envelope.payload,
                            &user.username,
                        ) && electricity_history_cache_is_usable(
                            &envelope.payload.generated_at,
                        ) =>
                    {
                        let payload = envelope.payload;
                        if electricity_history_cache_is_fresh(&payload.generated_at) {
                            self.last_error = None;
                            return Ok(map_electricity_history_cache_payload(
                                &payload, "cache", "ready", None,
                            ));
                        }
                        stale_cache = Some(payload);
                    }
                    Ok(Some(_)) | Ok(None) => {}
                    Err(error) => {
                        tracing::warn!(
                            target: "tsinghua_kit::storage",
                            event = "electricity_history_cache_read_failed",
                            reason = "cache_unavailable",
                            error = %error
                        );
                    }
                }

                if !self.service_session_is_proven(ServiceId::Identity) {
                    let recovered = self.try_restore_identity_for_cache_refresh().await;
                    if !recovered {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_electricity_history_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some("实时电费缴费记录暂时不可用，当前显示已验证缓存".to_owned()),
                            ));
                        }
                    }
                    if !self.service_session_is_proven(ServiceId::Identity) {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_electricity_history_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some("实时电费缴费记录暂时不可用，当前显示已验证缓存".to_owned()),
                            ));
                        }
                    }
                    user = self.ensure_identity_user_for_live_read().await?;
                }

                if let Err(error) = self.ensure_electricity_reader_session(&user).await {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_electricity_history_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("实时电费缴费记录暂时不可用，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(error);
                }
                // A caller choosing history instead of the remainder has moved past
                // the establishment read. Do not serve that older prefetched value
                // from a later remainder action.
                self.electricity_remainder_prefetch = None;
                let mut result = {
                    let Some(adapter) = self.electricity_adapter.as_ref() else {
                        return self.fail("电费服务会话未建立");
                    };
                    adapter.read_payment_history_with_proof().await
                };
                if matches!(&result, Err(error) if error.is_session_expired()) {
                    self.invalidate_electricity_session();
                    if let Err(error) = self
                        .refresh_nonacademic_service_after_expiry(ServiceId::Info)
                        .await
                    {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_electricity_history_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some("电费缴费记录自动续接失败，当前显示已验证缓存".to_owned()),
                            ));
                        }
                        return Err(self.record_error(format!("电费缴费记录自动续接失败: {error}")));
                    }
                    user = self.ensure_identity_user_for_live_read().await?;
                    if let Err(error) = self.ensure_electricity_session(&user).await {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_electricity_history_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some("电费缴费记录自动续接后不可用，当前显示已验证缓存".to_owned()),
                            ));
                        }
                        return Err(error);
                    }
                    self.electricity_remainder_prefetch = None;
                    result = {
                        let Some(adapter) = self.electricity_adapter.as_ref() else {
                            return self.fail("电费缴费记录自动续接后会话未建立");
                        };
                        adapter.read_payment_history_with_proof().await
                    };
                    if matches!(&result, Err(error) if error.is_session_expired()) {
                        self.invalidate_electricity_session();
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_electricity_history_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some(
                                    "电费缴费记录自动续接后仍已过期，当前显示已验证缓存".to_owned(),
                                ),
                            ));
                        }
                        return self.fail("电费缴费记录自动续接后仍已过期，请重新建立");
                    }
                }
                match result {
                    Ok(read) => {
                        self.electricity_proof = Some(read.proof);
                        let generated_at = Utc::now();
                        let records = map_electricity_history_records(read.value)
                            .into_iter()
                            .map(|record| ElectricityPaymentHistoryCacheRecord {
                                source_columns: record.source_columns,
                                sequence: record.sequence,
                                occurred_at: record.occurred_at,
                                amount: record.amount,
                                status: record.status,
                            })
                            .collect::<Vec<_>>();
                        let payload = ElectricityPaymentHistoryCachePayload {
                            account_scope: cache_account_scope(&user.username),
                            generated_at,
                            records,
                        };
                        if electricity_history_cache_payload_is_valid(&payload, &user.username) {
                            if let Err(error) = cache.write(&payload) {
                                tracing::warn!(
                                    target: "tsinghua_kit::storage",
                                    event = "electricity_history_cache_write_failed",
                                    reason = "storage_io",
                                    error = %error
                                );
                            }
                        }
                        self.last_error = None;
                        self.persist_resume_state_after_live_read(&user, "electricity");
                        Ok(map_electricity_history_cache_payload(
                            &payload, "live", "ready", None,
                        ))
                    }
                    Err(error) => {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_electricity_history_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some("实时电费缴费记录暂时不可用，当前显示已验证缓存".to_owned()),
                            ));
                        }
                        Err(self.record_business_failure(
                            "electricity",
                            "electricity_read",
                            error.diagnostic_code(),
                        ))
                    }
                }
            },
        )
        .await
    }

    /// Logs into the current macOS/desktop IPv4 TUNet portal while keeping the
    /// plaintext network password inside Rust.  The portal uses its own
    /// challenge and SRun digest; it does not reuse the identity cookie as a
    /// TUNet credential.
    pub async fn login_tunet(
        &mut self,
        username: String,
        password: String,
    ) -> Result<CampusRuntimeStatusDto, String> {
        crate::telemetry::observe("tunet", "login_tunet", async {
            // Wrap the one-shot secret before any validation or state gate can
            // return early, so every exit path zeroizes the input buffer.
            let password = zeroize::Zeroizing::new(password);
            self.allow_live_operation()?;
            let username = username.trim().to_owned();
            if username.is_empty() {
                return self.fail("请输入校园网账号");
            }
            if password.is_empty() {
                return self.fail("请输入校园网密码");
            }

            let ip = local_ipv4_address().map_err(|error| self.record_error(error))?;
            let config = TunetClientConfig::auth4()
                .map_err(|error| self.record_error(format!("tunet client: {error}")))?;
            let client = TunetClient::with_transport(config, self.identity.transport().clone())
                .map_err(|error| self.record_error(format!("tunet client: {error}")))?;
            self.login_tunet_using(username, password, ip, client).await
        })
        .await
    }

    // Keep endpoint selection in the public method and the identical login
    // orchestration independently testable with a loopback-only client.
    async fn login_tunet_using(
        &mut self,
        username: String,
        password: zeroize::Zeroizing<String>,
        ip: String,
        client: TunetClient,
    ) -> Result<CampusRuntimeStatusDto, String> {
        // A new attempt invalidates any earlier disconnect authority. If the
        // portal changes accounts before returning an ambiguous result, the
        // old target must not be reused.
        self.tunet_connection_target = None;
        let params = [("ip", ip.as_str())];
        let response = match client
            .login_with_password_verified(&username, &password, &params)
            .await
        {
            Ok(response) => response,
            Err(error) => {
                return Err(self.record_error(format!("tunet login: {error}")));
            }
        };

        if response.signal != TunetStatusSignal::Positive {
            return self.fail(match response.signal {
                TunetStatusSignal::Negative => "校园网账号或密码错误，请检查后重试",
                TunetStatusSignal::Unknown => "校园网登录状态未确认，请稍后重试",
                TunetStatusSignal::Positive => unreachable!("positive signal handled above"),
            });
        }

        // The verified client already returns the IP/account-bound online
        // status, not the login acknowledgement. A second read can fail after
        // successful login and is neither a stronger nor a required proof.
        let status = response;
        if status.account_binding_conflicts(&username) {
            return self.fail("校园网返回账号与本次登录账号不一致");
        }
        if !status.is_online_proven() {
            return self.fail("校园网登录状态未确认，请稍后重试");
        }

        self.tunet_connection_target = Some(TunetConnectionTarget {
            client,
            username,
            local_ipv4: ip,
        });
        self.last_error = None;
        Ok(self.status())
    }

    /// Reads the portal state for this machine's physical IPv4. This is a
    /// read-only observation and never establishes an SRun login session:
    /// Tsinghua-Secure may already have authenticated at the Wi-Fi layer.
    pub async fn load_tunet_status(&mut self) -> Result<TunetNetworkStatusDto, String> {
        crate::telemetry::observe("tunet", "load_tunet_status", async {
            self.allow_live_operation()?;
            let ip = local_ipv4_address().map_err(|error| self.record_error(error))?;
            let target = self.tunet_connection_target.as_ref();
            let target_username = target
                .filter(|target| target.local_ipv4 == ip)
                .map(|target| target.username.clone());
            let target_client = target
                .filter(|target| target.local_ipv4 == ip)
                .map(|target| target.client.clone());
            if target.is_some() && target_client.is_none() {
                // An address change ends the authority to disconnect the old
                // network target. It does not imply that the new interface is
                // offline, so continue with a read-only observation for its IP.
                self.tunet_connection_target = None;
            }
            let client = if let Some(client) = target_client {
                client
            } else {
                let config = TunetClientConfig::auth4()
                    .map_err(|error| self.record_error(format!("tunet status config: {error}")))?;
                let client = TunetClient::with_transport(config, self.identity.transport().clone())
                    .map_err(|error| self.record_error(format!("tunet status client: {error}")))?;
                client
            };
            self.load_tunet_status_using(client, ip, target_username)
                .await
        })
        .await
    }

    async fn load_tunet_status_using(
        &mut self,
        client: TunetClient,
        ip: String,
        target_username: Option<String>,
    ) -> Result<TunetNetworkStatusDto, String> {
        let record = match client.status(&[("ip", ip.as_str())]).await {
            Ok(record) => record,
            Err(error) => {
                if target_username.is_some() && error.is_authentication_failure() {
                    self.tunet_connection_target = None;
                }
                return Err(self.record_error(format!("tunet status: {error}")));
            }
        };
        let Some(target_username) = target_username else {
            // A portal reply is only an observation for this IP. In
            // particular, it must not grant an account-bound logout.
            let dto = if record.is_online_proven_for_ip(&ip) {
                TunetNetworkStatusDto {
                    state: "online".into(),
                    online: true,
                    signal: "positive".into(),
                }
            } else if record.is_offline_proven_for_ip(&ip) {
                TunetNetworkStatusDto {
                    state: "offline".into(),
                    online: false,
                    signal: "negative".into(),
                }
            } else {
                TunetNetworkStatusDto {
                    state: "unknown".into(),
                    online: false,
                    signal: "unknown".into(),
                }
            };
            self.last_error = None;
            return Ok(dto);
        };
        if record.account_binding_conflicts(&target_username) {
            self.tunet_connection_target = None;
            return self.fail("校园网返回账号与已登录账号不一致，请重新登录");
        }
        let dto = tunet_status_dto(&record);
        if !dto.online {
            if record.is_offline_proven_for_ip(&ip) {
                self.tunet_connection_target = None;
                return self.fail("校园网已离线，请重新登录");
            }
            // An incomplete/contradictory status is neither online proof nor
            // permission to discard an otherwise established network login.
            return self.fail("校园网在线状态未确认，请稍后刷新");
        }
        self.last_error = None;
        Ok(dto)
    }

    /// Explicitly disconnects the portal target established and verified by
    /// this process. The target is consumed before awaiting the one-shot
    /// operation, so an interrupted/unclear result cannot silently replay it.
    pub async fn disconnect_tunet(&mut self) -> Result<TunetNetworkStatusDto, String> {
        crate::telemetry::observe("tunet", "disconnect_tunet", async {
            self.allow_live_operation()?;
            if self.tunet_connection_target.is_none() {
                return self.fail("当前进程没有可验证的校园网断开目标");
            }
            let current_ip = local_ipv4_address().map_err(|error| self.record_error(error))?;
            self.disconnect_tunet_using(current_ip).await
        })
        .await
    }

    async fn disconnect_tunet_using(
        &mut self,
        current_ip: String,
    ) -> Result<TunetNetworkStatusDto, String> {
        let Some(target) = self.tunet_connection_target.take() else {
            return self.fail("当前进程没有可验证的校园网断开目标");
        };
        if current_ip != target.local_ipv4 {
            return self.fail("本机网络地址已变化，请先重新读取当前网络状态");
        }
        let TunetConnectionTarget {
            client,
            username,
            local_ipv4: ip,
        } = target;
        let record = match client
            .disconnect_verified(&username, &[("ip", ip.as_str())])
            .await
        {
            Ok(record) => record,
            Err(error) => return Err(self.record_error(format!("tunet disconnect: {error}"))),
        };
        let dto = tunet_status_dto(&record);
        self.last_error = None;
        Ok(dto)
    }

    /// Reads the card account through the source-aware cache boundary. A
    /// fresh account cache is returned before any card handoff or account
    /// request. A bounded stale value is used only after a live identity/card
    /// read is unavailable, and its provenance remains explicit on the Rust
    /// bridge.
    pub async fn load_campus_card_account_result(
        &mut self,
    ) -> Result<CampusCardAccountResultDto, String> {
        crate::telemetry::observe("campus_card", "load_campus_card_account_result", async {
            self.allow_live_operation()?;
            let mut user = match self.cache_user_for_read()? {
                Some(user) => user,
                None => self.ensure_identity_user_for_live_read().await?,
            };
            let cache = JsonFileCache::<CampusCardAccountCachePayload>::new(
                campus_card_account_cache_path(&self.cache_path, &user.username),
                CAMPUS_CARD_ACCOUNT_CACHE_SCHEMA_VERSION,
                CAMPUS_CARD_ACCOUNT_CACHE_SERVICE,
            );
            let mut stale_cache = None;
            match cache.read() {
                Ok(Some(envelope))
                    if campus_card_account_cache_payload_is_valid(
                        &envelope.payload,
                        &user.username,
                    ) && campus_card_account_cache_is_usable(&envelope.payload.generated_at) =>
                {
                    let payload = envelope.payload;
                    if campus_card_account_cache_is_fresh(&payload.generated_at) {
                        self.last_error = None;
                        return Ok(map_campus_card_account_cache_payload(
                            &payload, "cache", "ready", None,
                        ));
                    }
                    stale_cache = Some(payload);
                }
                Ok(Some(_)) | Ok(None) => {}
                Err(error) => {
                    tracing::warn!(
                        target: "tsinghua_kit::storage",
                        event = "campus_card_account_cache_read_failed",
                        reason = "cache_unavailable",
                        error = %error
                    );
                }
            }

            // Cache metadata can identify the account to display, but it can
            // never authorize a network request. Cross the live Identity
            // boundary only after the fresh-cache fast path has missed.
            if !self.service_session_is_proven(ServiceId::Identity) {
                let recovered = self.try_restore_identity_for_cache_refresh().await;
                if !recovered {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_campus_card_account_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("统一认证会话未建立，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                if !self.service_session_is_proven(ServiceId::Identity) {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_campus_card_account_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("统一认证会话未建立，当前显示已验证缓存".to_owned()),
                        ));
                    }
                }
                user = self.ensure_identity_user_for_live_read().await?;
            }

            if !self.service_session_is_proven(ServiceId::CampusCard) {
                let card_context_exists = self.card_session.is_some()
                    || self
                        .coordinator
                        .registry()
                        .snapshot_for(ServiceId::CampusCard)
                        .state
                        != ServiceSessionState::Anonymous
                    || self
                        .automatic_refresh_attempted
                        .contains(&ServiceId::CampusCard)
                    || self
                        .automatic_refresh_results
                        .contains_key(&ServiceId::CampusCard);
                if card_context_exists {
                    if let Err(error) = self.ensure_campus_card_reader_session().await {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_campus_card_account_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some("校园卡服务自动续接失败，当前显示已验证缓存".to_owned()),
                            ));
                        }
                        return Err(error);
                    }
                } else if let Some(payload) = stale_cache.take() {
                    // Do not turn an old account cache into an implicit first
                    // card SSO. The user may explicitly establish the card
                    // service; meanwhile the verified old value is useful.
                    self.last_error = None;
                    return Ok(map_campus_card_account_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some("校园卡服务会话未建立，当前显示已验证缓存".to_owned()),
                    ));
                } else {
                    // A first live account read is allowed to establish the
                    // card-specific SSO through the normal Rust boundary.
                    self.ensure_card_session(&user).await?;
                }
            }

            let Some(client) = self.card_client.clone() else {
                if let Some(payload) = stale_cache.take() {
                    self.last_error = None;
                    return Ok(map_campus_card_account_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some("校园卡服务会话未建立，当前显示已验证缓存".to_owned()),
                    ));
                }
                return self.fail("校园卡服务会话未建立");
            };
            let expected = CampusCardAccountBinding::new(&user.username)
                .map_err(|error| self.record_error(format!("校园卡账号绑定无效: {error}")))?;
            let Some(session) = self.card_session.as_ref() else {
                if let Some(payload) = stale_cache.take() {
                    self.last_error = None;
                    return Ok(map_campus_card_account_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some("校园卡服务会话未建立，当前显示已验证缓存".to_owned()),
                    ));
                }
                return self.fail("校园卡服务会话未建立");
            };
            let mut result = client.read_account_for(session, Some(&expected)).await;
            if matches!(
                &result,
                Err(crate::campus_card_adapter::CampusCardAdapterError::SessionExpired)
            ) {
                self.invalidate_service_session(ServiceId::CampusCard);
                if let Err(error) = self
                    .refresh_nonacademic_service_after_expiry(ServiceId::CampusCard)
                    .await
                {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_campus_card_account_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("校园卡账户自动续接失败，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return Err(self.record_error(format!("校园卡账户自动续接失败: {error}")));
                }
                let Some(session) = self.card_session.as_ref() else {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_campus_card_account_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("校园卡账户自动续接后会话未建立，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("校园卡账户自动续接后会话未建立");
                };
                result = client.read_account_for(session, Some(&expected)).await;
                if matches!(
                    &result,
                    Err(crate::campus_card_adapter::CampusCardAdapterError::SessionExpired)
                ) {
                    self.invalidate_service_session(ServiceId::CampusCard);
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_campus_card_account_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("校园卡账户自动续接后仍已过期，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("校园卡账户自动续接后仍已过期，请重新建立");
                }
            }

            match result {
                Ok(account) => {
                    let payload = CampusCardAccountCachePayload {
                        account_scope: cache_account_scope(&user.username),
                        generated_at: Utc::now(),
                        account,
                    };
                    if !campus_card_account_cache_payload_is_valid(&payload, &user.username) {
                        return self.fail("校园卡账户响应未通过安全校验");
                    }
                    if let Err(error) = cache.write(&payload) {
                        tracing::warn!(
                            target: "tsinghua_kit::storage",
                            event = "campus_card_account_cache_write_failed",
                            reason = "storage_io",
                            error = %error
                        );
                    }
                    self.last_error = None;
                    self.persist_resume_state_after_live_read(&user, "campus_card");
                    Ok(map_campus_card_account_cache_payload(
                        &payload, "live", "ready", None,
                    ))
                }
                Err(error) => {
                    let account_mismatch = matches!(
                        &error,
                        crate::campus_card_adapter::CampusCardAdapterError::AccountMismatch
                    );
                    if account_mismatch {
                        // A conflicting account is a binding failure, not a
                        // transient outage. Do not render an old balance when
                        // the current service proof belongs to another user.
                        self.invalidate_service_session(ServiceId::CampusCard);
                    }
                    error.trace_read_failure("load_campus_card_account");
                    let message = format!(
                        "校园卡读取未通过（{}），详见脱敏日志",
                        error.diagnostic_code()
                    );
                    if !account_mismatch {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_campus_card_account_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some("实时校园卡账户暂时不可用，当前显示已验证缓存".to_owned()),
                            ));
                        }
                    }
                    self.last_error = Some(message.clone());
                    Err(message)
                }
            }
        })
        .await
    }

    /// Legacy campus-card account shape retained for deterministic gateways.
    /// Production callers should use the source-aware result so a stale
    /// balance cannot be mistaken for a live one.
    pub async fn load_campus_card_account(
        &mut self,
    ) -> Result<crate::campus_card_read::CampusCardAccount, String> {
        self.load_campus_card_account_result()
            .await
            .map(|result| result.account)
    }

    /// Legacy campus-card transaction shape retained for deterministic
    /// gateways. The production path carries the query provenance envelope.
    pub async fn load_campus_card_transactions(
        &mut self,
        start_date: String,
        end_date: String,
    ) -> Result<crate::campus_card_read::CampusCardTransactionReport, String> {
        self.load_campus_card_transactions_result(start_date, end_date, "any".to_owned())
            .await
            .map(
                |result| crate::campus_card_read::CampusCardTransactionReport {
                    transactions: result.transactions,
                },
            )
    }

    /// Reads a complete, bounded campus-card transaction window. The bridge
    /// has no page selector or partial-result flag, so a full page cannot be
    /// returned as though it were the complete date range. Read serially and
    /// fail explicitly when completion cannot be established within the cap.
    /// The cache key includes the account, normalized date range, and explicit
    /// transaction type; balance and card status remain live-only.
    pub async fn load_campus_card_transactions_result(
        &mut self,
        start_date: String,
        end_date: String,
        transaction_type: String,
    ) -> Result<CampusCardTransactionsResultDto, String> {
        crate::telemetry::observe(
            "campus_card",
            "load_campus_card_transactions_result",
            async {
                self.allow_live_operation()?;
                let mut user = match self.cache_user_for_read()? {
                    Some(user) => user,
                    None => self.ensure_identity_user_for_live_read().await?,
                };
                let transaction_type = parse_campus_card_transaction_type(&transaction_type)?;
                const PAGE_SIZE: u16 = 100;
                const MAX_PAGES: u32 = 10;
                let initial_query = CampusCardTransactionQuery::new(
                    &start_date,
                    &end_date,
                    transaction_type,
                    PAGE_SIZE,
                    0,
                )
                .map_err(|error| self.record_error(format!("校园卡交易查询无效: {error}")))?;
                let normalized_start = initial_query.start_date().as_str().to_owned();
                let normalized_end = initial_query.end_date().as_str().to_owned();
                let normalized_type = campus_card_transaction_type_name(transaction_type);
                let cache = JsonFileCache::<CampusCardTransactionCachePayload>::new(
                    campus_card_transaction_cache_path(
                        &self.cache_path,
                        &user.username,
                        &normalized_start,
                        &normalized_end,
                        normalized_type,
                    ),
                    CAMPUS_CARD_TRANSACTION_CACHE_SCHEMA_VERSION,
                    CAMPUS_CARD_TRANSACTION_CACHE_SERVICE,
                );
                let mut stale_cache = None;
                match cache.read() {
                    Ok(Some(envelope))
                        if campus_card_transaction_cache_payload_is_valid(
                            &envelope.payload,
                            &user.username,
                            &normalized_start,
                            &normalized_end,
                            transaction_type,
                        ) && campus_card_transaction_cache_is_usable(
                            &envelope.payload.generated_at,
                        ) =>
                    {
                        let payload = envelope.payload;
                        if campus_card_transaction_cache_is_fresh(&payload.generated_at) {
                            self.last_error = None;
                            return Ok(map_campus_card_transactions_cache_payload(
                                &payload, "cache", "ready", None,
                            ));
                        }
                        stale_cache = Some(payload);
                    }
                    Ok(Some(_)) | Ok(None) => {}
                    Err(error) => {
                        tracing::warn!(
                            target: "tsinghua_kit::storage",
                            event = "campus_card_transaction_cache_read_failed",
                            reason = "cache_unavailable",
                            error = %error
                        );
                    }
                }

                if !self.service_session_is_proven(ServiceId::Identity) {
                    let recovered = self.try_restore_identity_for_cache_refresh().await;
                    if !recovered {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_campus_card_transactions_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some("校园卡服务会话未建立，当前显示已验证缓存".to_owned()),
                            ));
                        }
                    }
                    if !self.service_session_is_proven(ServiceId::Identity) {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_campus_card_transactions_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some("校园卡服务会话未建立，当前显示已验证缓存".to_owned()),
                            ));
                        }
                    }
                    user = self.ensure_identity_user_for_live_read().await?;
                }

                if !self.service_session_is_proven(ServiceId::CampusCard) {
                    // A previous card proof that has expired deserves one
                    // bounded reader-owned refresh before falling back to the
                    // stale transaction window. A first-ever card read is
                    // different: the card target has its own SSO boundary,
                    // so do not initiate that one-time handoff merely because
                    // an old cache exists. The explicit service action can
                    // establish it, after which later expiry is recoverable.
                    let card_context_exists = self.card_session.is_some()
                        || self
                            .coordinator
                            .registry()
                            .snapshot_for(ServiceId::CampusCard)
                            .state
                            != ServiceSessionState::Anonymous
                        || self
                            .automatic_refresh_attempted
                            .contains(&ServiceId::CampusCard)
                        || self
                            .automatic_refresh_results
                            .contains_key(&ServiceId::CampusCard);
                    if card_context_exists {
                        if let Err(error) = self.ensure_campus_card_reader_session().await {
                            if let Some(payload) = stale_cache.take() {
                                self.last_error = None;
                                return Ok(map_campus_card_transactions_cache_payload(
                                    &payload,
                                    "cache",
                                    "stale",
                                    Some("校园卡交易自动续接失败，当前显示已验证缓存".to_owned()),
                                ));
                            }
                            return Err(error);
                        }
                    } else if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_campus_card_transactions_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("校园卡服务会话未建立，当前显示已验证缓存".to_owned()),
                        ));
                    } else {
                        return self.fail("校园卡服务会话未建立");
                    }
                }
                let Some(client) = self.card_client.clone() else {
                    if let Some(payload) = stale_cache.take() {
                        self.last_error = None;
                        return Ok(map_campus_card_transactions_cache_payload(
                            &payload,
                            "cache",
                            "stale",
                            Some("校园卡服务会话未建立，当前显示已验证缓存".to_owned()),
                        ));
                    }
                    return self.fail("校园卡服务会话未建立");
                };
                let mut transactions = Vec::new();
                let mut seen = HashSet::new();
                let mut automatic_refresh_used = false;
                for page_number in 0..MAX_PAGES {
                    let query = CampusCardTransactionQuery::new(
                        initial_query.start_date().as_str(),
                        initial_query.end_date().as_str(),
                        initial_query.transaction_type(),
                        PAGE_SIZE,
                        page_number,
                    )
                    .map_err(|_| self.record_error("校园卡分页参数无效"))?;
                    let Some(session) = self.card_session.as_ref() else {
                        if let Some(payload) = stale_cache.take() {
                            self.last_error = None;
                            return Ok(map_campus_card_transactions_cache_payload(
                                &payload,
                                "cache",
                                "stale",
                                Some("校园卡服务会话未建立，当前显示已验证缓存".to_owned()),
                            ));
                        }
                        return self.fail("校园卡服务会话未建立");
                    };
                    let report = match client.read_transactions(session, &query).await {
                        Ok(report) => report,
                        Err(crate::campus_card_adapter::CampusCardAdapterError::SessionExpired)
                            if !automatic_refresh_used =>
                        {
                            self.invalidate_service_session(ServiceId::CampusCard);
                            if let Err(error) = self
                                .refresh_nonacademic_service_after_expiry(ServiceId::CampusCard)
                                .await
                            {
                                if let Some(payload) = stale_cache.take() {
                                    self.last_error = None;
                                    return Ok(map_campus_card_transactions_cache_payload(
                                        &payload,
                                        "cache",
                                        "stale",
                                        Some(
                                            "校园卡交易自动续接失败，当前显示已验证缓存".to_owned(),
                                        ),
                                    ));
                                }
                                return Err(
                                    self.record_error(format!("校园卡交易自动续接失败: {error}"))
                                );
                            }
                            automatic_refresh_used = true;
                            continue;
                        }
                        Err(crate::campus_card_adapter::CampusCardAdapterError::SessionExpired) => {
                            self.invalidate_service_session(ServiceId::CampusCard);
                            if let Some(payload) = stale_cache.take() {
                                self.last_error = None;
                                return Ok(map_campus_card_transactions_cache_payload(
                                    &payload,
                                    "cache",
                                    "stale",
                                    Some(
                                        "校园卡交易自动续接后仍已过期，当前显示已验证缓存"
                                            .to_owned(),
                                    ),
                                ));
                            }
                            return self.fail("校园卡交易自动续接后仍已过期，请重新建立");
                        }
                        Err(error) => {
                            if matches!(
                                error,
                                crate::campus_card_adapter::CampusCardAdapterError::AccountMismatch
                            ) {
                                self.invalidate_service_session(ServiceId::CampusCard);
                            }
                            // A later-page failure is an error, never an apparently
                            // complete first-page result. Do not replay the POST.
                            error.trace_read_failure("load_campus_card_transactions");
                            let message = format!(
                                "校园卡读取未通过（{}），详见脱敏日志",
                                error.diagnostic_code()
                            );
                            if let Some(payload) = stale_cache.take() {
                                self.last_error = None;
                                return Ok(map_campus_card_transactions_cache_payload(
                                    &payload,
                                    "cache",
                                    "stale",
                                    Some("实时校园卡流水暂时不可用，当前显示已验证缓存".to_owned()),
                                ));
                            }
                            self.last_error = Some(message.clone());
                            return Err(message);
                        }
                    };
                    if report.len() > usize::from(PAGE_SIZE) {
                        return self.fail("校园卡交易分页响应超出请求范围");
                    }
                    let complete = !report.may_have_next_page(&query);
                    for transaction in report.transactions {
                        if !seen.insert(transaction.transaction_id.clone()) {
                            return self.fail("校园卡交易分页出现重复记录，请缩小日期范围后重试");
                        }
                        transactions.push(transaction);
                    }
                    if complete {
                        let generated_at = Utc::now();
                        let payload = CampusCardTransactionCachePayload {
                            account_scope: cache_account_scope(&user.username),
                            start_date: normalized_start.clone(),
                            end_date: normalized_end.clone(),
                            transaction_type: normalized_type.to_owned(),
                            generated_at,
                            transactions: transactions.clone(),
                        };
                        if campus_card_transaction_cache_payload_is_valid(
                            &payload,
                            &user.username,
                            &normalized_start,
                            &normalized_end,
                            transaction_type,
                        ) {
                            if let Err(error) = cache.write(&payload) {
                                tracing::warn!(
                                    target: "tsinghua_kit::storage",
                                    event = "campus_card_transaction_cache_write_failed",
                                    reason = "storage_io",
                                    error = %error
                                );
                            }
                        }
                        self.last_error = None;
                        self.persist_resume_state_after_live_read(&user, "campus_card");
                        return Ok(map_campus_card_transactions_cache_payload(
                            &payload, "live", "ready", None,
                        ));
                    }
                }
                if let Some(payload) = stale_cache.take() {
                    self.last_error = None;
                    return Ok(map_campus_card_transactions_cache_payload(
                        &payload,
                        "cache",
                        "stale",
                        Some("校园卡交易结果未完整确认，当前显示已验证缓存".to_owned()),
                    ));
                }
                self.fail("校园卡交易超过单次分页上限，请缩小日期范围；未返回不完整结果")
            },
        )
        .await
    }

    /// Non-secret, local-only state for the independent login form. A stale
    /// image must never authorize another validation or final login POST.
    pub fn usereg_login_phase(&mut self) -> String {
        let valid = self.usereg_pending.as_ref().is_some_and(|pending| {
            pending.created_at.elapsed() < Duration::from_secs(5 * 60)
                && self.service_session_is_proven(ServiceId::Identity)
                && self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Identity)
                    .user
                    .as_ref()
                    == Some(&pending.identity_owner)
                && self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Usereg)
                    .state
                    == ServiceSessionState::Authenticating
                && Arc::ptr_eq(
                    pending.transport.cookie_jar(),
                    self.identity.transport().cookie_jar(),
                )
        });
        if !valid {
            self.cancel_usereg_login();
            return "restart_required".into();
        }
        if self
            .usereg_pending
            .as_ref()
            .is_some_and(|pending| pending.captcha_ready)
        {
            "captcha_ready".into()
        } else {
            "refresh_required".into()
        }
    }

    /// Cancels only the unfinished independent login. Does not log out a
    /// proven USEREG session, the primary identity, or any other service.
    pub fn cancel_usereg_login(&mut self) {
        if self.usereg_pending.take().is_some() {
            self.invalidate_service_session(ServiceId::Usereg);
        }
    }

    /// Starts the USEREG login dialog.  The page CSRF/public key, credentials,
    /// and shared-cookie transport remain in Rust; Flutter receives only the
    /// validated captcha image needed for human input.
    pub async fn start_usereg_login(
        &mut self,
        username: String,
        password: String,
    ) -> Result<UseregCaptchaDto, String> {
        self.start_usereg_login_with_options(username, password, false)
            .await
    }

    /// Starts one USEREG captcha flow with an explicit, per-login credential
    /// persistence choice. The selected Auth domain remains SelfService.
    pub async fn start_usereg_login_with_options(
        &mut self,
        username: String,
        password: String,
        remember_credentials: bool,
    ) -> Result<UseregCaptchaDto, String> {
        crate::telemetry::observe("usereg", "start_usereg_login", async {
            self.allow_live_operation()?;
            if !self.service_session_is_proven(ServiceId::Identity) {
                return self.fail("请先完成统一认证");
            }
            if self.current_service_second_factor().is_some() {
                return self.fail("请先完成当前服务的二次认证");
            }
            let identity_owner = self
                .coordinator
                .registry()
                .snapshot_for(ServiceId::Identity)
                .user
                .ok_or_else(|| self.record_error("请先完成统一认证"))?;
            let username = username.trim().to_owned();
            if username.is_empty() {
                return self.fail("请输入网络自助账号");
            }
            if password.is_empty() {
                return self.fail("请输入网络自助密码");
            }
            if !remember_credentials
                && self
                    .clear_saved_self_service_credentials(&username)
                    .is_err()
            {
                return self.fail("网络自助凭据存储不可用，无法确认已取消保存");
            }

            // USEREG is WebVPN-mapped even on campus. Identity alone does
            // not prove the portal cookie context needed by its captcha.
            // Reuse the shared bootstrap and its failure/no-replay guard.
            self.ensure_portal_bootstrap(&identity_owner).await?;

            let credentials = UseregLoginCredentials::new(username, password)
                .map_err(|error| self.record_error(format!("USEREG credentials: {error}")))?;
            let base = Url::parse(WEBVPN_BASE_URL)
                .and_then(|url| url.join(USEREG_TARGET_PREFIX))
                .map_err(|error| self.record_error(format!("USEREG base URL: {error}")))?;
            let config = UseregClientConfig::new(base.to_string(), UseregProfile::default())
                .map_err(|error| self.record_error(format!("USEREG config: {error}")))?;
            let adapter = UseregAdapter::new(
                UseregClient::new(config)
                    .map_err(|error| self.record_error(format!("USEREG client: {error}")))?,
            );

            self.self_service_account_username = None;
            if self.usereg_pending.is_some()
                || self.usereg_adapter.is_some()
                || self
                    .coordinator
                    .registry()
                    .snapshot_for(ServiceId::Usereg)
                    .state
                    != ServiceSessionState::Anonymous
            {
                self.invalidate_service_session(ServiceId::Usereg);
            }
            if let Err(error) = self.coordinator.begin_authentication(ServiceId::Usereg) {
                self.invalidate_service_session(ServiceId::Usereg);
                return Err(self.record_error(format!("USEREG session: {error}")));
            }

            let (page, image) = match adapter
                .prepare_captcha_login(
                    self.identity.transport(),
                    &Uuid::new_v4().simple().to_string(),
                )
                .await
            {
                Ok(context) => context,
                Err(error) => {
                    self.invalidate_service_session(ServiceId::Usereg);
                    return Err(self.record_usereg_failure("start_usereg_login", &error));
                }
            };

            self.usereg_pending = Some(UseregPendingLogin {
                adapter,
                page,
                credentials,
                identity_owner,
                transport: self.identity.transport().clone(),
                created_at: std::time::Instant::now(),
                captcha_ready: true,
                remember_credentials,
            });
            self.last_error = None;
            Ok(map_usereg_captcha(image))
        })
        .await
    }

    /// Refreshes the image while retaining the same USEREG page/session and
    /// credentials.  A refresh does not require another identity login.
    pub async fn refresh_usereg_captcha(&mut self) -> Result<UseregCaptchaDto, String> {
        crate::telemetry::observe("usereg", "refresh_usereg_captcha", async {
            self.allow_live_operation()?;
            if self.usereg_login_phase() == "restart_required" {
                return self.fail("网络自助登录页面已过期，请重新输入账号密码获取验证码");
            }
            let pending = self
                .usereg_pending
                .as_mut()
                .expect("current pending login checked");
            pending.captcha_ready = false;
            let adapter = pending.adapter.clone();
            let image = adapter
                .refresh_captcha_image(
                    self.identity.transport(),
                    &Uuid::new_v4().simple().to_string(),
                )
                .await
                .map_err(|error| {
                    self.invalidate_service_session(ServiceId::Usereg);
                    self.record_usereg_failure("refresh_usereg_captcha", &error)
                })?;
            if let Some(pending) = self.usereg_pending.as_mut() {
                pending.captcha_ready = true;
            }
            self.last_error = None;
            Ok(map_usereg_captcha(image))
        })
        .await
    }

    /// Validates the entered captcha and submits the final USEREG form only
    /// after the portal's AJAX validation accepts it.
    pub async fn complete_usereg_login(
        &mut self,
        verify_code: String,
        sms_code: Option<String>,
    ) -> Result<CampusRuntimeStatusDto, String> {
        self.complete_usereg_login_with_result(verify_code, sms_code)
            .await
            .map(|(status, _)| status)
    }

    /// Completes the explicit captcha flow and reports whether the selected
    /// SelfService credential was durably stored after authentication.
    pub async fn complete_usereg_login_with_result(
        &mut self,
        verify_code: String,
        sms_code: Option<String>,
    ) -> Result<(CampusRuntimeStatusDto, bool), String> {
        crate::telemetry::observe("usereg", "complete_usereg_login", async {
            self.allow_live_operation()?;
            if !self.service_session_is_proven(ServiceId::Identity) {
                self.invalidate_service_session(ServiceId::Usereg);
                return self.fail("请先完成统一认证");
            }
            let verify_code = verify_code.trim().to_owned();
            if verify_code.is_empty() {
                return self.fail("请输入网络自助验证码");
            }
            match self.usereg_login_phase().as_str() {
                "captcha_ready" => {}
                "refresh_required" => {
                    return self.fail("网络自助验证码已失效，请手动刷新图片后重试");
                }
                _ => return self.fail("网络自助登录页面已过期，请重新输入账号密码获取验证码"),
            }
            // Cancellation while validation is in flight also consumes the
            // displayed image; only an explicit refresh can acquire a new one.
            self.usereg_pending
                .as_mut()
                .expect("pending checked")
                .captcha_ready = false;
            let Some(pending) = self.usereg_pending.as_ref() else {
                return self.fail("请先开始网络自助登录");
            };
            let remember_credentials = pending.remember_credentials;
            let adapter = pending.adapter.clone();
            let page = pending.page.clone();
            let credentials = pending.credentials.clone();
            let validation = adapter
                .validate_user(self.identity.transport(), &page, &credentials, &verify_code)
                .await
                .map_err(|error| {
                    self.invalidate_service_session(ServiceId::Usereg);
                    self.record_usereg_failure("usereg_validate_user", &error)
                })?;

            match validation.outcome {
                UseregValidationOutcome::Accepted => {}
                UseregValidationOutcome::CaptchaRejected => {
                    return self.fail("网络自助验证码错误，请刷新后重试");
                }
                UseregValidationOutcome::CredentialsRejected => {
                    self.cancel_usereg_login();
                    return self.fail("网络自助用户名或密码错误，请检查后重试");
                }
                UseregValidationOutcome::SessionExpired => {
                    self.invalidate_service_session(ServiceId::Usereg);
                    return self.fail("网络自助登录页面已过期，请重新输入账号密码获取验证码");
                }
                UseregValidationOutcome::Rejected => {
                    return self.fail("网络自助账号验证未通过，请检查输入后重试");
                }
            }

            let sms_code = sms_code
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty());
            // Validation may be explicitly retried after a rejected captcha.
            // Once the final login is submitted its result is single-use: an
            // ambiguous outcome must not retain material for replay.
            self.usereg_pending = None;
            let result = adapter
                .login_after_validation(
                    self.identity.transport(),
                    &page,
                    &credentials,
                    &verify_code,
                    sms_code,
                    validation,
                )
                .await
                .map_err(|error| {
                    self.invalidate_service_session(ServiceId::Usereg);
                    self.record_usereg_failure("usereg_final_login", &error)
                })?;
            if result.state != UseregAuthenticationState::Authenticated {
                self.invalidate_service_session(ServiceId::Usereg);
                return self.fail(match result.state {
                    UseregAuthenticationState::LoginFailed => {
                        "网络自助用户名或密码错误，请检查后重试"
                    }
                    UseregAuthenticationState::LoginRequired => {
                        "网络自助登录未完成，请检查验证码后重试"
                    }
                    UseregAuthenticationState::NonSuccess
                    | UseregAuthenticationState::Unknown
                    | UseregAuthenticationState::Authenticated => {
                        "网络自助登录状态未确认，请稍后重试"
                    }
                });
            }

            if !result.account_bound {
                // The strong home-page path remains valid for existing
                // deployments. A sparse but authenticated home has already
                // been account-bound through `/users` by the adapter, so it
                // does not need a second home/account round trip here.
                let home_plan = adapter
                    .home_request_plan()
                    .map_err(|error| self.record_error(format!("USEREG home: {error}")))?;
                let home = adapter
                    .client()
                    .execute_success(self.identity.transport(), &home_plan)
                    .await
                    .map_err(|error| {
                        self.invalidate_service_session(ServiceId::Usereg);
                        self.record_error(format!("USEREG home: {error}"))
                    })?;
                let login_required = adapter
                    .client()
                    .is_login_required(
                        home.status,
                        &home.final_url,
                        home.body_text()
                            .map_err(|error| self.record_error(format!("USEREG home: {error}")))?,
                    )
                    .map_err(|error| {
                        self.invalidate_service_session(ServiceId::Usereg);
                        self.record_error(format!("USEREG home: {error}"))
                    })?;
                if login_required {
                    self.invalidate_service_session(ServiceId::Usereg);
                    return self.fail("网络自助服务会话未建立，请重试");
                }

                adapter
                    .confirm_account_username(self.identity.transport(), &credentials.username)
                    .await
                    .map_err(|error| {
                        self.invalidate_service_session(ServiceId::Usereg);
                        self.record_usereg_failure("usereg_account_proof", &error)
                    })?;
            }
            let user = UserIdentity {
                username: credentials.username.clone(),
                display_name: None,
            };
            if let Err(error) =
                self.coordinator
                    .mark_authenticated(ServiceId::Usereg, user, None, None, None)
            {
                self.invalidate_service_session(ServiceId::Usereg);
                return Err(self.record_error(format!("USEREG session: {error}")));
            }
            self.usereg_adapter = Some(adapter);
            self.usereg_pending = None;
            if !self.service_session_is_proven(ServiceId::Usereg) {
                self.invalidate_service_session(ServiceId::Usereg);
                return self.fail("网络自助服务会话建立状态未确认，请稍后重试");
            }
            self.self_service_account_username = Some(credentials.username.clone());
            self.last_error = None;
            let credentials_saved = remember_credentials
                && self
                    .save_self_service_credential(&credentials.username, credentials.password())
                    .is_ok();
            Ok((self.status(), credentials_saved))
        })
        .await
    }

    /// Reads the independently authenticated USEREG account summary.
    pub async fn load_usereg_account(&mut self) -> Result<UseregAccountDto, String> {
        crate::telemetry::observe("usereg", "load_usereg_account", async {
            self.allow_live_operation()?;
            let Some(adapter) = self.usereg_adapter.clone() else {
                return self.fail("网络自助服务会话未建立");
            };
            if !self.service_session_is_proven(ServiceId::Usereg) {
                self.invalidate_service_session(ServiceId::Usereg);
                return self.fail("网络自助服务会话未建立");
            }
            let expected = self
                .coordinator
                .registry()
                .snapshot_for(ServiceId::Usereg)
                .user
                .ok_or_else(|| self.record_error("网络自助服务会话未建立"))?
                .username;
            let account = match adapter
                .read_account_info_for(self.identity.transport(), Some(&expected))
                .await
            {
                Ok(account) => account,
                Err(error) => {
                    if error.is_session_failure() {
                        self.invalidate_service_session(ServiceId::Usereg);
                    }
                    return Err(self.record_usereg_failure("usereg_account", &error));
                }
            };
            self.last_error = None;
            self.persist_identity_resume_state_after_live_read("usereg");
            Ok(account.into())
        })
        .await
    }

    /// Reads the currently online USEREG devices. The portal identifiers and
    /// MAC addresses are cached only inside Rust; Flutter receives list indexes
    /// and masked display data for a later disconnect action.
    pub async fn load_usereg_devices(&mut self) -> Result<Vec<UseregDeviceDto>, String> {
        crate::telemetry::observe("usereg", "load_usereg_devices", async {
            self.allow_live_operation()?;
            let Some(adapter) = self.usereg_adapter.clone() else {
                return self.fail("网络自助服务会话未建立");
            };
            if !self.service_session_is_proven(ServiceId::Usereg) {
                self.invalidate_service_session(ServiceId::Usereg);
                return self.fail("网络自助服务会话未建立");
            }
            let devices = match adapter.read_online_devices(self.identity.transport()).await {
                Ok(devices) => devices,
                Err(error) => {
                    // Preserve authentication on read failures, but never retain
                    // stale row indexes as targets for a later disconnect action.
                    self.clear_usereg_device_targets();
                    if error.is_session_failure() {
                        self.invalidate_service_session(ServiceId::Usereg);
                    }
                    return Err(self.record_usereg_failure("usereg_devices", &error));
                }
            };
            self.advance_usereg_device_generation();
            self.usereg_devices = devices.clone();
            self.last_error = None;
            self.persist_identity_resume_state_after_live_read("usereg");
            Ok(devices
                .iter()
                .enumerate()
                .map(|(index, device)| map_usereg_device(index, device))
                .collect())
        })
        .await
    }

    /// SDK-only form of the legacy device read. The generation stays inside
    /// Rust and is paired with opaque DeviceRef values by the engine facade.
    pub(crate) async fn load_usereg_devices_for_sdk(
        &mut self,
    ) -> Result<(u64, Vec<UseregDeviceDto>), String> {
        let devices = self.load_usereg_devices().await?;
        Ok((self.usereg_devices_generation, devices))
    }

    pub(crate) fn usereg_device_reference_is_current(&self, generation: u64, index: u32) -> bool {
        generation == self.usereg_devices_generation
            && self.usereg_devices.get(index as usize).is_some()
    }

    /// Validates a generation-bound SDK reference before delegating to the
    /// compatibility operation. The actual portal identifiers never leave
    /// this Runtime, and a stale reference cannot dispatch a request.
    pub(crate) async fn disconnect_usereg_device_for_sdk(
        &mut self,
        generation: u64,
        index: u32,
    ) -> Result<(), String> {
        if !self.usereg_device_reference_is_current(generation, index) {
            return self.fail("网络自助设备引用已过期，请刷新设备列表");
        }
        self.disconnect_usereg_device(index).await.map(|_| ())
    }

    fn advance_usereg_device_generation(&mut self) {
        self.usereg_devices_generation = self.usereg_devices_generation.wrapping_add(1);
    }

    fn clear_usereg_device_targets(&mut self) {
        self.advance_usereg_device_generation();
        self.usereg_devices.clear();
    }

    /// Reads the authenticated USEREG usage/balance table. A missing table is
    /// reported as unavailable instead of being converted to a zero balance.
    pub async fn load_usereg_balance(&mut self) -> Result<UseregBalanceDto, String> {
        crate::telemetry::observe("usereg", "load_usereg_balance", async {
            self.allow_live_operation()?;
            let Some(adapter) = self.usereg_adapter.clone() else {
                return self.fail("网络自助服务会话未建立");
            };
            if !self.service_session_is_proven(ServiceId::Usereg) {
                self.invalidate_service_session(ServiceId::Usereg);
                return self.fail("网络自助服务会话未建立");
            }
            let balance = match adapter.read_balance(self.identity.transport()).await {
                Ok(balance) => balance,
                Err(error) => {
                    if error.is_session_failure() {
                        self.invalidate_service_session(ServiceId::Usereg);
                    }
                    return Err(self.record_usereg_failure("usereg_balance", &error));
                }
            };
            self.last_error = None;
            self.persist_identity_resume_state_after_live_read("usereg");
            Ok(balance.into())
        })
        .await
    }

    /// Disconnects one displayed USEREG device by its current list index.
    /// Device identifiers and the CSRF-bound request remain Rust-owned.
    pub async fn disconnect_usereg_device(
        &mut self,
        index: u32,
    ) -> Result<CampusRuntimeStatusDto, String> {
        crate::telemetry::observe("usereg", "disconnect_usereg_device", async {
            self.allow_live_operation()?;
            if !self.service_session_is_proven(ServiceId::Usereg) {
                if self.usereg_adapter.is_some()
                    || self
                        .coordinator
                        .registry()
                        .snapshot_for(ServiceId::Usereg)
                        .state
                        != ServiceSessionState::Anonymous
                {
                    self.invalidate_service_session(ServiceId::Usereg);
                }
                return self.fail("网络自助服务会话未建立");
            }
            let Some(adapter) = self.usereg_adapter.clone() else {
                return self.fail("网络自助服务会话未建立");
            };
            let Some(device) = self.usereg_devices.get(index as usize).cloned() else {
                return self.fail("网络自助设备编号无效，请先刷新设备列表");
            };
            let target = UseregDeviceTarget::new(device.id, device.mac)
                .map_err(|error| self.record_error(format!("USEREG device: {error}")))?;
            let result = match adapter
                .disconnect_device(self.identity.transport(), &target)
                .await
            {
                Ok(result) => result,
                Err(error) => {
                    self.invalidate_service_session(ServiceId::Usereg);
                    return Err(self.record_error(format!("USEREG disconnect: {error}")));
                }
            };
            if !result.confirmed {
                self.invalidate_service_session(ServiceId::Usereg);
                return self.fail("网络自助设备断开状态未确认，请稍后重试");
            }
            self.usereg_devices.remove(index as usize);
            // Every handle came from the prior complete list. The successful
            // mutation changes row positions, so invalidate all of them.
            self.advance_usereg_device_generation();
            self.last_error = None;
            Ok(self.status())
        })
        .await
    }

    /// Returns the safe service catalog for this runtime's current sessions.
    ///
    /// The catalog contains only coarse availability and authentication-source
    /// labels. Cookies, tickets, CSRF values, URLs, and response bodies remain
    /// owned by Rust and never cross the Flutter boundary.
    pub fn service_catalog(&self) -> ServiceCatalogDto {
        // A cache-backed capability is a read permission, not a service proof.
        // Resolve the account context locally and let the catalog expose only
        // envelopes that this same runtime would accept in its read methods.
        // An account mismatch or malformed cache therefore fails closed here
        // just as it does at the actual reader boundary.
        let cache_capabilities = self
            .cache_user_for_read()
            .ok()
            .flatten()
            .map(|user| self.cache_capabilities_for_catalog(&user))
            .unwrap_or_default();
        let mut catalog =
            super::service_catalog::list_runtime_service_catalog_with_resolver_and_cache(
                &self.coordinator,
                super::service_catalog::RuntimeServiceProofs {
                    learn: self.service_session_is_proven(ServiceId::Learn),
                    registrar: self.service_session_is_proven(ServiceId::Registrar),
                    info: self.service_session_is_proven(ServiceId::Info),
                    classroom: self.classroom_service_is_proven(),
                    electricity: self.electricity_service_is_proven(),
                    library: self.service_session_is_proven(ServiceId::Library),
                    campus_card: self.service_session_is_proven(ServiceId::CampusCard),
                    usereg: self.service_session_is_proven(ServiceId::Usereg),
                    tunet: self.tunet_connection_target.is_some(),
                },
                self.resolver.is_some(),
                cache_capabilities,
            );
        // Advertise cache-aware read entry points before their first handoff.
        // This is not a successful service status: the read still checks the
        // owner, lease, service proof and authentication/recovery gates.
        if self.status().state == "authenticated"
            && self.service_session_is_proven(ServiceId::Identity)
            && self.allow_live_operation().is_ok()
            && self.cache_user_for_read().ok().flatten().is_some()
        {
            super::service_catalog::enable_automatic_readers(&mut catalog, &self.coordinator);
        }
        if let Some(pending) = self.current_service_second_factor() {
            for entry in &mut catalog.services {
                let affected = match pending.target {
                    ServiceSecondFactorTarget::Portal => matches!(
                        entry.id.as_str(),
                        "info" | "library" | "classroom" | "electricity"
                    ),
                    ServiceSecondFactorTarget::CampusCard => entry.id == "campus_card",
                    ServiceSecondFactorTarget::Electricity => entry.id == "electricity",
                };
                if affected && entry.availability != "available" {
                    entry.availability = "requires_second_factor".to_owned();
                    entry.capabilities.clear();
                }
            }
        }
        catalog
    }

    /// Computes the cache capabilities that the service catalog may expose.
    /// This is deliberately a pure local probe: it never establishes a
    /// service, reads a private-vault credential, or sends an HTTP request.
    fn cache_capabilities_for_catalog(
        &self,
        user: &UserIdentity,
    ) -> super::service_catalog::RuntimeCacheCapabilities {
        let stage = self.catalog_stage_for_user(user);
        let semester = stage.and_then(|stage| self.catalog_semester_for_user(user, stage));
        let academic = stage.zip(semester.as_deref());

        super::service_catalog::RuntimeCacheCapabilities {
            learn_courses: academic.is_some_and(|(stage, semester)| {
                self.learn_course_cache_is_available_for_catalog(user, stage, semester)
            }),
            learn_announcements: academic.is_some_and(|(stage, semester)| {
                self.learn_announcement_cache_is_available_for_catalog(user, stage, semester)
            }),
            learn_schedule: stage
                .is_some_and(|stage| self.schedule_cache_is_available_for_catalog(user, stage)),
            registrar_grades: academic.is_some_and(|(stage, semester)| {
                self.registrar_grades_cache_is_available_for_catalog(user, stage, semester)
            }),
            registrar_exams: academic.is_some_and(|(stage, semester)| {
                self.registrar_exams_cache_is_available_for_catalog(user, semester, stage)
            }),
            info_news: self.info_news_cache_is_available_for_catalog(&user.username),
            library_areas: self.library_area_cache_is_available_for_catalog(&user.username),
            electricity_history: self
                .electricity_history_cache_is_available_for_catalog(&user.username),
            campus_card_account: self
                .campus_card_account_cache_is_available_for_catalog(&user.username),
            campus_card_transactions: self
                .campus_card_transactions_cache_is_available_for_catalog(&user.username),
        }
    }

    fn catalog_stage_for_user(&self, user: &UserIdentity) -> Option<AcademicStage> {
        if self.stage_detected || self.stage_selection_explicit || !self.stage_auto_detection {
            return Some(self.stage);
        }
        registrar_auth::academic_stage_from_student_id(&user.username)
    }

    fn catalog_semester_for_user(
        &self,
        user: &UserIdentity,
        stage: AcademicStage,
    ) -> Option<String> {
        if self.semester != AUTO_SEMESTER
            && crate::learn::validate_semester_id(&self.semester).is_ok()
        {
            return Some(self.semester.clone());
        }
        let configured = self.semester_config.trim();
        if configured != AUTO_SEMESTER && crate::learn::validate_semester_id(configured).is_ok() {
            return Some(configured.to_owned());
        }
        let cache = JsonFileCache::<LearnSemesterCachePayload>::new(
            learn_semester_cache_path_for_account_stage(&self.cache_path, &user.username, stage),
            LEARN_CACHE_SCHEMA_VERSION,
            LEARN_SEMESTER_CACHE_SERVICE,
        );
        if let Ok(Some(envelope)) = cache.read() {
            if learn_semester_cache_payload_is_valid(&envelope.payload, &user.username, stage) {
                return Some(envelope.payload.semester);
            }
        }

        if let Some(semester) =
            find_learn_course_cache_semester(&self.cache_path, &user.username, stage)
        {
            return Some(semester);
        }

        // Grades or exams may be the only academic data that was persisted
        // before a process restart.  Their Registrar-owned semester pointer
        // and bounded report scan are safe local context sources too; without
        // them the catalog would hide valid cache capabilities and the next
        // page read would unnecessarily enter an authentication path.
        if let Some(semester) =
            read_registrar_current_semester_cache(&self.cache_path, &user.username, stage)
        {
            return Some(semester);
        }
        if let Some(semester) =
            find_registrar_cache_semester(&self.cache_path, &user.username, stage)
        {
            return Some(semester);
        }

        // A process may have persisted an announcement list without retaining
        // the separate current-semester index (for example after a partial
        // cache migration or a cache directory cleanup).  The announcement
        // envelope carries the same account/stage/semester binding and the
        // real course id that was verified before it was written, so it is a
        // safe last-resort context source for the catalog.  This remains a
        // local probe and never turns the catalog into a live Learn request.
        find_learn_announcement_cache(&self.cache_path, &user.username, stage, None, None)
            .map(|payload| payload.semester)
    }

    fn learn_course_cache_is_available_for_catalog(
        &self,
        user: &UserIdentity,
        stage: AcademicStage,
        semester: &str,
    ) -> bool {
        let cache = JsonFileCache::<LearnCourseListCachePayload>::new(
            learn_course_list_cache_path(&self.cache_path, &user.username, semester, stage),
            LEARN_CACHE_SCHEMA_VERSION,
            LEARN_COURSE_LIST_CACHE_SERVICE,
        );
        match cache.read() {
            Ok(Some(envelope)) => {
                learn_course_list_cache_payload_is_valid(
                    &envelope.payload,
                    &user.username,
                    semester,
                    stage,
                ) && learn_course_cache_is_usable(&envelope.payload.generated_at)
            }
            Ok(None) | Err(_) => false,
        }
    }

    /// Checks every locally stored Learn announcement envelope without asking
    /// `JsonFileCache` to deserialize unrelated cache payloads.  The cache
    /// file name is intentionally an account/context hash, so the catalog
    /// cannot reconstruct a course-specific path from the current course
    /// list.  Reading the generic envelope first keeps this probe read-only:
    /// a valid course, INFO, or schedule cache is never deleted merely
    /// because it is not an announcement payload.
    fn learn_announcement_cache_is_available_for_catalog(
        &self,
        user: &UserIdentity,
        stage: AcademicStage,
        semester: &str,
    ) -> bool {
        find_learn_announcement_cache(
            &self.cache_path,
            &user.username,
            stage,
            Some(semester),
            None,
        )
        .is_some()
    }

