fn cache_account_scope(username: &str) -> String {
    let mut hasher = Sha1::new();
    hasher.update(b"thyou-cache-owner-v1\0");
    hasher.update(username.trim().as_bytes());
    hasher
        .finalize()
        .iter()
        .fold(String::with_capacity(40), |mut output, byte| {
            use std::fmt::Write;

            let _ = write!(output, "{byte:02x}");
            output
        })
}

fn campus_overview_cache_payload_is_valid(
    payload: &CampusOverviewCachePayload,
    username: &str,
    stage: AcademicStage,
    requested_date: NaiveDate,
    configured_semester: &str,
) -> bool {
    payload.account_scope == cache_account_scope(username)
        && payload.stage == stage
        && payload.date == requested_date
        && payload.overview.date == requested_date
        && payload.overview.semester.as_deref().is_none_or(|semester| {
            cache_semester_is_safe(semester)
                && (configured_semester == AUTO_SEMESTER || semester == configured_semester)
        })
        && payload.generated_at == payload.overview.generated_at
        && payload.generated_at <= Utc::now() + chrono::Duration::minutes(5)
}

fn read_account_bound_overview_cache(
    cache: &JsonFileCache<CampusOverviewCachePayload>,
    username: &str,
    stage: AcademicStage,
    requested_date: NaiveDate,
    configured_semester: &str,
    now: SystemTime,
) -> CampusOverviewFacadeDto {
    let cached = match cache.read() {
        Ok(Some(envelope))
            if campus_overview_cache_payload_is_valid(
                &envelope.payload,
                username,
                stage,
                requested_date,
                configured_semester,
            ) && campus_overview_cache_saved_at_is_usable(&envelope.saved_at, now) =>
        {
            Ok(Some(JsonCacheEnvelope {
                schema_version: CAMPUS_OVERVIEW_CACHE_SCHEMA_VERSION,
                service: CAMPUS_OVERVIEW_CACHE_SERVICE.to_owned(),
                saved_at: envelope.saved_at,
                payload: envelope.payload.overview,
            }))
        }
        Ok(Some(_)) => {
            // A valid envelope with a different owner, stage, or requested
            // day is a cache miss for this read.  It must never be exposed as
            // a stale overview or used to authorize a live request.
            return CampusOverviewFacade::from_cache(
                requested_date,
                Ok(None),
                now,
                CAMPUS_OVERVIEW_CACHE_MAX_AGE,
            );
        }
        Ok(None) => Ok(None),
        Err(error) => Err(error),
    };
    CampusOverviewFacade::from_cache(requested_date, cached, now, CAMPUS_OVERVIEW_CACHE_MAX_AGE)
}

fn campus_overview_cache_saved_at_is_usable(saved_at: &str, now: SystemTime) -> bool {
    let Ok(saved_at_millis) = saved_at.parse::<u128>() else {
        return false;
    };
    let Ok(now_millis) = now.duration_since(std::time::UNIX_EPOCH) else {
        return false;
    };
    let now_millis = now_millis.as_millis();
    if saved_at_millis > now_millis {
        return false;
    }
    let age_millis = now_millis.saturating_sub(saved_at_millis);
    let max_stale_millis = CAMPUS_OVERVIEW_CACHE_MAX_STALE_AGE.as_millis();
    age_millis <= max_stale_millis
}

fn cache_context_text_is_safe(value: &str, allow_empty: bool) -> bool {
    let value = value.trim();
    (allow_empty || !value.is_empty())
        && value.len() <= 256
        && !value.chars().any(|character| character.is_control())
}

fn cache_semester_is_safe(value: &str) -> bool {
    cache_context_text_is_safe(value, false)
        && value != AUTO_SEMESTER
        && !value.contains(['/', '?', '#'])
}

fn registrar_grades_cache_payload_is_valid(
    payload: &RegistrarGradesCachePayload,
    username: &str,
    configured_semester: &str,
    stage: AcademicStage,
    report_kind: Option<&str>,
) -> bool {
    if payload.account_scope != cache_account_scope(username)
        || payload.stage != stage
        || !cache_semester_is_safe(&payload.semester)
        || (configured_semester != AUTO_SEMESTER && payload.semester != configured_semester)
        || payload.report_kind.as_deref() != report_kind
        || payload.generated_at > Utc::now() + chrono::Duration::minutes(5)
    {
        return false;
    }

    let mut seen = HashSet::new();
    payload.courses.iter().all(|course| {
        cache_context_text_is_safe(&course.course_name, false)
            && course.credit.is_finite()
            && course.credit >= 0.0
            && cache_context_text_is_safe(&course.grade, false)
            && course
                .grade_point
                .is_none_or(|point| point.is_finite() && point >= 0.0)
            && course.semester == payload.semester
            && cache_context_text_is_safe(&course.semester, false)
            && seen.insert((&course.course_name, &course.semester))
    })
}

fn registrar_exams_cache_payload_is_valid(
    payload: &RegistrarExamsCachePayload,
    username: &str,
    configured_semester: &str,
    stage: AcademicStage,
) -> bool {
    if payload.account_scope != cache_account_scope(username)
        || payload.stage != stage
        || !cache_semester_is_safe(&payload.semester)
        || (configured_semester != AUTO_SEMESTER && payload.semester != configured_semester)
        || payload.generated_at > Utc::now() + chrono::Duration::minutes(5)
    {
        return false;
    }

    if stage == AcademicStage::Graduate {
        return graduate_exams::cache_rows_are_valid(payload);
    }
    if payload.calendar_window.is_some() {
        return false;
    }

    let mut seen = HashSet::new();
    payload.exams.iter().all(|exam| {
        cache_context_text_is_safe(&exam.course_code, false)
            && cache_context_text_is_safe(&exam.course_sequence, false)
            && cache_context_text_is_safe(&exam.course_name, false)
            && (1..=12).contains(&exam.exam_month)
            && (1..=days_in_month(exam.exam_month)).contains(&exam.exam_day)
            && cache_context_text_is_safe(&exam.exam_weekday, false)
            && cache_context_text_is_safe(&exam.exam_session, false)
            && cache_context_text_is_safe(&exam.schedule_raw, false)
            && cache_context_text_is_safe(&exam.location, false)
            && exam
                .department
                .as_deref()
                .is_none_or(|value| cache_context_text_is_safe(value, false))
            && exam
                .category
                .as_deref()
                .is_none_or(|value| cache_context_text_is_safe(value, false))
            && exam
                .instructor
                .as_deref()
                .is_none_or(|value| cache_context_text_is_safe(value, false))
            && exam.headcount.is_none_or(|value| value <= 1_000_000)
            && seen.insert((&exam.course_code, &exam.course_sequence, &exam.schedule_raw))
    })
}

fn registrar_current_semester_cache_payload_is_valid(
    payload: &RegistrarCurrentSemesterCachePayload,
    username: &str,
    stage: AcademicStage,
) -> bool {
    payload.account_scope == cache_account_scope(username)
        && payload.stage == stage
        && cache_semester_is_safe(&payload.semester)
        && crate::learn::validate_semester_id(&payload.semester).is_ok()
        && payload.generated_at <= Utc::now() + chrono::Duration::minutes(5)
}

fn registrar_current_semester_cache_is_usable(generated_at: &DateTime<Utc>) -> bool {
    cache_is_usable(generated_at, REGISTRAR_CURRENT_SEMESTER_CACHE_MAX_STALE_AGE)
}

fn read_registrar_current_semester_cache(
    base: &Path,
    username: &str,
    stage: AcademicStage,
) -> Option<String> {
    let path = registrar_current_semester_cache_path(base, username, stage);
    let cache = JsonFileCache::<RegistrarCurrentSemesterCachePayload>::new(
        &path,
        REGISTRAR_CURRENT_SEMESTER_CACHE_SCHEMA_VERSION,
        REGISTRAR_CURRENT_SEMESTER_CACHE_SERVICE,
    );
    match cache.read() {
        Ok(Some(envelope))
            if registrar_current_semester_cache_payload_is_valid(
                &envelope.payload,
                username,
                stage,
            ) && registrar_current_semester_cache_is_usable(&envelope.payload.generated_at) =>
        {
            Some(envelope.payload.semester)
        }
        Ok(Some(_)) | Ok(None) => None,
        Err(error) => {
            tracing::warn!(
                target: "tsinghua_kit::storage",
                event = "registrar_current_semester_cache_read_failed",
                reason = "cache_unavailable",
                error = %error
            );
            None
        }
    }
}

fn persist_registrar_current_semester_cache(
    base: &Path,
    username: &str,
    stage: AcademicStage,
    semester: &str,
    generated_at: DateTime<Utc>,
) {
    let payload = RegistrarCurrentSemesterCachePayload {
        account_scope: cache_account_scope(username),
        semester: semester.to_owned(),
        stage,
        generated_at,
    };
    if !registrar_current_semester_cache_payload_is_valid(&payload, username, stage) {
        return;
    }
    let cache = JsonFileCache::<RegistrarCurrentSemesterCachePayload>::new(
        registrar_current_semester_cache_path(base, username, stage),
        REGISTRAR_CURRENT_SEMESTER_CACHE_SCHEMA_VERSION,
        REGISTRAR_CURRENT_SEMESTER_CACHE_SERVICE,
    );
    if let Err(error) = cache.write(&payload) {
        tracing::warn!(
            target: "tsinghua_kit::storage",
            event = "registrar_current_semester_cache_write_failed",
            reason = "storage_io",
            error = %error
        );
    }
}

fn info_news_cache_option_is_valid(value: &Option<String>) -> bool {
    value
        .as_deref()
        .is_none_or(|value| cache_context_text_is_safe(value, false))
}

fn info_news_cache_option_matches(value: &Option<String>, expected: Option<&str>) -> bool {
    value.as_deref() == expected
}

fn info_news_cache_payload_is_valid(
    payload: &InfoNewsPageCachePayload,
    username: &str,
    feed: &str,
    page: u32,
    page_size: u32,
    source_id: Option<&str>,
    channel_id: Option<&str>,
    keyword: &str,
    channel_filter_label: Option<&str>,
    exact_match: bool,
) -> bool {
    if payload.account_scope != cache_account_scope(username)
        || payload.feed != feed
        || payload.page != page
        || payload.page_size != page_size
        || !info_news_cache_option_matches(&payload.source_id, source_id)
        || !info_news_cache_option_matches(&payload.channel_id, channel_id)
        || payload.keyword != keyword
        || !info_news_cache_option_matches(&payload.channel_filter_label, channel_filter_label)
        || payload.exact_match != exact_match
        || payload.generated_at > Utc::now() + chrono::Duration::minutes(5)
        || !matches!(feed, "list" | "search")
        || page == 0
        || (feed == "list" && !(1..=INFO_NEWS_MAX_PAGE_SIZE).contains(&page_size))
        || (feed == "search" && page_size != 0)
        || !cache_context_text_is_safe(&payload.keyword, true)
        || !info_news_cache_option_is_valid(&payload.source_id)
        || !info_news_cache_option_is_valid(&payload.channel_id)
        || !info_news_cache_option_is_valid(&payload.channel_filter_label)
        || payload.items.len() > INFO_NEWS_MAX_PAGE_SIZE as usize
    {
        return false;
    }

    let mut ids = HashSet::new();
    payload.items.iter().all(|item| {
        cache_context_text_is_safe(&item.id, false)
            && cache_context_text_is_safe(&item.title, false)
            && cache_context_text_is_safe(&item.link, false)
            && cache_context_text_is_safe(&item.published_at, false)
            && cache_context_text_is_safe(&item.source, false)
            && cache_context_text_is_safe(&item.channel, false)
            && ids.insert(item.id.as_str())
    })
}

fn info_news_cache_is_fresh(generated_at: &DateTime<Utc>) -> bool {
    cache_is_fresh(generated_at, INFO_NEWS_CACHE_MAX_AGE)
}

fn info_news_cache_is_usable(generated_at: &DateTime<Utc>) -> bool {
    let age = Utc::now()
        .signed_duration_since(*generated_at)
        .num_seconds();
    age >= 0 && age <= INFO_NEWS_CACHE_MAX_STALE_AGE.as_secs() as i64
}

fn info_news_detail_cache_is_fresh(generated_at: &DateTime<Utc>) -> bool {
    cache_is_fresh(generated_at, INFO_NEWS_DETAIL_CACHE_MAX_AGE)
}

fn info_news_detail_cache_is_usable(generated_at: &DateTime<Utc>) -> bool {
    let age = Utc::now()
        .signed_duration_since(*generated_at)
        .num_seconds();
    age >= 0 && age <= INFO_NEWS_DETAIL_CACHE_MAX_STALE_AGE.as_secs() as i64
}

fn cache_markup_is_safe(value: &str, allow_empty: bool) -> bool {
    (allow_empty || !value.is_empty())
        && value.len() <= 1_000_000
        && !value
            .chars()
            .any(|character| character.is_control() && !matches!(character, '\n' | '\r' | '\t'))
}

fn info_news_detail_cache_payload_is_valid(
    payload: &InfoNewsDetailCachePayload,
    username: &str,
    article_id: &str,
    bound_link: &str,
) -> bool {
    if payload.account_scope != cache_account_scope(username)
        || payload.article_id != article_id
        || payload.bound_link != bound_link
        || !cache_context_text_is_safe(&payload.article_id, false)
        || !cache_context_text_is_safe(&payload.bound_link, false)
        || payload.generated_at > Utc::now() + chrono::Duration::minutes(5)
        // Some pinned legacy policies intentionally have no title. A real
        // body and strict account/article/link binding remain mandatory.
        || !cache_context_text_is_safe(&payload.title, true)
        || !cache_markup_is_safe(&payload.content_html, true)
        || !cache_markup_is_safe(&payload.summary, true)
        || (payload.content_html.is_empty() && payload.summary.is_empty())
        || payload.attachments.len() > 128
    {
        return false;
    }

    let mut ids = HashSet::new();
    payload.attachments.iter().all(|attachment| {
        cache_context_text_is_safe(&attachment.id, false)
            && cache_context_text_is_safe(&attachment.name, false)
            && ids.insert(attachment.id.as_str())
    })
}

fn map_info_news_cache_payload(
    payload: &InfoNewsPageCachePayload,
    source: &'static str,
    status: &'static str,
    error: Option<String>,
) -> InfoNewsPageDto {
    InfoNewsPageDto {
        feed: payload.feed.clone(),
        items: payload.items.clone(),
        empty: payload.items.is_empty(),
        generated_at: Some(payload.generated_at.to_rfc3339()),
        source: Some(source.to_owned()),
        status: Some(status.to_owned()),
        error,
    }
}

fn map_info_news_detail_cache_payload(
    payload: &InfoNewsDetailCachePayload,
    source: &'static str,
    status: &'static str,
    error: Option<String>,
) -> InfoNewsDetailResultDto {
    InfoNewsDetailResultDto {
        id: payload.article_id.clone(),
        title: payload.title.clone(),
        content_html: payload.content_html.clone(),
        summary: payload.summary.clone(),
        attachments: payload.attachments.clone(),
        generated_at: payload.generated_at.to_rfc3339(),
        source: source.to_owned(),
        status: status.to_owned(),
        error,
    }
}

