fn campus_card_transaction_type_name(value: CampusCardTransactionType) -> &'static str {
    match value {
        CampusCardTransactionType::Any => "any",
        CampusCardTransactionType::Consumption => "consumption",
        CampusCardTransactionType::Recharge => "recharge",
        CampusCardTransactionType::Subsidy => "subsidy",
    }
}

fn parse_campus_card_transaction_type(value: &str) -> Result<CampusCardTransactionType, String> {
    match value.trim().to_ascii_lowercase().as_str() {
        "any" => Ok(CampusCardTransactionType::Any),
        "consumption" => Ok(CampusCardTransactionType::Consumption),
        "recharge" => Ok(CampusCardTransactionType::Recharge),
        "subsidy" => Ok(CampusCardTransactionType::Subsidy),
        _ => Err(String::from("校园卡交易类型无效")),
    }
}

fn library_campus_date_is_current_or_tomorrow(day: NaiveDate, now: DateTime<Utc>) -> bool {
    let today = campus_date_at(now);
    day == today || Some(day) == today.succ_opt()
}

