fn library_area_tree_cache_payload_is_valid(
    payload: &LibraryAreaTreeCachePayload,
    username: &str,
) -> bool {
    if payload.account_scope != cache_account_scope(username)
        || payload.generated_at > Utc::now() + chrono::Duration::minutes(5)
        || payload.areas.len() > 4096
    {
        return false;
    }

    fn visit(
        area: &crate::library_read::LibraryAreaDto,
        depth: usize,
        seen: &mut HashSet<u64>,
    ) -> bool {
        depth <= 16
            && area.id > 0
            && cache_context_text_is_safe(&area.name, false)
            && area
                .name_merge
                .as_deref()
                .is_none_or(|value| cache_context_text_is_safe(value, false))
            && area
                .english_name
                .as_deref()
                .is_none_or(|value| cache_context_text_is_safe(value, false))
            && area
                .english_name_merge
                .as_deref()
                .is_none_or(|value| cache_context_text_is_safe(value, false))
            && area.total_count.is_none_or(|value| value <= 10_000_000)
            && area
                .unavailable_space
                .is_none_or(|value| value <= 10_000_000)
            && area.available_count.is_none_or(|value| value <= 10_000_000)
            && area.point_x.is_none_or(f64::is_finite)
            && area.point_y.is_none_or(f64::is_finite)
            && seen.insert(area.id)
            && area
                .child_areas
                .iter()
                .all(|child| visit(child, depth + 1, seen))
    }

    let mut seen = HashSet::new();
    payload.areas.iter().all(|area| visit(area, 0, &mut seen))
}

fn library_day_segments_cache_payload_is_valid(
    payload: &LibraryDaySegmentsCachePayload,
    username: &str,
    section_id: u64,
) -> bool {
    if payload.account_scope != cache_account_scope(username)
        || payload.section_id != section_id
        || section_id == 0
        || payload.generated_at > Utc::now() + chrono::Duration::minutes(5)
        || payload.segments.len() > 512
    {
        return false;
    }

    let mut seen = HashSet::new();
    payload.segments.iter().all(|segment| {
        let day = NaiveDate::parse_from_str(&segment.day, "%Y-%m-%d");
        let start = NaiveTime::parse_from_str(&segment.start_time, "%H:%M")
            .or_else(|_| NaiveTime::parse_from_str(&segment.start_time, "%H:%M:%S"));
        let end = NaiveTime::parse_from_str(&segment.end_time, "%H:%M")
            .or_else(|_| NaiveTime::parse_from_str(&segment.end_time, "%H:%M:%S"));
        segment.id > 0
            && day.is_ok()
            && start.is_ok()
            && end.is_ok()
            && start.unwrap() < end.unwrap()
            && cache_context_text_is_safe(&segment.day, false)
            && cache_context_text_is_safe(&segment.start_time, false)
            && cache_context_text_is_safe(&segment.end_time, false)
            && seen.insert(segment.id)
    })
}

