fn session_state_name(state: ServiceSessionState) -> &'static str {
    match state {
        ServiceSessionState::Anonymous => "signed_out",
        ServiceSessionState::Authenticating => "authenticating",
        ServiceSessionState::RequiresSecondFactor => "requires_second_factor",
        ServiceSessionState::Authenticated => "authenticated",
        ServiceSessionState::Expired => "expired",
    }
}

fn second_factor_method_name(method: &SecondFactorMethod) -> &'static str {
    match method {
        SecondFactorMethod::Mobile => "mobile",
        SecondFactorMethod::Sms => "sms",
        SecondFactorMethod::Totp => "totp",
        SecondFactorMethod::Wechat => "wechat",
    }
}

fn trusted_device_status_name(status: TrustedDeviceStatus) -> &'static str {
    match status {
        TrustedDeviceStatus::Saved => "saved",
        TrustedDeviceStatus::LimitReached => "limit_reached",
        TrustedDeviceStatus::Rejected => "rejected",
        TrustedDeviceStatus::InvalidResponse => "invalid_response",
        TrustedDeviceStatus::RequestFailed => "request_failed",
    }
}

