        assert_eq!(transactions.transactions[0].merchant_address, "");
        assert_eq!(transactions.transactions[0].amount_cents, -345);
        assert!(runtime.service_session_is_proven(ServiceId::CampusCard));
        server.join().unwrap();
        let _ = std::fs::remove_dir_all(cache_root);
