    #[test]
    fn backend_repair_portal_oauth_redirect_is_strict_and_preserves_target_uri() {
        let target = reqwest::Url::parse(
            "https://info.tsinghua.edu.cn/f/info/gxfw_fg/common/index?mode=fixture",
        )
        .unwrap();
        let oauth = portal_oauth_redirect_url(&target).expect("portal OAuth URL");
        assert_eq!(oauth.scheme(), "https");
        assert_eq!(oauth.host_str(), Some("oauth.tsinghua.edu.cn"));
        assert_eq!(oauth.path(), "/lb-auth/lbredirect");
        let query = oauth
            .query_pairs()
            .collect::<std::collections::HashMap<_, _>>();
        assert_eq!(
            query.get("scheme").map(|value| value.as_ref()),
            Some("https")
        );
        assert_eq!(
            query.get("host").map(|value| value.as_ref()),
            Some("info.tsinghua.edu.cn")
        );
        assert_eq!(query.get("port").map(|value| value.as_ref()), Some("443"));
        assert_eq!(
            query.get("uri").map(|value| value.as_ref()),
            Some("/f/info/gxfw_fg/common/index?mode=fixture")
        );

        for unsafe_target in [
            "https://evil.example/f/info/gxfw_fg/common/index",
            "https://user@info.tsinghua.edu.cn/f/info/gxfw_fg/common/index",
            "https://info.tsinghua.edu.cn/f/info/gxfw_fg/common/index#fragment",
        ] {
            assert!(
                portal_oauth_redirect_url(&reqwest::Url::parse(unsafe_target).unwrap()).is_err()
            );
        }
    }

