    fn backend_repair_portal_handoff_allows_only_known_oauth_bridge_routes() {
        let webvpn = reqwest::Url::parse(
            "https://webvpn.tsinghua.edu.cn/https/mapped/f/info/gxfw_fg/common/index",
        )
        .unwrap();
        for allowed in [
            "https://oauth.tsinghua.edu.cn/thu-oauth/auth?state=fixture",
            "https://oauth.tsinghua.edu.cn/lb-auth/lbredirect?state=fixture",
        ] {
            let target = reqwest::Url::parse(allowed).unwrap();
            assert!(portal_oauth_bridge_target_allowed(&target));
            assert!(portal_handoff_redirect_allowed(&webvpn, &target));
        }
        for denied in [
            "https://oauth.tsinghua.edu.cn/login?state=fixture",
            "https://user@oauth.tsinghua.edu.cn/thu-oauth/auth?state=fixture",
            "https://oauth.tsinghua.edu.cn/thu-oauth/auth?state=fixture#fragment",
            "https://evil.example/thu-oauth/auth?state=fixture",
        ] {
            let target = reqwest::Url::parse(denied).unwrap();
            assert!(!portal_oauth_bridge_target_allowed(&target));
            assert!(!portal_handoff_redirect_allowed(&webvpn, &target));
        }
        let info = reqwest::Url::parse("https://info.tsinghua.edu.cn/f/info/gxfw_fg/common/index")
            .unwrap();
        let oauth =
            reqwest::Url::parse("https://oauth.tsinghua.edu.cn/thu-oauth/auth?state=fixture")
                .unwrap();
        assert!(!portal_handoff_redirect_allowed(&info, &oauth));
    }

    #[test]
    fn backend_repair_portal_handoff_allows_fixed_identity_callback_bridge() {
        let webvpn = reqwest::Url::parse(
            "https://webvpn.tsinghua.edu.cn/https/mapped/f/info/gxfw_fg/common/index",
        )
        .unwrap();
        let identity = reqwest::Url::parse(
            "https://id.tsinghua.edu.cn/do/off/ui/auth/login/redirect2Jsp?state=fixture",
        )
        .unwrap();
        let info = reqwest::Url::parse("https://info.tsinghua.edu.cn/f/info/gxfw_fg/common/index")
            .unwrap();
        let oauth =
            reqwest::Url::parse("https://oauth.tsinghua.edu.cn/lb-auth/lbredirect?state=fixture")
                .unwrap();

        assert!(portal_handoff_redirect_allowed(&oauth, &info));
        assert!(portal_handoff_redirect_allowed(&webvpn, &identity));
        assert!(portal_handoff_redirect_allowed(&identity, &info));
        for path in [
            "/do/off/ui/auth/login/check",
            "/do/off/ui/auth/login/checkSingle",
        ] {
            let continuation =
                reqwest::Url::parse(&format!("https://id.tsinghua.edu.cn{path}?state=fixture"))
                    .unwrap();
            assert!(portal_handoff_redirect_allowed(&identity, &continuation));
        }
        assert!(portal_handoff_redirect_allowed(
            &identity,
            &reqwest::Url::parse("https://id.tsinghua.edu.cn/do/off/ui/auth/login/form/portal")
                .unwrap()
        ));
    }

    #[test]
    fn backend_repair_portal_handoff_checks_identity_login_form_as_intermediate() {
        let oauth =
            reqwest::Url::parse("https://oauth.tsinghua.edu.cn/lb-auth/lbredirect?state=fixture")
                .unwrap();
        let identity_form = reqwest::Url::parse(
            "https://id.tsinghua.edu.cn/do/off/ui/auth/login/form/10000ea055dd8d81d09d5a1ba55d39ad/0?flow=fixture",
        )
        .unwrap();

        assert!(
            portal_handoff_redirect_allowed(&oauth, &identity_form),
            "a target identity login form is a checked intermediate hop, not a terminal success"
        );
        assert!(
            !portal_handoff_target_allowed(&identity_form),
            "an identity login form must never count as the final portal proof"
        );
    }

