    #[test]
    fn backend_repair_fresh_portal_generic_template_allows_password_then_success_navigation() {
        let runtime = CampusRuntime::new("2026-fall".to_owned(), false, String::new())
            .expect("runtime config");
        let client = runtime.identity.identity().client().clone();
        let initial = r#"
            <div>登录失败</div>
            <div id="sm2publicKey">fixture-key</div>
            <form method="post" action="/do/off/ui/auth/login/check">
              <input name="i_user"><input name="i_pass" type="password">
            </form>
        "#;
        assert!(
            !portal_fresh_entry_has_terminal_failure(&client, initial),
            "a generic GET template notice must not block the credential fallback"
        );

        let response_url =
            reqwest::Url::parse("https://id.tsinghua.edu.cn/do/off/ui/auth/login/check").unwrap();
        let target = reqwest::Url::parse(
            "https://info.tsinghua.edu.cn/f/info/gxfw_fg/common/index?ticket=fixture",
        )
        .unwrap();
        let submitted = r#"
            <div>登录失败</div>
            <div>登录成功。正在重定向到</div>
            <form method="post" action="/do/off/ui/auth/login/check">
              <input name="i_user"><input name="i_pass" type="password">
            </form>
            <a href="https://info.tsinghua.edu.cn/f/info/gxfw_fg/common/index?ticket=fixture">continue</a>
        "#;
        assert_eq!(
            portal_target_from_submitted_identity_evidence(
                &client,
                &response_url,
                reqwest::StatusCode::OK,
                None,
                submitted,
            )
            .as_ref(),
            Some(&target),
            "an explicit submitted success navigation may outrank stale generic/form markup"
        );

        for explicit_failure in [
            "用户名或密码错误",
            "请输入验证码",
            "二次认证",
            r#"<input name="loginInvalid" value="true">"#,
        ] {
            let body = format!("{explicit_failure}{submitted}");
            assert!(
                portal_target_from_submitted_identity_evidence(
                    &client,
                    &response_url,
                    reqwest::StatusCode::OK,
                    None,
                    &body,
                )
                .is_none(),
                "explicit failure evidence must still fail closed"
            );
        }
    }

