    #[test]
    fn backend_repair_portal_accepts_server_selected_oauth_success_anchor() {
        let runtime = CampusRuntime::new("2026-fall".to_owned(), false, String::new())
            .expect("runtime config");
        let client = runtime.identity.identity().client().clone();
        let response_url =
            reqwest::Url::parse("https://id.tsinghua.edu.cn/do/off/ui/auth/login/check").unwrap();
        let oauth = reqwest::Url::parse(
            "https://oauth.tsinghua.edu.cn/lb-auth/lbredirect?scheme=https&host=info.tsinghua.edu.cn&port=443&uri=%2Ff%2Finfo%2Fgxfw_fg%2Fcommon%2Findex%3Fticket%3Dfixture",
        )
        .unwrap();
        let submitted = format!(
            r#"<html><body>登录成功。正在重定向到 <a href="{}">continue</a></body></html>"#,
            oauth
        );

        let selected = portal_target_from_submitted_identity_evidence(
            &client,
            &response_url,
            reqwest::StatusCode::OK,
            None,
            &submitted,
        )
        .expect("reference client accepts the server-selected OAuth handoff");
        assert_eq!(selected, oauth);
        assert_eq!(
            portal_oauth_redirect_url(&selected).expect("validated OAuth handoff"),
            oauth,
            "an already-selected OAuth handoff must not be rebuilt"
        );

        for rejected in [
            "https://oauth.tsinghua.edu.cn/other?scheme=https&host=info.tsinghua.edu.cn&port=443&uri=%2Ff%2Finfo%2Fgxfw_fg%2Fcommon%2Findex",
            "https://oauth.tsinghua.edu.cn/lb-auth/lbredirect?scheme=https&host=evil.example&port=443&uri=%2Ff%2Finfo%2Fgxfw_fg%2Fcommon%2Findex",
            "https://oauth.tsinghua.edu.cn/lb-auth/lbredirect?scheme=http&host=info.tsinghua.edu.cn&port=80&uri=%2Ff%2Finfo%2Fgxfw_fg%2Fcommon%2Findex",
            "https://oauth.tsinghua.edu.cn/lb-auth/lbredirect?scheme=https&host=info.tsinghua.edu.cn&port=443&uri=https%3A%2F%2Fevil.example%2F",
            "https://user@oauth.tsinghua.edu.cn/lb-auth/lbredirect?scheme=https&host=info.tsinghua.edu.cn&port=443&uri=%2Ff%2Finfo%2Fgxfw_fg%2Fcommon%2Findex",
            "https://oauth.tsinghua.edu.cn/lb-auth/lbredirect?scheme=https&host=info.tsinghua.edu.cn&port=443&uri=%2Ff%2Finfo%2Fgxfw_fg%2Fcommon%2Findex#fragment",
        ] {
            assert!(
                portal_oauth_redirect_url(&reqwest::Url::parse(rejected).unwrap()).is_err(),
                "unsafe server-selected OAuth routes must fail closed"
            );
        }
    }

