    #[tokio::test]
    async fn backend_repair_partial_overview_never_queries_unproven_registrar() {
        let (base_url, server) = spawn_learn_runtime_fixture(false);
        let mut runtime = CampusRuntime::new("2025-2026-2".to_owned(), false, String::new())
            .expect("runtime config");
        install_fixture_learn_source(&mut runtime, &base_url);
        runtime.cache_path =
            std::env::temp_dir().join(format!("thyou-partial-{}.json", uuid::Uuid::new_v4()));
        let result = runtime
            .load_overview("2026-09-13".to_owned())
            .await
            .expect("partial overview");
        assert_eq!(result.status, "ready");
        assert_eq!(result.source, "live");
        assert!(result.overview.is_some());
        let errors = result
            .section_errors
            .expect("missing Registrar remains explicit");
        assert!(errors.schedule.is_some());
        assert!(errors.courses.is_none());
        assert!(errors.todos.is_none());
        assert!(!runtime.service_session_is_proven(ServiceId::Registrar));
        server
            .join()
            .expect("only the four expected Learn requests were received");
    }

