    #[tokio::test]
    async fn backend_repair_explicit_learn_401_invalidates_only_learn() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let base = format!("http://{}/", listener.local_addr().unwrap());
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let request = read_fixture_request(&mut stream);
            assert!(request.starts_with("GET /b/wlxt/kc/"));
            stream
                .write_all(
                    b"HTTP/1.1 401 Unauthorized\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                )
                .unwrap();
        });
        let mut runtime =
            CampusRuntime::new("2025-2026-2".to_owned(), false, String::new()).unwrap();
        install_fixture_learn_source(&mut runtime, &base);
        let source = runtime.learn_source.clone().unwrap();
        install_registrar_proof(&mut runtime, &test_user("fixture-user"), source);
        assert!(runtime.load_learn_courses().await.is_err());
        assert!(!runtime.service_session_is_proven(ServiceId::Learn));
        assert!(runtime.service_session_is_proven(ServiceId::Registrar));
        assert_eq!(runtime.status().state, "authenticated");
        server.join().unwrap();
    }

    #[tokio::test]
    async fn backend_repair_overview_expiry_uses_bounded_refresh_and_stale_fallback() {
        let server = FixtureServer::new(vec![
            Reply {
                status: 401,
                headers: String::new(),
                body: String::new(),
            },
            Reply {
                status: 401,
                headers: String::new(),
                body: String::new(),
            },
        ]);
        let base = unique_cache_base("overview-expiry-stale");
        let user = test_user("fixture-user");
        let mut runtime = CampusRuntime::new(
            "2025-2026-2".to_owned(),
            false,
            base.to_string_lossy().into_owned(),
        )
        .expect("runtime config");
        install_fixture_learn_source_for_user(&mut runtime, server.base(), &user);
        let source = runtime.learn_source.clone().expect("Learn source");
        install_registrar_proof(&mut runtime, &user, source);

        let date = NaiveDate::from_ymd_opt(2026, 9, 14).expect("date");
        let cache_path = overview_cache_path_for_account_stage(
            &base,
            &user.username,
            AcademicStage::Undergraduate,
        );
        let generated_at = Utc::now() - ChronoDuration::hours(1);
        let overview = CampusOverview {
            date,
            generated_at,
            semester: Some("2025-2026-2".to_owned()),
            course_count: 7,
            pending_todo_count: 2,
            completed_todo_count: 1,
            today_schedule: Vec::new(),
            upcoming_todos: Vec::new(),
            next_schedule: None,
        };
        let payload = CampusOverviewCachePayload {
            account_scope: cache_account_scope(&user.username),
            stage: AcademicStage::Undergraduate,
            date,
            generated_at,
            overview,
        };
        std::fs::create_dir_all(cache_path.parent().expect("cache directory")).unwrap();
        let saved_at = (Utc::now() - ChronoDuration::hours(1))
            .timestamp_millis()
            .to_string();
        let envelope = crate::cache::JsonCacheEnvelope {
            schema_version: CAMPUS_OVERVIEW_CACHE_SCHEMA_VERSION,
            service: CAMPUS_OVERVIEW_CACHE_SERVICE.to_owned(),
            saved_at,
            payload,
        };
        std::fs::write(
            &cache_path,
            serde_json::to_vec_pretty(&envelope).expect("stale overview cache encodes"),
        )
        .unwrap();

        // Pretend the shared gates already contain the single failed recovery
        // result. The overview path must reuse that bounded outcome, not open
        // another portal/login chain while selecting the stale cache.
        runtime.automatic_refresh_results.insert(
            ServiceId::Learn,
            Err(String::from("fixture learn refresh failed")),
        );
        runtime.automatic_refresh_results.insert(
            ServiceId::Registrar,
            Err(String::from("fixture registrar refresh failed")),
        );

        let result = runtime
            .load_overview(date.to_string())
            .await
            .expect("stale overview remains available after bounded expiry recovery failure");

        assert_eq!(result.source, "cache");
        assert_eq!(result.status, "stale");
        assert_eq!(
            result.overview.as_ref().map(|value| value.course_count),
            Some(7)
        );
        assert_eq!(
            server.requests().len(),
            2,
            "only the first live section probes run"
        );
        assert!(!runtime.service_session_is_proven(ServiceId::Learn));
        assert!(!runtime.service_session_is_proven(ServiceId::Registrar));
        assert_eq!(runtime.automatic_refresh_results.len(), 2);

        remove_cache_file(cache_path);
    }

