    #[tokio::test]
    async fn backend_repair_runtime_info_search_and_detail_reach_safe_dtos() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            for step in 0..4 {
                let (mut stream, _) = listener.accept().unwrap();
                let request = read_fixture_request(&mut stream);
                match step {
                    0 | 2 => {
                        assert!(request.starts_with("GET /wengine-vpn/cookie?"));
                        let body = "XSRF-TOKEN=fixture-csrf;";
                        write!(
                            stream,
                            "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                            body.len(),
                            body
                        )
                        .unwrap();
                    }
                    1 => {
                        assert!(request.starts_with(
                            "POST /target/b/xnzx/search/info/xxfb_fg/teacher/getMobilePageList?"
                        ));
                        assert!(request.contains("esParamClass="));
                        let body = r#"{"result":"success","object":{"resultsList":[{"bt":"<strong>Fixture search</strong>","url":"/article","xxid":"fixture-search-id","time":"2026-09-14 11:00:00","dwmc_show":"Fixture source","yxzd":null,"lmid":"LM_BGTG","sfsc":true}]}}"#;
                        write!(
                            stream,
                            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                            body.len(),
                            body
                        )
                        .unwrap();
                    }
                    3 => {
                        assert!(
                            request.contains("GET /target/b/info/xxfb_fg/xnzx/template/detail?")
                        );
                        assert!(request.contains("xxid=fixture-detail-id"));
                        let body = r#"{"result":"success","object":{"xxDto":{"xxid":"fixture-detail-id","bt":"Fixture detail","nr":"&lt;p&gt;Fixture body&lt;/p&gt;","fjs_template":[{"wjid":"fixture-file","wjmc":"fixture.pdf"}]}}}"#;
                        write!(
                            stream,
                            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                            body.len(),
                            body
                        )
                        .unwrap();
                    }
                    _ => unreachable!(),
                }
            }
        });

        let mut runtime = CampusRuntime::new("2026-fall".to_owned(), false, String::new()).unwrap();
        let user = test_user("fixture-user");
        install_identity(&mut runtime, &user);
        runtime
            .coordinator
            .begin_authentication(ServiceId::Info)
            .unwrap();
        let csrf = runtime
            .coordinator
            .registry()
            .bind_csrf(ServiceId::Info, CsrfToken::new("fixture-csrf").unwrap());
        runtime
            .coordinator
            .mark_authenticated(ServiceId::Info, user, None, Some(csrf), None)
            .unwrap();
        let base = format!("http://{address}/");
        runtime.info_adapter = Some(
            crate::info_session::InfoSessionAdapter::new(
                crate::info_session::InfoWebVpnConfig::new(&base, "/target").unwrap(),
                runtime.identity.transport().clone(),
            )
            .unwrap(),
        );
        runtime.info_roaming_url =
            Some(crate::info::OpaqueUrl::new(&format!("{base}target/home")).unwrap());

        let search = runtime
            .search_info_news(1, "fixture".to_owned(), Some("办公通知".to_owned()), false)
            .await
            .unwrap();
        assert_eq!(search.items.len(), 1);
        assert_eq!(search.items[0].id, "fixture-search-id");
        assert!(search.items[0].favorited);

        let detail = runtime
            .load_info_news_detail("fixture-detail-id".to_owned())
            .await
            .unwrap();
        assert_eq!(detail.id, "fixture-detail-id");
        assert_eq!(detail.title, "Fixture detail");
        assert_eq!(detail.summary, "Fixture body");
        assert_eq!(detail.attachments.len(), 1);
        assert_eq!(detail.attachments[0].name, "fixture.pdf");
        assert!(runtime.service_session_is_proven(ServiceId::Info));
        server.join().unwrap();
    }

