    #[tokio::test]
    async fn backend_repair_identity_recovery_gate_reopens_after_each_proven_cycle() {
        let mut runtime = CampusRuntime::new_with_persistence(
            "2026-fall".to_owned(),
            false,
            String::new(),
            false,
        )
        .expect("runtime config");
        let user = test_user("fixture-user");

        // Model the safe state left by a private-vault recovery: the password was
        // already read for this expiry cycle, while the opt-in itself remains
        // available for a later independent expiry. The two guards have
        // different scopes and the identity proof must release only the
        // primary-recovery guard.
        runtime.remember_credentials = true;
        runtime.credentials_persisted = true;
        runtime.credential_username = Some(user.username.clone());
        runtime.private_credential_attempted = true;

        for _ in 0..2 {
            let snapshot = runtime
                .coordinator
                .begin_authentication(ServiceId::Identity)
                .and_then(|_| {
                    runtime.coordinator.mark_authenticated(
                        ServiceId::Identity,
                        user.clone(),
                        None,
                        None,
                        None,
                    )
                })
                .expect("identity recovery proof");
            runtime.credential_recovery_attempted = true;

            runtime
                .finish_authenticated_identity_only(IdentitySessionResult {
                    snapshot,
                    identity_ticket: None,
                    trusted_device: None,
                })
                .await
                .expect("identity-only recovery should complete");

            assert!(runtime.service_session_is_proven(ServiceId::Identity));
            assert!(
                !runtime.credential_recovery_attempted,
                "the next independent Identity expiry must be eligible for one new recovery"
            );
            assert!(
                runtime.private_credential_attempted,
                "successful primary recovery must not replay the portal private-vault boundary"
            );

            runtime
                .coordinator
                .logout(ServiceId::Identity)
                .expect("end synthetic expiry cycle");
        }
    }

