    #[test]
    fn backend_repair_completed_service_factor_consumes_only_its_target_handoff() {
        let runtime = CampusRuntime::new("2026-fall".to_owned(), false, String::new()).unwrap();
        let client = runtime.identity.identity().client().clone();
        let response_url =
            reqwest::Url::parse("https://id.tsinghua.edu.cn/do/off/ui/auth/login/check").unwrap();
        let card_origin = reqwest::Url::parse(super::CAMPUS_CARD_BASE_URL).unwrap();
        let portal_response = crate::identity_execution::IdentityHttpResponse::from_parts(
            reqwest::StatusCode::OK,
            response_url.clone(),
            r#"登录成功。正在重定向到 <a href="https://info.tsinghua.edu.cn/f/info/gxfw_fg/common/index?ticket=fixture">continue</a>"#,
        );
        let card_response = crate::identity_execution::IdentityHttpResponse::from_parts(
            reqwest::StatusCode::OK,
            response_url,
            r#"登录成功。正在重定向到 <a href="https://card.tsinghua.edu.cn/login?ticket=fixture">continue</a>"#,
        );
        assert!(
            super::completed_service_second_factor_handoff(
                super::ServiceSecondFactorTarget::Portal,
                &client,
                &portal_response,
                &card_origin,
            )
            .is_some()
        );
        assert!(
            super::completed_service_second_factor_handoff(
                super::ServiceSecondFactorTarget::CampusCard,
                &client,
                &card_response,
                &card_origin,
            )
            .is_some()
        );
        assert!(
            super::completed_service_second_factor_handoff(
                super::ServiceSecondFactorTarget::CampusCard,
                &client,
                &portal_response,
                &card_origin,
            )
            .is_none()
        );
    }

