    fn remove_cache_file(path: PathBuf) {
        let directory = path.parent().map(Path::to_path_buf);
        let _ = std::fs::remove_file(path);
        if let Some(directory) = directory {
            let _ = std::fs::remove_dir_all(directory);
        }
    }

