    fn reference_factor_runtime(
        server: &crate::reference_test_support::FixtureServer,
        target: super::ServiceSecondFactorTarget,
        methods: Vec<SecondFactorMethod>,
    ) -> CampusRuntime {
        let mut runtime =
            CampusRuntime::new_with_persistence(AUTO_SEMESTER.into(), false, String::new(), false)
                .unwrap();
        let profile = runtime
            .identity
            .identity()
            .client()
            .config()
            .profile
            .clone();
        let client = crate::identity_client::IdentityClient::new(
            crate::identity_client::IdentityClientConfig::new(server.base(), profile).unwrap(),
        )
        .unwrap();
        runtime.identity = crate::identity_session::IdentitySessionOrchestrator::new(
            crate::identity_execution::IdentityExecutionClient::with_transport(
                client,
                CampusHttpTransport::with_timeout(
                    "THYou/reference-fixture",
                    Duration::from_secs(2),
                )
                .unwrap(),
            ),
        );
        install_identity(&mut runtime, &test_user("fixture-user"));
        runtime.service_second_factor = Some(super::PendingServiceSecondFactor {
            target,
            challenge: crate::protocol::SecondFactorChallenge {
                methods,
                masked_phone: Some("138****0000".into()),
                expires_at: None,
            },
        });
        runtime
    }

    #[test]
    fn backend_repair_reference_service_challenge_reaches_existing_status_dto() {
        let server = crate::reference_test_support::FixtureServer::new(vec![]);
        for target in [
            super::ServiceSecondFactorTarget::Portal,
            super::ServiceSecondFactorTarget::CampusCard,
        ] {
            let mut runtime = reference_factor_runtime(
                &server,
                target,
                vec![SecondFactorMethod::Mobile, SecondFactorMethod::Totp],
            );
            install_learn_proof(&mut runtime, &test_user("fixture-user"));
            let status = runtime.status();
            assert_eq!(status.state, "requires_second_factor");
            assert_eq!(status.second_factor_methods, vec!["mobile", "totp"]);
            assert_eq!(status.masked_phone.as_deref(), Some("138****0000"));
            assert!(!status.overview_available, "existing Dart status contract");
            assert!(runtime.service_session_is_proven(ServiceId::Identity));
            assert!(
                runtime.service_session_is_proven(ServiceId::Learn),
                "do not erase independent proof"
            );
        }
        assert!(server.requests().is_empty());
    }

    #[tokio::test]
    async fn backend_repair_reference_public_send_routes_to_pending_service() {
        use crate::reference_test_support::{FixtureServer, Reply};
        let server = FixtureServer::new(vec![Reply::json(r#"{"result":"success"}"#)]);
        let mut runtime = reference_factor_runtime(
            &server,
            super::ServiceSecondFactorTarget::Portal,
            vec![SecondFactorMethod::Mobile],
        );
        let result = runtime.send_second_factor_code("mobile".into()).await;
        assert!(
            result.is_ok(),
            "existing bridge must send the target-service challenge"
        );
        let requests = server.requests();
        assert_eq!(requests.len(), 1);
        assert!(requests[0].contains("action=SEND_CODE"));
        assert!(requests[0].contains("type=mobile"));
        assert!(runtime.service_session_is_proven(ServiceId::Identity));
    }

