    #[tokio::test]
    async fn backend_repair_reference_trusted_portal_challenge_is_not_lost() {
        use crate::reference_test_support::{FixtureServer, Reply};
        let identity = FixtureServer::new(vec![
            Reply::html(
                r#"<form method="post" action="/do/off/ui/auth/login/checkSingle"><input name="fingerPrint" value="fixture"></form>"#,
            ),
            Reply::html("<html><body>二次认证</body></html>"),
            Reply::json(r#"{"result":"success","object":{"hasWeChatBool":true,"hasTotp":true}}"#),
        ]);
        let portal = FixtureServer::new(vec![
            Reply::html(""),
            Reply {
                status: 302,
                headers: format!(
                    "Location: {}do/off/ui/auth/login/form/{PORTAL_ID_APP_ID}\r\n",
                    identity.base()
                ),
                body: String::new(),
            },
        ]);
        let oauth = FixtureServer::new(vec![]);
        let mut runtime =
            reference_factor_runtime(&identity, super::ServiceSecondFactorTarget::Portal, vec![]);
        runtime.service_second_factor = None;
        runtime.primary_password = Some("fixture-password".into());
        let portal_config = crate::webvpn_identity::WebVpnIdentityConfig::new(
            portal.base(),
            oauth.base(),
            identity.base(),
        )
        .unwrap();
        let info_config = crate::info_session::InfoWebVpnConfig::new(portal.base(), "/info/")
            .unwrap()
            .with_identity_origin(identity.base())
            .unwrap();
        let adapter = crate::info_session::InfoSessionAdapter::new(
            info_config,
            runtime.identity.transport().clone(),
        )
        .unwrap();
        assert!(
            runtime
                .ensure_portal_bootstrap_inner_with_adapter_and_config(
                    &test_user("fixture-user"),
                    &adapter,
                    &portal_config,
                )
                .await
                .is_err()
        );
        let pending = runtime
            .service_second_factor
            .as_ref()
            .expect("checkSingle can require 2FA");
        assert_eq!(pending.target, super::ServiceSecondFactorTarget::Portal);
        assert!(
            pending
                .challenge
                .methods
                .contains(&SecondFactorMethod::Totp)
        );
        let requests = identity.requests();
        assert_eq!(
            requests.len(),
            3,
            "one GET, one trusted POST, one method discovery"
        );
        assert!(!requests.iter().any(|r| r.contains("name=\"i_pass\"")));
        assert_eq!(runtime.status().state, "requires_second_factor");
    }

