    #[tokio::test]
    async fn backend_repair_reference_card_credential_form_matches_service_roam_wire() {
        use crate::reference_test_support::{FixtureServer, Reply};
        use sm2::elliptic_curve::sec1::ToSec1Point;
        let key = sm2::SecretKey::from_slice(&[1u8; 32]).unwrap();
        let public_key: String = key.public_key().to_sec1_point(false).as_bytes()[1..]
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect();
        let server = FixtureServer::new(vec![
            Reply::html(&format!(
                "<div id=\"sm2publicKey\">{public_key}</div><form method=\"post\" action=\"/do/off/ui/auth/login/check\"><input name=\"i_user\"><input type=\"password\" name=\"i_pass\"></form>"
            )),
            Reply::html("<html><body>账号或密码错误</body></html>"),
        ]);
        let mut runtime = reference_factor_runtime(
            &server,
            super::ServiceSecondFactorTarget::CampusCard,
            vec![],
        );
        runtime.service_second_factor = None;
        runtime.primary_password = Some("fixture-password".into());
        assert!(
            runtime
                .ensure_card_session(&test_user("fixture-user"))
                .await
                .is_err()
        );
        let requests = server.requests();
        assert_eq!(
            requests.len(),
            2,
            "one form GET and one credential POST, never retry"
        );
        let body = requests[1].split_once("\r\n\r\n").unwrap().1;
        let fields: std::collections::BTreeMap<String, String> =
            reqwest::Url::parse(&format!("http://fixture.invalid/?{body}"))
                .unwrap()
                .query_pairs()
                .into_owned()
                .collect();
        assert_eq!(
            fields.keys().map(String::as_str).collect::<Vec<_>>(),
            vec![
                "fingerGenPrint",
                "fingerPrint",
                "i_captcha",
                "i_pass",
                "i_user"
            ]
        );
        assert!(fields["i_pass"].starts_with("04"));
        assert!(!body.contains("fixture-password"));
    }

