    fn install_fixture_learn_source_for_user(
        runtime: &mut CampusRuntime,
        base_url: &str,
        user: &UserIdentity,
    ) {
        install_identity(runtime, user);
        let csrf = runtime.coordinator.registry().bind_csrf(
            ServiceId::Learn,
            CsrfToken::new("runtime-learn-csrf").expect("fixture CSRF"),
        );
        runtime
            .coordinator
            .begin_authentication(ServiceId::Learn)
            .expect("Learn authentication begins");
        runtime
            .coordinator
            .mark_authenticated(
                ServiceId::Learn,
                user.clone(),
                None,
                Some(csrf.clone()),
                None,
            )
            .expect("Learn authentication succeeds");

        let transport = CampusHttpTransport::with_timeout(
            "THYou/runtime-learn-contract",
            Duration::from_secs(2),
        )
        .expect("fixture transport");
        let learn = LearnClient::new(
            LearnClientConfig::new(base_url, CourseRole::Student).expect("fixture Learn config"),
        );
        let registrar = RegistrarClient::from_transport(
            RegistrarClientConfig {
                user_agent: "THYou/runtime-learn-contract".to_owned(),
                learn_base_url: base_url.to_owned(),
                registrar_base_url: base_url.to_owned(),
                ..RegistrarClientConfig::default()
            },
            transport,
        )
        .expect("fixture Registrar transport holder");
        runtime.learn_source = Some(
            runtime
                .build_learn_source(learn, registrar, csrf)
                .expect("Learn source with real todo adapter"),
        );
    }

    fn read_fixture_request(stream: &mut TcpStream) -> String {
        stream
            .set_read_timeout(Some(Duration::from_secs(2)))
            .expect("fixture request timeout");
        let mut bytes = Vec::new();
        let mut buffer = [0_u8; 4096];
        let mut header_end = None;
        let mut content_length = 0_usize;
        loop {
            let read = stream.read(&mut buffer).expect("fixture request read");
            if read == 0 {
                break;
            }
            bytes.extend_from_slice(&buffer[..read]);
            if header_end.is_none()
                && let Some(position) = bytes.windows(4).position(|window| window == b"\r\n\r\n")
            {
                let end = position + 4;
                let headers = String::from_utf8_lossy(&bytes[..position]);
                content_length = headers
                    .lines()
                    .find_map(|line| {
                        line.strip_prefix("Content-Length:")
                            .or_else(|| line.strip_prefix("content-length:"))
                    })
                    .and_then(|value| value.trim().parse().ok())
                    .unwrap_or(0);
                header_end = Some(end);
            }
            if header_end.is_some_and(|end| bytes.len() >= end + content_length) {
                break;
            }
        }
        String::from_utf8_lossy(&bytes).into_owned()
    }

    fn spawn_learn_runtime_fixture(
        fail_submitted_provider: bool,
    ) -> (String, thread::JoinHandle<()>) {
        const COURSE_PATH: &str =
            "/b/wlxt/kc/v_wlkc_xs_xkb_kcb_extend/student/loadCourseBySemesterId/2025-2026-2/zh";
        const PENDING_PATH: &str = "/b/wlxt/kczy/zy/student/zyListWj";
        const SUBMITTED_PATH: &str = "/b/wlxt/kczy/zy/student/zyListYjwg";
        const GRADED_PATH: &str = "/b/wlxt/kczy/zy/student/zyListYpg";

        let listener = TcpListener::bind("127.0.0.1:0").expect("fixture listener");
        let address = listener.local_addr().expect("fixture address");
        let server = thread::spawn(move || {
            for index in 0..4 {
                let (mut stream, _) = listener.accept().expect("fixture connection");
                let request = read_fixture_request(&mut stream);
                if index == 0 {
                    assert!(request.starts_with(&format!(
                        "GET {COURSE_PATH}?_csrf=runtime-learn-csrf HTTP/1.1"
                    )));
                } else {
                    let path = match index {
                        1 => PENDING_PATH,
                        2 => SUBMITTED_PATH,
                        3 => GRADED_PATH,
                        _ => unreachable!(),
                    };
                    assert!(
                        request
                            .starts_with(&format!("POST {path}?_csrf=runtime-learn-csrf HTTP/1.1"))
                    );
                    assert!(
                        request.contains("name=\"aoData\"")
                            && request.contains(r#""name":"wlkcid""#)
                    );
                    assert!(request.contains("7001"));
                }
                if index > 0 {
                    assert!(request.lines().any(|line| {
                        line.eq_ignore_ascii_case("cookie: fixture-session=present")
                    }));
                }

                let body = match index {
                    0 => {
                        r#"{"message":"success","resultList":[{"wlkcid":"7001","kch":"30240001","kcm":"数据结构"}]}"#
                    }
                    1 => {
                        r#"{"result":"success","object":{"aaData":[{"xszyid":"runtime-homework-1","wlkcid":"7001","bt":"待完成作业","jzsj":"2026-09-20 23:59:59","fbsj":"2026-09-10 08:00:00"}]}}"#
                    }
                    2 if fail_submitted_provider => {
                        r#"{"result":"error","message":"provider unavailable"}"#
                    }
                    2 | 3 => r#"{"result":"success","object":{"aaData":[]}}"#,
                    _ => unreachable!(),
                };
                let cookie = (index == 0)
                    .then_some("Set-Cookie: fixture-session=present; Path=/\r\n")
                    .unwrap_or("");
                let response = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n{cookie}Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                stream
                    .write_all(response.as_bytes())
                    .expect("fixture response");
            }
        });
        (format!("http://{address}/"), server)
    }

