    #[test]
    fn backend_repair_academic_failure_cleanup_keeps_partial_overview() {
        let mut runtime = CampusRuntime::new("2026-fall".to_owned(), false, String::new())
            .expect("runtime config");
        let user = test_user("fixture-user");
        install_identity(&mut runtime, &user);
        let source = install_learn_proof(&mut runtime, &user);
        install_registrar_proof(&mut runtime, &user, source);
        install_overview_resolver(&mut runtime);

        assert!(runtime.service_session_is_proven(ServiceId::Learn));
        assert!(runtime.service_session_is_proven(ServiceId::Registrar));
        assert!(runtime.status().overview_available);

        runtime.invalidate_learn_session();

        assert_eq!(
            runtime
                .coordinator
                .registry()
                .snapshot_for(ServiceId::Learn)
                .state,
            ServiceSessionState::Anonymous
        );
        assert!(runtime.learn_source.is_none());
        assert!(runtime.grades_source.is_some());
        assert!(runtime.service_session_is_proven(ServiceId::Registrar));
        assert!(runtime.resolver.is_none());
        assert!(runtime.status().overview_available);

        let source = install_learn_proof(&mut runtime, &user);
        runtime.invalidate_registrar_session();

        assert!(runtime.service_session_is_proven(ServiceId::Learn));
        assert!(runtime.learn_source.is_some());
        assert_eq!(
            runtime
                .coordinator
                .registry()
                .snapshot_for(ServiceId::Registrar)
                .state,
            ServiceSessionState::Anonymous
        );
        assert!(runtime.grades_source.is_none());
        assert!(runtime.resolver.is_none());

        drop(source);
    }

