    #[test]
    fn backend_repair_overview_cache_payload_rejects_account_stage_date_and_semester_drift() {
        let date = NaiveDate::from_ymd_opt(2026, 9, 20).expect("date");
        let overview = CampusOverview {
            date,
            generated_at: Utc::now(),
            semester: Some("2026-2027-1".to_owned()),
            course_count: 1,
            pending_todo_count: 0,
            completed_todo_count: 0,
            today_schedule: Vec::new(),
            upcoming_todos: Vec::new(),
            next_schedule: None,
        };
        let payload = CampusOverviewCachePayload {
            account_scope: cache_account_scope("fixture-user"),
            stage: AcademicStage::Undergraduate,
            date,
            generated_at: overview.generated_at,
            overview,
        };

        assert!(campus_overview_cache_payload_is_valid(
            &payload,
            "fixture-user",
            AcademicStage::Undergraduate,
            date,
            "2026-2027-1",
        ));
        assert!(!campus_overview_cache_payload_is_valid(
            &payload,
            "other-user",
            AcademicStage::Undergraduate,
            date,
            "2026-2027-1",
        ));
        assert!(!campus_overview_cache_payload_is_valid(
            &payload,
            "fixture-user",
            AcademicStage::Graduate,
            date,
            "2026-2027-1",
        ));
        assert!(!campus_overview_cache_payload_is_valid(
            &payload,
            "fixture-user",
            AcademicStage::Undergraduate,
            date + chrono::Duration::days(1),
            "2026-2027-1",
        ));
        assert!(!campus_overview_cache_payload_is_valid(
            &payload,
            "fixture-user",
            AcademicStage::Undergraduate,
            date,
            "2025-2026-2",
        ));
    }

    #[test]
    fn backend_repair_overview_cache_stale_window_is_finite_and_rejects_future_entries() {
        let now = SystemTime::UNIX_EPOCH + Duration::from_secs(10 * 24 * 60 * 60);
        let now_millis = now
            .duration_since(SystemTime::UNIX_EPOCH)
            .expect("fixture clock")
            .as_millis();
        let seven_days_ago = now_millis - Duration::from_secs(7 * 24 * 60 * 60).as_millis();
        let eight_days_ago = now_millis - Duration::from_secs(8 * 24 * 60 * 60).as_millis();

        assert!(campus_overview_cache_saved_at_is_usable(
            &seven_days_ago.to_string(),
            now,
        ));
        assert!(!campus_overview_cache_saved_at_is_usable(
            &eight_days_ago.to_string(),
            now,
        ));
        assert!(!campus_overview_cache_saved_at_is_usable(
            &(now_millis + 1).to_string(),
            now,
        ));
        assert!(!campus_overview_cache_saved_at_is_usable(
            "not-a-timestamp",
            now
        ));
    }

