    async fn backend_repair_grades_stale_cache_is_explicit_when_live_session_is_missing() {
        let base = unique_cache_base("grades-stale");
        let user = test_user("fixture-user");
        let cache_path = write_grades_cache(
            &base,
            &user.username,
            AcademicStage::Undergraduate,
            "2026-2027-1",
            Utc::now() - ChronoDuration::hours(25),
            vec![crate::api::academic::CampusGradeDto {
                course_name: "缓存成绩".to_owned(),
                credit: 3.0,
                grade: "A".to_owned(),
                grade_point: Some(4.0),
                semester: "2026-2027-1".to_owned(),
            }],
        );
        let mut runtime = CampusRuntime::new_auto_with_persistence(
            "2026-2027-1".to_owned(),
            false,
            base.to_string_lossy().into_owned(),
            false,
        )
        .expect("runtime config");
        install_identity(&mut runtime, &user);
        assert_eq!(runtime.semester, "2026-2027-1");
        assert_eq!(runtime.stage, AcademicStage::Undergraduate);
        assert_eq!(runtime.cache_path, base);
        assert_eq!(
            super::registrar_grades_cache_path(
                &runtime.cache_path,
                &user.username,
                &runtime.semester,
                runtime.stage,
                Some("first_degree"),
            ),
            cache_path
        );
        assert_eq!(
            runtime
                .coordinator
                .registry()
                .snapshot_for(ServiceId::Identity)
                .user
                .as_ref()
                .map(|value| value.username.as_str()),
            Some("fixture-user")
        );
        let envelope = JsonFileCache::<super::RegistrarGradesCachePayload>::new(
            &cache_path,
            REGISTRAR_GRADES_CACHE_SCHEMA_VERSION,
            REGISTRAR_GRADES_CACHE_SERVICE,
        )
        .read()
        .expect("grade cache reads")
        .expect("grade cache exists");
        assert!(super::registrar_grades_cache_payload_is_valid(
            &envelope.payload,
            &user.username,
            "2026-2027-1",
            AcademicStage::Undergraduate,
            Some("first_degree"),
        ));

        let report = runtime
            .load_grades()
            .await
            .expect("same-account stale grade cache should be usable");

        assert_eq!(report.source.as_deref(), Some("cache"));
        assert_eq!(report.status.as_deref(), Some("stale"));
        assert_eq!(
            report.error.as_deref(),
            Some("实时成绩暂时不可用，当前显示已验证缓存")
        );
        assert_eq!(report.courses.len(), 1);
        assert!(!runtime.service_session_is_proven(ServiceId::Registrar));
        remove_cache_file(cache_path);
    }

