    #[tokio::test]
    async fn learn_only_runtime_reads_courses_and_todos_without_registrar_proof() {
        let (base_url, server) = spawn_learn_runtime_fixture(false);
        let mut runtime = CampusRuntime::new("2025-2026-2".to_owned(), false, String::new())
            .expect("runtime config");
        install_fixture_learn_source(&mut runtime, &base_url);

        let courses = runtime
            .load_learn_courses()
            .await
            .expect("Learn course read succeeds");
        assert_eq!(courses.courses.len(), 1);
        assert_eq!(courses.courses[0].course_id, "7001");
        assert!(runtime.grades_source.is_none());
        assert_eq!(
            runtime
                .coordinator
                .registry()
                .snapshot_for(ServiceId::Registrar)
                .state,
            ServiceSessionState::Anonymous
        );

        let source = runtime
            .learn_source
            .clone()
            .expect("Learn-only source is retained");
        let todos = source
            .list_todos(TodoFilter::default())
            .await
            .expect("Learn todo read succeeds without Registrar");
        assert_eq!(todos.len(), 1);
        assert_eq!(todos[0].title, "待完成作业");
        assert_eq!(todos[0].status, crate::domain::TodoStatus::Pending);
        assert!(runtime.service_session_is_proven(ServiceId::Learn));
        assert!(!runtime.service_session_is_proven(ServiceId::Registrar));
        server.join().expect("Learn runtime fixture joins");
    }

    #[tokio::test]
    async fn learn_only_runtime_does_not_turn_todo_provider_failure_into_empty_success() {
        let (base_url, server) = spawn_learn_runtime_fixture(true);
        let mut runtime = CampusRuntime::new("2025-2026-2".to_owned(), false, String::new())
            .expect("runtime config");
        install_fixture_learn_source(&mut runtime, &base_url);

        runtime
            .load_learn_courses()
            .await
            .expect("course read succeeds before todo provider failure");
        let source = runtime
            .learn_source
            .clone()
            .expect("Learn-only source is retained");
        let error = source
            .list_todos(TodoFilter::default())
            .await
            .expect_err("provider failure must fail the ordinary todo read");
        assert!(matches!(
            error,
            crate::error::ServiceError::Adapter { message }
                if message.contains("learning todo providers failed")
                    && message.contains("business_failure")
        ));
        assert!(runtime.grades_source.is_none());
        assert!(runtime.service_session_is_proven(ServiceId::Learn));
        server.join().expect("Learn runtime failure fixture joins");
    }

