        let graduate = learn_course_list_cache_path(
            &base,
            "2026000000",
            "2026-2027-1",
            AcademicStage::Graduate,
        );
        let undergraduate = learn_course_list_cache_path(
            &base,
            "2026000000",
            "2026-2027-1",
            AcademicStage::Undergraduate,
        );
        let other_semester = learn_course_list_cache_path(
            &base,
            "2026000000",
            "2026-2027-2",
            AcademicStage::Graduate,
        );
        let other_account = learn_course_list_cache_path(
            &base,
            "2026113469",
            "2026-2027-1",
            AcademicStage::Graduate,
        );
        assert_ne!(graduate, undergraduate);
