    #[tokio::test]
    async fn load_exams_maps_the_verified_undergraduate_fixture_without_calendar_fields() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("fixture listener");
        let address = listener.local_addr().expect("fixture address");
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().expect("fixture request");
            let mut request = Vec::new();
            let mut byte = [0_u8; 1];
            while !request.ends_with(b"\r\n\r\n") {
                stream.read_exact(&mut byte).expect("fixture headers");
                request.push(byte[0]);
                assert!(request.len() < 16 * 1024, "fixture request is unbounded");
            }
            let body = r#"<html><body><table>
                <tr><th>开课系</th><th>课程号</th><th>课序号</th><th>课程名</th><th>课程分类</th><th>教师</th><th>人数</th><th>考试日期</th><th>考场</th></tr>
                <tr><td>计算机系</td><td>30240043</td><td>01</td><td>程序设计基础</td><td>必修</td><td>教师甲</td><td>30</td><td>06.22 一 下午</td><td>六教6A201</td></tr>
            </table></body></html>"#;
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=UTF-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                body.len(),
                body
            );
            stream
                .write_all(response.as_bytes())
                .expect("fixture response");
            String::from_utf8(request)
                .expect("fixture request UTF-8")
                .lines()
                .next()
                .and_then(|line| line.split_whitespace().nth(1))
                .unwrap_or_default()
                .to_owned()
        });

        let mut runtime = CampusRuntime::new("2026-2027-1".to_owned(), false, String::new())
            .expect("runtime config");
        let user = test_user("fixture-user");
        install_identity(&mut runtime, &user);
        let csrf = runtime.coordinator.registry().bind_csrf(
            ServiceId::Learn,
            crate::protocol::CsrfToken::new("learn-csrf-fixture").expect("csrf fixture"),
        );
        let source = test_exam_source(&format!("http://{address}/"), csrf);
        install_registrar_proof(&mut runtime, &user, source);

        let report = runtime
            .load_exams(String::new(), String::new())
            .await
            .expect("verified undergraduate exam fixture");
        assert_eq!(report.stage, "undergraduate");
        assert_eq!(report.exam_count, 1);
        assert_eq!(report.exams.len(), 1);
        let exam = &report.exams[0];
        assert_eq!(exam.course_code, "30240043");
        assert_eq!(exam.course_sequence, "01");
        assert_eq!(exam.course_name, "程序设计基础");
        assert_eq!(exam.exam_month, 6);
        assert_eq!(exam.exam_day, 22);
        assert_eq!(exam.exam_weekday, "monday");
        assert_eq!(exam.exam_session, "afternoon");
        assert_eq!(exam.schedule_raw, "06.22 一 下午");
        assert_eq!(exam.location, "六教6A201");
        assert_eq!(exam.headcount, Some(30));
        assert_eq!(
            server.join().expect("fixture server"),
            "/jxmh.do?url=%2Fjxmh.do&m=bks_ksSearch"
        );
    }

