    #[tokio::test]
    async fn auto_semester_uses_the_authenticated_learn_current_id() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("listener");
        let address = listener.local_addr().expect("address");
        let server = thread::spawn(move || {
            let current_course_home = r#"<html><head><meta name="_csrf" content="current-csrf"></head><body>课程</body></html>"#;
            let semester_list_course_home = r#"<html><head><meta name="_csrf" content="semester-list-csrf"></head><body>课程</body></html>"#;
            let responses = [
                ("/f/wlxt/index/course/student/index", current_course_home),
                (
                    "/b/kc/zhjw_v_code_xnxq/getCurrentAndNextSemester?_csrf=current-csrf",
                    r#"{"message":"success","result":{"id":"2026-2027-1","kssj":"2026-09-01 00:00:00","jssj":"2027-01-31 00:00:00","xnxq":"2026-2027-1"}}"#,
                ),
                (
                    "/f/wlxt/index/course/student/index",
                    semester_list_course_home,
                ),
                (
                    "/b/wlxt/kc/v_wlkc_xs_xktjb_coassb/queryxnxq?_csrf=semester-list-csrf",
                    r#"["2025-2026-2","2026-2027-1","2026-2027-2"]"#,
                ),
            ];
            for (path, body) in responses {
                let (mut stream, _) = listener.accept().expect("connection");
                let mut request = Vec::new();
                let mut buffer = [0_u8; 1024];
                loop {
                    let read = stream.read(&mut buffer).expect("request");
                    request.extend_from_slice(&buffer[..read]);
                    if request.windows(4).any(|window| window == b"\r\n\r\n") {
                        break;
                    }
                }
                let request = String::from_utf8_lossy(&request);
                assert!(
                    request.starts_with(&format!("GET {path} HTTP/1.1")),
                    "unexpected request: {request}"
                );
                let response = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                stream.write_all(response.as_bytes()).expect("response");
            }
        });

        let base = format!("http://{address}/");
        let learn = LearnClient::new(
            LearnClientConfig::new(&base, CourseRole::Student).expect("learn config"),
        );
        let transport =
            CampusHttpTransport::with_timeout("THYou/test", std::time::Duration::from_secs(5))
                .expect("transport");
        let mut runtime = CampusRuntime::new(AUTO_SEMESTER.to_owned(), false, String::new())
            .expect("runtime config");
        let user = test_user("fixture-user");
        install_identity(&mut runtime, &user);
        let initial_csrf = runtime.coordinator.registry().bind_csrf(
            ServiceId::Learn,
            CsrfToken::new("handoff-csrf").expect("fixture csrf"),
        );
        runtime
            .coordinator
            .begin_authentication(ServiceId::Learn)
            .expect("learn authentication begins");
        runtime
            .coordinator
            .mark_authenticated(
                ServiceId::Learn,
                user.clone(),
                None,
                Some(initial_csrf),
                None,
            )
            .expect("learn authentication succeeds");

        runtime
            .resolve_semester(&user, &learn, &transport)
            .await
            .expect("live semester discovery");

        assert_eq!(runtime.semester, "2026-2027-1");
        assert_eq!(runtime.semester_config, AUTO_SEMESTER);
        assert_eq!(
            runtime
                .coordinator
                .bound_csrf(ServiceId::Learn)
                .expect("latest Learn CSRF")
                .as_csrf_token()
                .as_str(),
            "semester-list-csrf"
        );
        server.join().expect("server");
    }

